(window.GIM_TS=window.GIM_TS||{})["Makkot.1"]={"from":24,"a":[["\u0003כדאמרינן מעיקרא\u0004 \u0005[כמו שאמרנו מתחילה],\u0006 שחייבי כריתות ישנם בכלל מלקות משום \u0003שאם עשו תשובה, בית דין של מעלה מוחלין להן,\u0004 ולכן אין כאן \"שתי רשעיות\", כדי לפוטרם ממלקות. \u0003מאי אמרת\u0004 \u0005[מה אתה אומר],\u0006 מה טענת כנגד זה? \u0003הא\u0004 \u0005[הרי]\u0006 עדיין \u0003לא עבוד\u0004 \u0005[עשו]\u0006 \u0003תשובה\u0004 — יש לומר כי מכל מקום \u0003לא פסיקא מילתא\u0004 \u0005[חתוך,\u0006 מוחלט \u0005הדבר]\u0006 \u0003לכרת,\u0004 וכיון שאין כאן כרת ברור — אין פוטרים אותם ממלקות משום כך.","שנינו בברייתא לעיל, \u0003ר' יצחק אומר:\u0004 כל \u0003חייבי כריתות\u0004 המנויים בפרשת אחרי מות (ויקרא יח) \u0003בכלל\u0004 אחד \u0003היו,\u0004 ובכללם אחותו, \u0003ולמה יצאת\u0004 שוב \u0003כרת באחותו\u0004 בפרשת קדושים (ויקרא כ, יז) — \u0003לדונו בכרת ולא במלקות.\u0004 שלדעתו גם חייבי כריתות, כמו חייבי מיתות בית דין, אינם לוקים.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כלומר, ר' ישמעאל ור' עקיבא, שאינם סבורים כך, אלא שחייבי כריתות לוקים, \u0003כרת\u0004 שנאמרה במיוחד \u0003באחותו למה לי\u0004 ומה הוא בא ללמד? ומשיבים: \u0003לחלק\u0004 כלומר, ללמד שיש עונש נפרד על כל אחת מן העריות (ושאר הכריתות) לחוד, \u0003וכ\u0004דברי \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן: שאם עשאן כולם,\u0004 שעבר על כל העבירות המנויות שם \u0003בהעלם\u0004 (חוסר ידיעה) \u0003אחד,\u0004 שעשה את כולן בשגגה אחת — \u0003חייב\u0004 להביא קרבן \u0003על כל אחת ואחת\u0004 מהן, משום שיש חיוב כרת בכל אחת לעצמה.","ושואלים: \u0003ור' יצחק,\u0004 הלומד מכרת האמור באחותו את שיטתו, דין זה \u0003לחלק\u0004 לקרבנות, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 \u0003מ\u0004מקור אחר, שנאמר \u0003\"ואל אשה בנדת טמאתה\u0004 לא תקרב\" (ויקרא יח, יט), שמייתור הלשון הזה יש ללמוד \u0003לחייב על כל אשה ואשה.\u0004","ושואלים: \u0003ורבנן נמי תיפוק ליה מהא\u0004 \u0005[וחכמים גם כן, תצא להם\u0006 הלכה זו \u0005מ\u0006פסוק \u0005זה]\u0006 ולא מכרת האמור באחותו! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן כך\u0006 הוא \u0005גם כן],\u0006 שגם הם למדים מפסוק זה לחלק בקרבנות. \u0003ו\u0004חוזרת השאלה: \u0003אלא\u0004 לשיטתם, \u0003כרת\u0004 שכתוב \u0003אחותו למה לי?\u0004 ומשיבים: \u0003לחייבו\u0004 שלושה קרבנות נפרדים אם בא \u0003על אחותו ועל אחות אביו ועל אחות אמו\u0004 בהעלם אחד.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, \u0003הרי גופין מוחלקים\u0004 שהרי הן שלוש נשים נפרדות, \u0003הרי שמות מוחלקין\u0004 שיש כאן שלוש עבירות שונות, ומה החידוש בדבר? \u0003אלא, לחייבו\u0004 שלושה קרבנות \u0003על אחותו, שהיא\u0004 גם \u0003אחות אביו, שהיא\u0004 גם \u0003אחות אמו.\u0004 ומסבירים: \u0003והיכי משכחת לה\u0004 \u0005[ואיך אתה מוצא אותה]\u0006 שיהיה דבר כזה? \u0003ברשיעא בר רשיעא\u0004 \u0005[ברשע בן רשע].\u0006 כיצד? בא אדם על אמו, והוליד ממנה שתי בנות, וחזר ובא על אחת מהבנות הללו, והוליד ממנה בן, ואותו בן בא על אחות אמו, שהיא גם אחותו (שהרי היא בת אביו) וגם אחות אביו (שמצד אמה היא אחות אביו, אחות האיש שבא על אמו).","ושואלים: \u0003ור' יצחק הא מנא ליה\u0004 \u0005[\u0006דבר \u0005זה מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר \u0003מקל וחומר, דתניא\u0004 \u0005[\u0006כמו \u0005ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' עקיבא: שאלתי את רבן גמליאל ור' יהושע באיטליז\u0004 (מקום ממכר הבשר) \u0003של\u0004 העיר \u0003עימאום,\u0004 בשעה \u0003שהלכו\u0004 שניהם \u0003ליקח\u0004 (לקנות) \u0003בהמה ל\u0004צורך \u0003משתה\u0004 (סעודת החתונה) של \u0003בנו של רבן גמליאל.\u0004 וכך היתה השאלה: \u0003הבא על אחותו שהיא אחות אביו שהיא אחות אמו, מהו\u0004 דינו לגבי קרבן? האם \u0003[אינו] חייב על כולן אלא אחת, או חייב על כל אחת ואחת?\u0004","\u0003אמרו לו: זו לא שמענו,\u0004 לא קיבלנו מסורת בהלכה מסויימת זו, \u0003אבל שמענו\u0004 הלכה בענין דומה: \u0003הבא על חמש נשים נדות בהעלם אחד, שחייב\u0004 להביא קרבן חטאת \u0003על כל אחת ואחת\u0004 מהן, \u0003ונראין דברים\u0004 לגבי המקרה ששאלת, שחייב על כל אחת \u0003מקל וחומר,\u0004 כיצד? \u0003ומה נדה שהיא שם אחד\u0004 כלומר סוג אחד של איסור — \u0003חייב על כל אחת ואחת, כאן\u0004 באשה זו \u0003ששלשה שמות\u0004 (איסורים) הן — \u0003לא כל שכן\u0004 שיהיה חייב עליה שלוש חטאות?","ומסבירים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 הסבורים שצריך ללמוד דבר זה מפסוק מפורש, סבורים כי \u0003קל וחומר פריכא\u0004 \u0005[שביר]\u0006 \u0003הוא,\u0004 שאינו קל וחומר שעומד בפני ביקורת, שהרי אפשר לטעון כנגדו: \u0003מה לנדה\u0004 — \u0003שכן גופין מוחלקין,\u0004 שהרי מדובר כשבא על נשים שונות, מה שאין כן במקרה שלנו שמדובר באשה אחת.","ושואלים: \u0003ולאידך נמי\u0004 \u0005[ול\u0006שיטת \u0005האחר,\u0006 ר' יצחק, \u0005גם כן],\u0006 \u0003האי\u0004 \u0005[הרי]\u0006 \u0003ודאי קל וחומר פריכא\u0004 \u0005[שביר]\u0006 \u0003הוא,\u0004 שאי אפשר ללמוד ממנו! \u0003אלא,\u0004 צריך לומר שדין זה, לחייב שלוש חטאות על אחותו שהיא גם אחות אביו וגם אחות אמו, \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 \u0003מ\"אחתו\" דסיפא\u0004 \u0005[שבסוף\u0006 אותו פסוק\u0005].\u0006 שנאמר בתחילה \"ואיש אשר יקח את אחותו בת אביו או בת אמו... ונכרתו\", ואחר כך נאמר \"ערות אחותו גילה עוונו ישא\" (ויקרא כ, יז), וחזרה זו על המלה \"אחותו\", באה ללמד שחייב על כל איסור ואיסור לעצמו.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 שלמדו דין זה מ\"אחותו\" הראשון, \u0003\"אחותו\" דסיפא\u0004 \u0005[שבסוף]\u0006 \u0003למה לי,\u0004 מה הוא בא ללמד? ומשיבים: \u0003לחייבו על אחותו\u0004 שהיא גם \u0003בת אביו ו\u0004גם \u0003בת אמו, לומר שאין עונשין מן הדין\u0004 (מקל וחומר). שהרי פרטה התורה עונש לגבי אחותו בת אביו לחוד, וגם לגבי אחותו בת אמו לחוד, ומכל מקום צריך ללמדנו שאם אחות זו היא גם בת אביו וגם בת אמו חייב עליה.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יצחק\u0005]\u0006 שלמד מכתוב זה דבר אחר, מנין לו שחייב על אחותו מאב ומאם? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003גמר\u0004 \u0005[\u0006הריהו \u0005למד]\u0006 כעין גזירה שווה \u0003עונש מאזהרה,\u0004 שכשם שבאזהרה= באיסור למדנו שיש איסור גם באחותו בת אביו ובת אמו, כן הוא גם בעונש. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר ל"],["\u0003מ\"אחותו\" דרישא\u0004 \u0005[שבתחילת\u0006 הפסוק\u0005]\u0006 (ויקרא כ, יז), שהיה יכול להיכתב \"כי יקח את בת אביו או בת אמו\" בלי להזכיר את המלה \"אחותו\", ומייתור המלה הוא למד עונש לאחותו בת אביו ואמו.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 סבור: כיון שייתור המלה \"אחותו\" אינו מלמד לעניינו, יש ללמוד ממנו לענין אחר, \u0003ההוא\u0004 \u0005[אותו]\u0006 כתוב \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לענין אחר, \u0003לחלק\u0004 שיהיה דין \u0003כרת\u0004 נפרד, וחיוב קרבן חטאת נפרד בשגגה, גם \u0003למפטם\u0004 (רוקח) שמן המשחה, \u0003ו\u0004גם \u0003לסך\u0004 משמן המשחה, למרות שהכתוב כולל את שניהם בכרת אחד, שנאמר לגבי שמן המשחה \"איש אשר ירקח כמוהו ואשר יתן ממנו על זר ונכרת מעמיו\" (שמות ל, לג).","\u0003ואידך סבר\u0004 \u0005[והאחר,\u0006 ר' יצחק, \u0005סבור]\u0006 בענין זה \u0003כ\u0004דברי \u0003ר' אלעזר אמר ר' הושעיא.\u0004 ש\u0003אמר ר' אלעזר אמר ר' הושעיא:\u0004 כלל הוא, \u0003כל מקום שאתה מוצא שני לאוין\u0004 מחולקים, \u0003וכרת אחד\u0004 שנאמר על שניהם, הכוונה היא ש\u0003חלוקין הן לקרבן,\u0004 שאם עשה את שניהם בשגגה מביא שני קרבנות. ולכן אין צורך בכתוב מיוחד בענין מפטם וסך.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לא סבר לה\u0004 \u0005[אינו סבור\u0006 בענין זה\u0005]\u0006 \u0003כר' אלעזר, ונפקא ליה\u0004 \u0005[ויוצא לו]\u0006 חילוק חטאות במפטם וסך בשמן המשחה \u0003מ\u0004ייתור אחר, והוא הכתוב \u0003\"ואיש אשר ישכב את אשה דוה...\u0004 ונכרתו שניהם\" (ויקרא כ, יח) שנאמר בה עונש כרת בנפרד, למרות שהיא נכללת בתוך כל העבירות שחייבים עליהן כרת, ואם אינו ענין לגופה תנהו ענין למפטם וסך.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 מה הוא לומד מכאן — \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 \u0003ל\u0004כמו שאמר \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מנין שאין האשה טמאה\u0004 טומאת נדה \u0003עד שיצא מדוה\u0004 (דם הנדה) \u0003דרך ערותה,\u0004 שאם יצא דרך מקום אחר בגוף אינה טמאה? \u0003שנאמר \"ואיש אשר ישכב את אשה דוה וגלה את ערותה\"\u0004 (ויקרא כ, יח), \u0003מלמד שאין האשה טמאה עד שיצא מדוה דרך ערותה\u0004 דווקא, ולא ממקום אחר.","שנינו במשנה: \u0003וטמא שאכל את הקדש,\u0004 והבא למקדש טמא, שהם לוקים. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 בדין \u0003הבא למקדש טמא,\u0004 שכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 בתורה \u0003עונש\u0004 לדבר זה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 גם \u0003אזהרה\u0004 (קביעת איסור) על כך. ומפרטים: \u0003עונש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"את משכן ה' טמא ונכרתה\"\u0004 (במדבר יט, יג). \u0003אזהרה,\u0004 שיש איסור בדבר — שנאמר \u0003\"ולא יטמאו את מחניהם\"\u0004 (במדבר ה, ג). \u0003אלא טמא שאכל את הקדש, בשלמא\u0004 \u0005[נניח]\u0006 \u0003עונש\u0004 אכן \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003\"והנפש אשר תאכל בשר מזבח השלמים אשר לה' וטמאתו עליו ונכרתה\"\u0004 (ויקרא ז, כ), \u0003אלא אזהרה,\u0004 האיסור על כך, \u0003מנין?\u0004","\u0003ריש לקיש אומר:\u0004 הדבר נלמד ממה שנאמר ביולדת, קודם שתטהר לגמרי, \u0003\"בכל קדש לא תגע\"\u0004 (ויקרא יב, ד), שכוונתו אינה נגיעה סתם, אלא אכילה.","\u0003ר' יוחנן אומר, תני\u0004 \u0005[שנה]\u0006 החכם \u0003ברדלא \u0004\u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של \u0003\"טומאתו\" \"טומאתו\", כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בטמא שאכל קדשים \u0003\"וטמאתו עליו ונכרתה\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בטמא הנכנס למקדש \u0003\"טמא יהיה עוד טמאתו בו\"\u0004 (במדבר יט, יג), \u0003מה להלן\u0004 בטמא הנכנס למקדש — יש \u0003עונש ואזהרה\u0004 (כמבואר לעיל), \u0003אף כאן\u0004 בטמא האוכל קודש, למדים שיש \u0003עונש ואזהרה.\u0004","ומבררים את השיטות: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מובן הדבר, מדוע \u0003ריש לקיש לא אמר כר' יוחנן,\u0004 שמקור הדין הוא בגזירה שווה — כי \u0003גזירה שוה\u0004 זו \u0003לא גמיר\u0004 \u0005[קיבל במסורת]\u0006 מרבו, ואין אדם למד גזירה שווה מעצמו. \u0003אלא ר' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כריש לקיש,\u0004 שמקור האיסור לטמא שאכל את הקודש, הוא \"בכל קדש לא תגע\", שהרי זה לכאורה ראיה פשוטה יותר? ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 ר' יוחנן: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 אינו אזהרה על אכילת קדש בטומאה, אלא הוא \u0003אזהרה ל\u0004אוכל \u0003תרומה\u0004 בטומאה.","ושואלים: \u0003וריש לקיש,\u0004 באמת \u0003אזהרה לתרומה\u0004 שלא יאכל בטומאה, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 הדבר \u0003מ\u0004מה שנאמר \u0003\"איש איש מזרע אהרן והוא צרוע או זב\u0004 בקדשים לא יאכל עד אשר יטהר\" (ויקרא כב, ד), והניסוח \"מזרע אהרן\" מורה שהאיסור חל על כל מי שמזרעו, גם נשים, ולפיכך יש לברר: \u0003אי זהו דבר שהוא שוה ב\u0004כל \u0003זרעו של אהרן,\u0004 שכן בקדשים יש דברים שאין בת הכהן אוכלת — \u0003הוי אומר זו תרומה.\u0004 ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוחנן\u0005]\u0006 מה הוא למד מכתוב זה? ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 נאמר \u0003ל\u0004איסור \u0003אכילה\u0004 של תרומה, \u0003והא\u0004 \u0005[וזה]\u0006 הכתוב \"בכל קדש לא תגע\" — \u0003ל\u0004איסור \u0003נגיעה.\u0004","ושואלים: \u0003וריש לקיש האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"בכל קדש לא תגע\"\u0004 (ויקרא יב, ד) \u0003להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמד, לטמא שאכל את הקודש? הלא \u0003ההוא\u0004 \u0005[אותו]\u0006 כתוב \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמד כפשוטו, \u0003לטמא שנגע בקדש! דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בדבר זה: \u0003טמא שנגע בקדש, ריש לקיש אומר: לוקה\u0004 על כך, \u0003ר' יוחנן אומר: אינו לוקה.\u0004 ופירשו את שיטותיהם, \u0003ריש לקיש אומר: לוקה,\u0004 שהרי נאמר \u0003\"בכל קדש לא תגע\"\u0004 (ויקרא יב, ד). \u0003ר' יוחנן אומר: אין לוקה,\u0004 שלדעתו \u0003ההוא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 \u0003אזהרה לתרומה הוא דאתא\u0004 \u0005[שבא]\u0006 ללמד!","ומשיבים: לדעת ריש לקיש, שני הדברים נלמדו מפסוק זה, דין \u0003טמא שנגע בקדש\u0004 נלמד \u0003מדאפקיה רחמנא\u0004 \u0005[מ\u0006מה \u0005שהוציאה\u0006 שכתבה \u0005אותו התורה]\u0006 \u0003בלשון נגיעה, אזהרה לאוכל\u0004 בטומאה נלמדה ממה ש\u0003אתקוש\u0004 \u0005[הוקשו\u0006 הושוו\u0005]\u0006 בפסוק זה \u0003קדש למקדש,\u0004 כמבואר להלן.","ושואלים: \u0003ואכתי להכי\u0004 \u0005[ועדיין, לכך,\u0006 לצורך זה\u0005]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 הפסוק? הלא \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 לריש לקיש, ללמד \u0003ל\u0004ענין \u0003טמא שאכל בשר קדש לפני זריקת דמים\u0004 על המזבח, כשעדיין לא הותר בשר זה באכילה! \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה זו: \u0003טמא שאכל בשר קדש לפני זריקת דמים, ריש לקיש אומר: לוקה\u0004 על כך, \u0003ר' יוחנן אומר: אינו לוקה.\u0004","\u0003ריש לקיש אומר: לוקה,\u0004 שהרי נאמר \u0003\"בכל קדש לא תגע\",\u0004 וכיון שנאמר הדבר בלשון כוללת, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003לפני זריקה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003לאחר זריקה. ר' יוחנן אומר: אינו לוקה.\u0004 ומסבירים, \u0003ר' יוחנן לטעמיה\u0004 \u0005[לשיטתו]\u0006 לעיל, שמקור האיסור הוא בגזירה שווה, ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"טומאתו\" \"טומאתו\", וכי כתיב\u0004 \u0005[וכאשר נאמר]\u0006 \u0003\"טומאתו\"\u0004 בענין אכילת בשר קודש (ויקרא ז, כ) — \u0003לאחר זריקה הוא דכתיב\u0004 \u0005[שנאמר]!\u0006 ומשיבים: לדעת ריש לקיש, \u0003ההיא\u0004 \u0005[אותה\u0006 הלכה\u0005]\u0006 \u0003מ\"בכל קדש\" נפקא\u0004 \u0005[יוצאת],\u0006 שלשון הריבוי \"כל\" באה לרבות גם בשר קדש לפני זריקה.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003ריש לקיש:\u0004 נאמר \u0003\"בכל קדש לא תגע\"\u0004 — הרי זו \u0003אזהרה לאוכל. אתה אומר אזהרה לאוכל, או אינו אלא\u0004 כפשוטו \u0003אזהרה לנוגע? תלמוד לומר \"בכל קדש לא תגע ואל המקדש\u0004 לא תבוא\" (ויקרא ז, כ), \u0003מקיש\u0004 (משווה) הכתוב באיסורו של הטמא \u0003קדש למקדש, מה מקדש\u0004 — \u0003דבר שיש\u0004 \u0003בו\u0004 בעונשו \u0003נטילת נשמה\u0004 (שהרי עונשו של הנכנס למקדש בטומאה הוא כרת) — \u0003אף כל\u0004 שהוזכר באותו פסוק, הוא \u0003דבר שיש בו נטילת נשמה\u0004 (עונש כרת), \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003בנגיעה\u0004 — \u0003מי איכא\u0004 \u0005[האם יש\u0006 בה\u0005]\u0006 \u0003נטילת נשמה? אלא\u0004 ודאי מדבר הכתוב \u0003באכילה.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל לא תעשה שקדמו עשה\u0004 אינו בכלל \"לאו הניתק לעשה\" (שהוא לאו שיש אחריו מצות עשה המורה מה לעשות אחר כך כדי לתקן מה שעשה), ולכל הדעות \u0003לוקין עליו. ל\u0004"],["\u0003אמרו לו: אמרת\u0004 הלכה זו? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא. אמר רבה\u0004 בלשון שבועה: \u0003האלהים! אמרה\u0004 את ההלכה הזו, \u0003וכתיבא\u0004 \u0005[וכתובה]\u0006 הלכה זו בתורה, \u0003ותנינא\u0004 \u0005[ו\u0006כן \u0005שנינו]\u0006 בדברי חכמים; \u0003כתיבא\u0004 \u0005[כתובה]\u0006 — שנאמר \u0003\"וישלחו מן המחנה\u0004 כל צרוע וכל זב... \u0003ולא יטמאו את מחניהם\"\u0004 (במדבר ה, ב— ד), הרי שיש כאן מצות לא תעשה שעוברים הטמאים, ומצות עשה לשלח את הטמאים. ומכל מקום הואיל והעשה קודם ללאו, ומתקיים גם בלעדיו — לוקים על הלאו, שהרי \u0003תנינא\u0004 \u0005[ושנינו]\u0006 במשנתנו בכלל הלוקים: \u0003הבא למקדש טמא.\u0004","ושואלים: \u0003אלא מאי טעמא קא הדר ביה\u0004 \u0005[מה טעם חזר בו]?\u0006 ומשיבים: \u0003משום דקשיא ליה\u0004 \u0005[שהיה קשה לו]\u0006 מדין \u0003אונס\u0004 נערה בתולה, שחייב מן התורה לשאתה לאשה, ונאסר עליו לשלחה כל ימיו. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אונס שגירש\u0004 את אשתו, \u0003אם ישראל הוא\u0004 — \u0003מחזיר\u0004 אותה, \u0003ואינו לוקה\u0004 על מה שגירש ועבר על \"לא יוכל שלחה כל ימיו\" (דברים כב, כט). \u0003אם כהן הוא,\u0004 שאינו יכול להחזירה, שהרי אסור לכהן לשאת גרושה — \u0003לוקה\u0004 משום לאו זה, \u0003ואינו מחזיר.\u0004","ומעתה נברר: \u0003אם ישראל הוא\u0004 — \u0003מחזיר ואינו לוקה, אמאי\u0004 \u0005[מדוע]?\u0006 הלא \u0003לא תעשה שקדמו עשה הוא,\u0004 שהרי נאמרה תחילה מצות עשה \"ולו תהיה לאשה\" (דברים כב, כט), ורק אחר כך נאמר \"לא יוכל שלחה\", \u0003ו\u0004כיון שעבר והוציאה \u0003לילקי\u0004 \u0005[שילקה]\u0006 על כך! ומכאן שאין לוקים על לאו כזה.","\u0003אמר עולא\u0004 בדחיית קושי זה: מצות העשה שבאונס אינה עשה שקודם ללאו, אלא היא עשה הבא אחרי הלאו ומנתק אותו, לפי שהוא בא במקרה שכבר נשא את אנוסתו וגירשה. וההוכחה לכך: ראוי היה לכאורה ש\u0003לא יאמר\u0004 הכתוב \u0003\"לו תהיה לאשה\"\u0004 (דברים כב, כט) \u0003באונס, וליגמר\u0004 \u0005[ושנלמד]\u0006 את ההלכה הזו \u0003ממוציא שם רע\u0004 על אשתו שזנתה קודם נישואיה, בקל וחומר: \u0003ומה מוציא שם רע שלא עשה מעשה\u0004 אלא רק דיבר בפיו — \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ולו תהיה לאשה\"\u0004 (דברים כ\"ט יט), \u0003אונס\u0004 שעשה מעשה בפועל של אונס — \u0003לא כל שכן\u0004 שחייב לשאתה?","אם כן \u0003למה נאמר\u0004 דין זה גם באונס? אלא \u0003אם אינו ענין לפניו\u0004 לעצם ההלכה שחייב לשאת אותה לאחר שנאנסה על ידו, \u0003תנהו ענין לאחריו\u0004 לאחר שנשאה, לומר \u0003שאם גירש\u0004 אותה לאחר מכן \u0003יחזיר.\u0004 ואם כן \"ולו תהיה לאשה\" אינו קודם ללאו של \"לא יוכל שלחה\", אלא בא לתקן אותו.","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 אין זו ראיה, שהרי \u0003אונס ממוציא שם רע לא גמר\u0004 \u0005[אינו\u0006 יכול \u0005ללמוד],\u0006 משום \u0003דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לשבור]\u0006 את הקל וחומר, ולומר: \u0003מה למוציא שם רע\u0004 שהחמיר בו הכתוב יותר מבאונס, \u0003שכן לוקה ומשלם,\u0004 שלא ככלל הרגיל שאין אדם נענש בשני עונשים על אותה עבירה!","ומסבירים: \u0003אלא,\u0004 כך יש לומר: \u0003לא יאמר \"לו תהיה לאשה\" במוציא שם רע, וליגמר\u0004 \u0005[ושילמד]\u0006 הלכה זו \u0003מאונס\u0004 בקל וחומר: \u0003ומה אונס שאינו לוקה ומשלם,\u0004 בכל זאת \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ולו תהיה לאשה\", מוציא שם רע לא כל שכן? ו\u0004אם כן \u0003למה נאמר\u0004 \"ולו תהיה לאשה\" במוציא שם רע? אלא, \u0003אם אינו ענין למוציא שם רע\u0004 — \u0003תנהו ענין לאונס,\u0004 ו\u0003אם אינו ענין לפניו\u0004 שצריך לשאתה, שהרי כבר נאמר בו הדבר במפורש — \u0003תנהו ענין לאחריו,\u0004 שאם נשאה וגירשה — חייב להחזירה. ואם כן אין זה לאו שקדמו עשה, ולכן אינו לוקה.","ודוחים ראיה זו: \u0003ומוציא שם רע מאונס נמי לא גמר\u0004 \u0005[גם כן אינו\u0006 יכול \u0005ללמוד]\u0006 משום \u0003דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לשבור]\u0006 את ההשוואה, ולומר, כפי שכבר אמרנו לעיל: \u0003מה לאונס\u0004 — \u0003שכן עשה מעשה,\u0004 ואילו מוציא שם רע רק דיבר!","ומציעים: \u0003אלא\u0004 מכאן יש ראיה: \u0003לא יאמר \"לו תהיה לאשה\" במוציא שם רע,\u0004 שביטוי זה מיותר לגמרי, \u0003שהרי אשתו היא,\u0004 וצריך היה לומר רק שאסור לו לגרשה. אם כן \u0003למה נאמר? אם אינו ענין למוציא שם רע תנהו ענין לאונס, ואם אינו ענין לפניו תנהו ענין לאחריו.\u0004 והואיל ואין העשה קודם ללאו — לכן אין לוקים עליו.","ומקשים על לימוד זה: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך, \u0003אם אינו ענין לפניו\u0004 של \u0003מוציא שם רע,\u0004 שהרי אשתו היא — \u0003תנהו ענין לאחריו דידיה\u0004 \u0005[שלו],\u0006 של מוציא שם רע, שגם אם עבר וגירש את אשתו ועבר על \"לא יוכל לשלחה כל ימיו\", שחייב לשאתה, \u0003דלא לקי\u0004 \u0005[שאינו לוקה]\u0006 משום שעשה זה מתקן את הלאו, ואינו קודם לו. אבל לגבי אונס — אין עשה לשאתה לאחר שגירשה, אלא קודם לכן, ואף על פי כן אינו לוקה!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן],\u0006 \u0003ו\u0004אולם \u0003אתי\u0004 \u0005[בא]\u0006 \u0003אונס וגמר מיניה\u0004 \u0005[ולמד ממנו]\u0006 שקיים בו אותו דין. ושואלים: \u0003במאי גמר מיניה\u0004 \u0005[במה\u0006 באיזו דרך \u0005למד ממנו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בקל וחומר אי\u0004 \u0005[אם]\u0006 \u0003ב\"מה מצינו\",\u0004 והרי בשתי דרכים אלה \u0003איכא למיפרך כדפרכינן\u0004 \u0005[יש\u0006 מקום \u0005להקשות כפי שהקשינו\u0006 כבר\u0005]:\u0006 \u0003מה למוציא שם רע\u0004 — \u0003שכן לא עשה מעשה!\u0004","\u0003אלא אמר רבא:\u0004 מנין שיש מצוה על האונס להחזיר את אנוסתו שגירשה, שהיא מנתקת את הלאו של \"לא יוכל שלחה\" — מייתור המלים \"כל ימיו\", ש\u0003כל ימיו,\u0004 גם לאחר שנשאה לאשה, הריהו מצווה \u0003בעמוד והחזר\u0004 במקרה שגירשה, ולכן אינו לוקה. ומוסיפים: \u0003וכן, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: כל ימיו בעמוד והחזר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא,\u0004 שיש לשאול על דברי ר' יוחנן: מדוע לאו שקדמו עשה לוקים עליו? \u0003והא לא דמי לאויה\u0004 \u0005[והרי אין דומה לאו\u0006 זה \u0005שלו]\u0006 \u0003ללאו\u0004 של \u0003חסימה\u0004 (\"לא תחסום שור בדישו\". דברים כה, ד), שממנו למדים מה הם האיסורים שיש עליהם עונש מלקות, שהרי בלאו של חסימה אין מצות עשה כתובה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: וכי \u0003משום דכתב ביה רחמנא\u0004 \u0005[שכתבה בו התורה]\u0006 בענין זה מצות \u0003עשה יתירא, מגרע גרע\u0004 \u0005[נעשה גרוע\u0006 יותר\u0005]\u0006 ואין לוקים עליו?","הקשה לו רב פפא: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כל \u0003לאו שניתק לעשה נמי לימא\u0004 \u0005[גם כן נאמר]\u0006 אותו דבר: \u0003משום דכתב ביה רחמנא\u0004 \u0005[שכתבה בו התורה]\u0006 מצות \u0003עשה יתירא מגרע גרע\u0004 \u0005[נעשה גרוע יותר]\u0006 ולא ילקו עליו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003ההוא\u0004 בלאו הניתק לעשה, דין מלקות בטל מפני שמצות העשה \u0003לנתוקי לאו\u0004 \u0005[לנתק את הלאו]\u0006 מעונש מלקות \u0003הוא דאתא\u0004 \u0005[שבאה],\u0006 וכל זמן שבידו לקיים את העשה אינו לוקה על הלאו.","ושבים לדברי רבא לענין אונס, שכל ימיו הריהו מצווה בעמוד והחזר, ולכן אינו לוקה על \"לא יוכל שלחה\", ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח למי שאומר]\u0006 שהשאלה אם לוקים על לאו שניתק לעשה תלויה בשאלה האם \u0003ביטלו ולא ביטלו\u0004 את העשה, שרק אם פעל באופן שביטל את מצוות העשה שבדבר, שלא יוכל עוד לקיימה, כגון אם היה זה כהן שגירש את אנוסתו, הריהו לוקה. אבל אונס רגיל אינו לוקה משום שלא ביטל את המצוה, שהרי יכול הוא עדיין להחזירה כל ימיו.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהשאלה אם לוקה או לא תלויה בשאלה האם \u0003קיימו ולא קיימו\u0004 שרק אם מקיים את העשה באופן מיידי אינו לוקה, אבל אם לא עשה זאת מיד הוא לוקה, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי מיד כשלא החזירה הריהו חייב מלקות!"],["ומשיבים: \u0003מידי הוא טעמא\u0004 \u0005[הרי טעם זה]\u0006 שכל ימיו הריהו בעמוד והחזר, לא אמרנו \u0003אלא ל\u0004שיטת \u0003ר' יוחנן,\u0004 להסביר מדוע אין האונס לוקה, למרות שהוא לאו שקדמו עשה. \u0003האמר ליה\u0004 \u0005[הרי אמר לו]\u0006 \u0003ר' יוחנן לתנא\u0004 \u0005[לחוזר המשניות],\u0006 \u0003תני\u0004 \u0005[שנה\u0006 כך\u0005]:\u0006 \u0003בטלו\u0004 את העשה — \u0003חייב, ולא בטלו\u0004 — \u0003פטור,\u0004 ולשיטתו הדבר מתיישב היטב.","ומה עניינו, \u0003דתני תנא קמיה\u0004 \u0005[ששנה חוזר המשניות לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו: \u0003כל מצות לא תעשה שיש בה קום עשה,\u0004 אם \u0003קיים עשה שבה\u0004 — \u0003פטור\u0004 ממלקות, אם \u0003ביטל עשה שבה\u0004 — \u0003חייב.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי קא אמרת\u0004 \u0005[מה אתה אומר]?\u0006 הלא יש בנוסח זה לשון כפולה וסותרת, שמן הרישא \u0003קיים\u0004 — \u0003פטור,\u0004 עולה שאם \u0003לא קיים\u0004 — \u0003חייב,\u0004 ומן הסיפא שאם \u0003ביטל\u0004 — \u0003חייב,\u0004 עולה שאם \u0003לא ביטל\u0004 — \u0003פטור,\u0004 למרות שלא קיים את העשה! אלא \u0003תני\u0004 \u0005[שנה]\u0006 כך: אם \u0003ביטלו\u0004 — חייב, \u0003ו\u0004אם \u0003לא ביטלו\u0004 — פטור. \u0003ור' שמעון בן לקיש אומר:\u0004 אכן, צריך לאחד את הלשונות בברייתא, אבל באופן אחר, שצריך לומר: אם \u0003קיימו\u0004 — פטור, \u0003לא קיימו\u0004 — חייב.","ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 מה יסודה של מחלוקת זו? \u0003בהתראת ספק\u0004 כשמתרים באדם על עבירה שאין זה ברור שילקה עליה, \u0003קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 ש\u0003התראת ספק שמה\u0004 (נחשבת) \u0003התראה,\u0004 שגם אם אין זה ברור שאותו אדם ייענש על אותה עבירה — אפשר להתרות בו שלא יעשה מעשה זה שיביאנו לידי מלקות, ואם אכן עבר — לוקה.","\u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 \u0003התראת ספק לא שמה\u0004 (נחשבת) \u0003התראה.\u0004 ולכן, לשיטת ר' יוחנן, כאשר מגרש את האנוסה, אף שאין זה ודאי שיבטל את העשה — מתרים בו שילקה, ואם יימצא שביטל את העשה, כגון שידור ממנה הנאה — ילקו אותו. ואילו ריש לקיש סבור שאם הדבר תלוי בביטול העשה — לא היה לוקה, שהרי זו התראת ספק, ואין לוקים עליה. ולכן הוא מסביר שהמלקות תלויות בקיום העשה, ואם לא קיים מיד את העשה (להחזירה) — מלקים אותו. ונמצא שכשמתרים בו שילקה אם יגרש, התראת ודאי היא.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והולכים\u0006 הם \u0005לטעמיהם,\u0006 לשיטותיהם\u0005],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה הבאה: אדם שאמר \u0003\"שבועה שאוכל ככר זה היום\", ועבר היום ולא אכלה,\u0004 מה דינו? \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אינו לוקה\u0004 על כך. משום שבועת שקר. אלא שנחלקו בטעמה של ההלכה, \u0003ר' יוחנן אומר: אינו לוקה ל\u0004"],["\u0003משום דהוי\u0004 \u0005[שהריהו]\u0006 \u0003לאו שאין בו מעשה,\u0004 שהרי כשעובר על השבועה ואינו אוכל אינו עושה כל מעשה, \u0003ו\u0004כלל הוא: \u0003כל לאו שאין בו מעשה —\u0004 \u0003אין לוקין עליו. ריש לקיש אומר: אינו לוקה, משום דהוי\u0004 \u0005[שהריהו]\u0006 \u0003התראת ספק,\u0004 שהרי אין יכולים להתרות בו כשהוא עומד להישבע שהוא עומד באותה שעה לעבור על שבועתו, שהרי כל עוד שיש זמן ביום — יכול הוא לאכול את הככר ולקיים את שבועתו, \u0003וכל התראת ספק\u0004 — \u0003לא שמה התראה.\u0004","ואומרים, \u0003ותרוייהו אליבא\u0004 \u0005[ושניהם\u0006 הולכים \u0005לפי שיטת]\u0006 \u0003ר' יהודה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר בקרבן הפסח \u0003\"ולא תותירו ממנו עד בקר, והנתר ממנו עד בקר\u0004 באש תשרפו\" (שמות יב, י), \u0003בא הכתוב ליתן\u0004 מצות \u0003עשה\u0004 של שריפה \u0003אחר\u0004 מצות \u0003לא תעשה\u0004 של הותרה, \u0003לומר שאין לוקין עליו,\u0004 על לאו זה של נותר, אלו \u0003דברי ר' יהודה. ר' יוחנן דייק הכי\u0004 \u0005[כך]\u0006 מדברי ר' יהודה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאינו לוקה הוא רק מכיון ש\u0003בא הכתוב\u0004 ונתן עשה על כך, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא\u0004 היה \u0003בא הכתוב,\u0004 היה \u0003לוקה\u0004 על כך, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003התראת ספק שמה\u0004 (נחשבת) \u0003התראה,\u0004 שהרי היו מתרים בו שלא יותיר, למרות שאולי לא יתחייב על כך אם ישרוף את הנותר.","\u0003וריש לקיש דייק הכי\u0004 \u0005[כך]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאינו לוקה הוא רק מכיון ש\u0003בא הכתוב, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא בא הכתוב\u0004 — היה \u0003לוקה, אלמא\u0004 \u0005[מכאן]\u0006 שגם על \u0003לאו שאין בו מעשה לוקין עליו,\u0004 שהרי די בכך שלא יאכל את הבשר כדי לעבור על הלאו.","ושואלים: \u0003ור' שמעון בן לקיש נמי\u0004 \u0005[גם כן],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ודאי התראת ספק הוא\u0004 כשמתרים בו על איסור ההותרה, ומדוע אינו מסביר כך את דברי ר' יהודה, שהתראת ספק שמה התראה?","ומשיבים: \u0003סבר לה כאידך תנא\u0004 \u0005[סבור הוא כ\u0006שיטת \u0005התנא האחר]\u0006 בשם \u0003ר' יהודה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מי שנתגרשה אמו ונישאה לאחר מכן, בלא להמתין זמן מספיק, וילדה אותו לאחר שבעה חודשים לנישואיה עם בעלה השני, שהם תשעה חודשים לגירושיה מבעלה הראשון, ולא ברור עתה אם הבן הנולד הוא בנו של הבעל הראשון או של השני, ונמצאים איפוא שני אנשים שהם ספק אביו, אם \u0003הכה\u0004 הבן את \u0003זה\u0004 את אחד הבעלים של אמו, \u0003וחזר והכה\u0004 את \u0003זה\u0004 הבעל האחר, או ש\u0003קילל זה וחזר וקילל זה,\u0004 וכן אם \u0003הכה שניהם בבת אחת או קילל שניהם בבת אחת\u0004 — הרי הוא \u0003חייב\u0004 משום מכה ומקלל אביו. \u0003ר' יהודה אומר:\u0004 אם קילל את שניהם \u0003בבת אחת\u0004 — \u0003חייב,\u0004 אבל אם עשה זאת \u0003בזה אחר זה,\u0004 והתרו בו לפני שהכה או קילל כל אחד מהם — \u0003פטור.\u0004 ומכאן ראיה שסבור ר' יהודה שאין לוקים על התראת ספק, שהרי כאשר מכה כל אחד לעצמו — אי אפשר להתרות בו בודאות שהוא מכה את אביו.","ועתה שואלים מצד שני: \u0003ור' יוחנן נמי\u0004 \u0005[גם כן],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ודאי\u0004 איסור ההותרה \u0003לאו שאין בו מעשה הוא,\u0004 ומדוע איננו תולה את טעם דברי ר' יהודה בזה, לומר שלאו שאין בו מעשה — לוקים עליו?","ומשיבים: \u0003סבר לה כי הא\u0004 \u0005[סבור הוא כ\u0006מימרה \u0005זו]\u0006 שנאמרה בשמו, ש\u0003אמר רב אידי בר אבין אמר רב עמרם אמר ר' יצחק, אומר ר' יוחנן: ר' יהודה אומר משום\u0004 (בשם) \u0003ר' יוסי הגלילי: כל לא תעשה שבתורה, לאו שיש בו מעשה\u0004 — \u0003לוקין עליו, לאו שאין בו מעשה\u0004 — \u0003אין לוקין עליו, חוץ מן הנשבע\u0004 לשקר, או \u0003מימר\u0004 בהמת הקדש בבהמת חולין, שאומר שזו תהיה תמורת זו, \u0003והמקלל את חבירו בשם\u0004 ה', שאף על פי שכל אלה לא עשו מעשה — לוקים.","ושואלים: אף שיישבנו את שיטות ר' יוחנן וריש לקיש, מכל מקום \u0003קשיא\u0004 \u0005[קשה]\u0006 מדבריו של \u0003ר' יהודה\u0004 על דבריו של \u0003ר' יהודה,\u0004 שהובאו שיטות סותרות בשמו, לגבי לאו שאין בו מעשה ולגבי התראת ספק!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' שמעון בן לקיש\u0004 צריך להגיד כי \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים\u0006 חלוקים \u0005לפי שיטתו]\u0006 של \u0003ר' יהודה, אי\u0004 \u0005[אם]\u0006 \u0003לר' יוחנן\u0004 — \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 שאפשר לומר: \u0003הא דידיה\u0004 \u0005[זו\u0006 שיטתו \u0005שלו]\u0006 והוא סבור שלאו שאין בו מעשה לוקים עליו, ו\u0003הא דרביה\u0004 \u0005[זו של רבו],\u0006 ר' יוסי הגלילי, הסבור שלאו שאין בו מעשה אין לוקים עליו.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003הנוטל אם על הבנים\u0004 שעבר על דברי תורה \"לא תקח האם על הבנים, שלח תשלח את האם ואת הבנים תקח לך\" (דברים כב, ו—ז), \u0003ר' יהודה אומר: לוקה\u0004 על מה שעבר ולקח, \u0003ואינו משלח\u0004 את האם. \u0003וחכמים אומרים: משלח ואינו לוקה;\u0004 וטעמם, \u0003זה הכלל: כל מצות לא תעשה שיש בה קום עשה\u0004 — \u0003אין חייבין עליה. אמר ר' יוחנן: אין לנו\u0004 בענין זה \u0003אלא\u0004 מצוה \u0003זאת ועוד אחרת,\u0004 שיש אפשרות ללקות עליה, ואינו לוקה אם אכן קיים את מצות העשה שבה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר: היכא\u0004 \u0005[היכן]\u0006 יש אותה מצוה נוספת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכי תשכח\u0004 \u0005[כאשר תמצא]\u0006 כלומר, לך ותמצא. \u0003נפק, דק, ואשכח\u0004 \u0005[יצא\u0006 מבית המדרש, \u0005דקדק\u0006 בדברים, \u0005ומצא].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אונס שגירש\u0004 את אנוסתו, \u0003אם ישראל הוא\u0004 — \u0003מחזיר ואינו לוקה\u0004 משום \"לא יוכל שלחה\", \u0003ואם כהן הוא,\u0004 ואינו יכול עוד להחזירה, משום שכל גרושה אסורה לכהן — \u0003לוקה ואינו מחזיר.\u0004","ושואלים: \u0003הניחא למאן דתני\u0004 \u0005[זה נוח למי ששונה]\u0006 שהמלקות על לא תעשה שיש בו עשה תלויות בשאלה האם \u0003קיימו\u0004 את העשה או \u0003לא קיימו,\u0004 שאם אין האיש מקיים את העשה ברגע שמוטל עליו הדבר — מלקים אותו.","\u0003אלא למאן דתני\u0004 \u0005[למי ששונה]\u0006 \u0003ביטלו ולא ביטלו,\u0004 שרק אם ביטל האיש בפועל את האפשרות לקיים את העשה הריהו לוקה על הלאו, הרי \u0003בשלמא\u0004 \u0005[נניח]\u0006 ל\u0003גבי שילוח הקן משכחת לה\u0004 \u0005[יכול אתה למצוא אותה]\u0006 שביטל את העשה, כגון שהרג את האם ואינו יכול עוד לשלחה. \u0003אלא אונס, ביטלו ולא ביטלו, היכי משכחת לה\u0004 \u0005[איך אתה מוצא\u0006 אפשרות \u0005כזו]\u0006 שהאיש יכול לבטל את האפשרות לחזור ולשאתה?","\u0003אי דקטלה\u0004 \u0005[אם שהרג אותה]\u0006 ולכן איננו יכול לשאתה — הלוא במקרה זה ממילא אינו נענש במלקות, \u0003קם ליה בדרבה מיניה\u0004 \u0005[\u0006משום ש\u0005עומד הוא ב\u0006עונש \u0005גדול ממנו],\u0006 בעונש מיתה! \u0003אמר רב שימי מחוזנאה\u0004 \u0005[ממחוזא]:\u0006 \u0003כגון שקיבל לה\u0004 עבורה דמי \u0003קידושין מאחר,\u0004 ועל ידי כך גרם ששוב לא יוכל לשאת אותה. \u0003אמר רב:\u0004 אם מעיינים בדבר רואים שאין פתרון כזה אפשרי, שכן \u0003אי שוויתיה\u0004 \u0005[אם\u0006 היא \u0005עשתה אותו]\u0006 \u0003שליח\u0004 לקבל קידושין — \u0003איהי קא מבטלא ליה\u0004 \u0005[היא המבטלת אותו]\u0006 מן העשה, שהדבר תלוי ברצונה, ואם כן אין הוא חייב כלל. \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא שוויתיה\u0004 \u0005[עשתה אותו]\u0006 \u0003שליח\u0004 — \u0003כל כמיניה\u0004 \u0005[וכי בכוחו]\u0006 לקבל קידושין עבור אשה שלא בקשה ממנו לעשות זאת? \u0003ולא כלום היא!\u0004","\u0003אלא אמר רב שימי מנהרדעא:\u0004 כאן מדובר \u0003כגון שהדירה ברבים,\u0004 שנדר בפני רבים הנאה ממנה, ואסור לו לשאת אותה. ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003נדר שהודר ברבים\u0004 — \u0003אין לו הפרה,\u0004 ולכן ביטל את האפשרות לקיים את המצוה לחזור ולשאתה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שגם נדר כזה \u0003יש לו הפרה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלא יכול להתיר את הנדר ולשאתה! ומשיבים: ש\u0003מדירה לה על דעת רבים\u0004 שתלה בדעתם את קיום הנדר, ולנדר כזה אין התרה. ש\u0003אמר אמימר, הלכתא\u0004 \u0005[הלכה]\u0006 היא: \u0003נדר שהודר ב\u0004פני \u0003רבים\u0004 — \u0003יש לו הפרה, על דעת רבים\u0004 — \u0003אין לו הפרה.\u0004","ועוד שואלים על דברי ר' יוחנן: \u0003ותו ליכא\u0004 \u0005[ועוד אין]\u0006 מצות לא תעשה שיש בה עשה, ולוקה עליה? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003 (סימן גזל משכן ופאה)\u0004 גזל, דרחמנא אמר \u0005[שהתורה אמרה]\u0006 \u0003\"לא תגזל\"\u0004 (ויקרא יט, יג), וגם נאמר \u0003\"והשיב את הגזלה\"\u0004 (ויקרא ה, כג). וכן דין \u0003משכון, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003\"לא תבא אל ביתו לעבט עבטו\"\u0004 (דברים כד, יא), ובהמשך נאמר \u0003\"השב תשיב לו העבוט כבא השמש\"\u0004 (דברים כד, יג),","\u0003ומשכחת לה\u0004 \u0005[ומוצא אתה אותה]\u0006 שלוקה בשני מקרים אלה גם למי שסבור שהדברים תלויים \u0003בקיימו ולא קיימו,\u0004 כשאינו רוצה לקיים את מצות העשה ולהשיב את הדבר, \u0003ו\u0004גם ב\u0003ביטלו ולא ביטלו,\u0004 כגון שמשמיד את הדבר הגזול או את המשכון! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בשני המקרים הללו, \u0003כיון\u0004 ש\u0003חייב בתשלומין\u0004 בהחזרת מה שלקח שלא כדין, יש טעם אחר שאינו לוקה, לפי הכלל: ש\u0003אין\u0004 אדם \u0003לוקה ומשלם\u0004 על אותו מעשה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: הא איכא\u0004 \u0005[הרי יש]\u0006 אפשרות שלא יוכל לשלם, כגון שלקח \u0003משכונו של גר, ומת הגר,\u0004 ואין לו יורשים שיוכל להחזיר להם. ואם כן אין בזה תשלומים, ובכל זאת אינו לוקה!"],["ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003גברא\u0004 \u0005[האיש]\u0006 \u0003בר תשלומין הוא,\u0004 שחיוב התשלומים חל עליו, \u0003ו\u0004רק \u0003שיעבודא\u0004 \u0005[השיעבוד]\u0006 של ה\u0003גר הוא דקא פקע\u0004 \u0005[שפקע],\u0006 שאין לו למי לשלם, ולכן אינו לוקה.","ושואלים: \u0003והא איכא\u0004 \u0005[והרי\u0006 עדיין \u0005יש]\u0006 דין \u0003פאה,\u0004 שיש מצות לא תעשה שלא לכלות את השדה, ומצות עשה הניתקת לה להניח לעני ולגר, \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003\"לא תכלה פאת\u0004 שדך\" (ויקרא כג, כב), ואחר כך נאמר \u0003\"לעני ולגר תעזב אתם\"\u0004 (ויקרא כג, כב),","\u0003דמשכחת לה\u0004 \u0005[שאתה יכול למצוא]\u0006 דוגמא לביטול העשה גם \u0003ב\u0004דרך של \u0003קיימו ולא קיימו\u0004 — כשלא נתן פאה, וגם ב\u0003ביטלו ולא ביטלו. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מצות פאה להפריש מן הקמה\u0004 (התבואה כשהיא צומחת בקרקע) כלומר, להניח חלק שאינו קצור. \u0003לא הפריש מן הקמה\u0004 וקצר הכל — \u0003מפריש מן העומרין\u0004 את חלק הפאה. \u0003לא הפריש מן העומרין\u0004 — \u0003מפריש מן הכרי\u0004 (ערימת החטים) \u0003עד שלא מירח\u0004 לפני שסידרה והחליקה, שאז נעשתה התבואה \"דגן\", וחלה על התבואה חובת תרומות ומעשרות. אם כבר \u0003מירחו\u0004 — \u0003מעשר\u0004 את הכרי תחילה \u0003ו\u0004אחר כך \u0003נותן לו\u0004 לעני. אבל אם טחן את הדגן — שוב אינו מפריש פאה. ונמצא שיש דרך לבטל את מצות הפרשת הפאה, ומדוע לא הזכיר גם אותה ר' יוחנן?","ומשיבים: הוא סבור \u0003כ\u0004שיטת \u0003ר' ישמעאל,\u0004 ש\u0003אמר: אף מפריש\u0004 פאה \u0003מן העיסה\u0004 כלומר, לעולם לא בטלה מצות פאה, ואם לא הפריש קודם פאה מן התבואה או מן הקמח — מפריש אף מעיסת הבצק. ומקשים: \u0003ולר' ישמעאל נמי משכחת לה\u0004 \u0005[גם כן אפשר למצוא אותה]\u0006 דרך של ביטול, \u0003דאכל\u0004 \u0005[שהוא אוכל]\u0006 את ה\u0003עיסה,\u0004 ואז אינו יכול להפריש עוד!","\u0003אלא\u0004 יש לחזור ממה שאמרנו, ולפרש שר' יוחנן שאמר \u0003\"זאת\u0004 (שילוח הקן) \u0003ועוד אחרת\"\u0004 — \u0003אהא\u0004 \u0005[על זו]\u0006 על דין פאה אמר, \u0003אבל אונס\u0004 — לא, שאינו יכול לבטל את מצות העשה של החזרתה, גם אם מדירה על דעת רבים. \u0003דהיכא אמרינן\u0004 \u0005[\u0006משום \u0005שהיכן אנו אומרים]\u0006 שנדר \u0003על דעת רבים אין לו הפרה\u0004 — \u0003ל\u0004צורך \u0003דבר הרשות, אבל\u0004 במקום שצריך להפר \u0003לדבר מצוה\u0004 — אפילו נדר על דעת רבים \u0003יש לו הפרה.\u0004 ואף כאן, אם נודר שלא לשאת את אנוסתו — הרי הוא נודר כנגד המצוה שעליו, ויש לנדר התרה.","ומביאים ראיה לדבר, \u0003כי הא דההוא מקרי דרדקי דהוה פשע בינוקי\u0004 \u0005[כמו\u0006 מעשה \u0005זה של מלמד תינוקות אחד שהיה פושע,\u0006 התרשל \u0005בתינוקות]\u0006 שלא השגיח עליהם כראוי, \u0003אדריה\u0004 \u0005[הדיר אותו]\u0006 \u0003רב אחא\u0004 על דעת רבים, שלא ילמד יותר. \u0003ואהדריה\u0004 \u0005[והחזיר אותו]\u0006 \u0003רבינא\u0004 למרות זאת, משום \u0003דלא אשתכח דדייק כוותיה\u0004 \u0005[שלא נמצא\u0006 אחר \u0005שהיה מדייק כמותו]\u0006 בלימוד. הרי שלצורך מצוה, אפילו נדר שהודר על דעת רבים יש לו הפרה.","שנינו במשנה בכלל הלוקים: \u0003והאוכל נבילות וטריפות שקצים ורמשים. אמר רב יהודה: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003אכל ביניתא דבי כרבא\u0004 \u0005[\u0006מעין \u0005דג הנמצא\u0006 בתלמי \u0005החריש\u0006\u0005]\u0006 \u0003מלקינן ליה\u0004 \u0005[מלקים אנו אותו]\u0006 \u0003משום \"שרץ השרץ על הארץ\u0004 לא תאכלום\" (ויקרא יא, מא). מסופר, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אכל ביניתא דבי כרבא\u0004 \u0005[דג שבין התלמים]\u0006 \u0003ונגדיה\u0004 \u0005[והלקהו]\u0006 \u0003רב יהודה.\u0004","\u0003אמר אביי: אכל פוטיתא\u0004 שהוא מין שרץ מים — \u0003לוקה ארבעה\u0004 חיובי מלקות, ששני לאוים כתובים בשרץ המים: \"כל אשר אין לו סנפיר וקשקשת... מבשרם לא תאכלו\" (ויקרא י—יא), וכן \"וכל אשר אין לו סנפיר וקשקשת לא תאכלו\" (דברים יד, י). ועוד שני לאוים כתובים בשרץ סתם: \"אל תשקצו את נפשותיכם בכל השרץ השורץ, ולא תטמאו בהם\" (ויקרא יא, מג), הרי ארבעה.","אכל \u0003נמלה\u0004 — \u0003לוקה חמש\u0004 פעמים מלקות, שנוסף לשני לאוים האמורים בשקץ סתם, לוקה גם \u0003משום \"השרץ השרץ על הארץ\u0004... לא יאכל\" (ויקרא יא, מא), ומשום \"...וכל השרץ השורץ על הארץ לא תאכלום\" (ויקרא יא, מג), ומשום \"ולא תטמאו את נפשותיכם בכל השרץ הרומש על הארץ\" (ויקרא יא, מד).","אכל \u0003צרעה\u0004 — \u0003לוקה שש\u0004 פעמים מלקות: חמש — כמו נמלה, ועוד אחד — \u0003משום שרץ העוף\u0004 (\"וכל שרץ העוף טמא הוא לכם לא יאכלו\" דברים יד, יט).","\u0003אמר רב אחאי: המשהה את נקביו\u0004 ואיננו יוצא לעשות צרכיו כשהוא צריך לכך — \u0003עובר משום \"לא תשקצו\u0004 את נפשותיכם\" (ויקרא כ, כה). \u0003אמר רב ביבי בר אביי: האי מאן דשתי בקרנא דאומנא\u0004 \u0005[מי ששותה מים מן הקרן של מקיז הדם]\u0006 שאליה נשפך הדם — \u0003קא עבר\u0004 \u0005[הריהו עובר]\u0006 \u0003משום \"לא תשקצו\".\u0004","\u0003אמר רבא בר רב הונא:\u0004 אם \u0003ריסק תשעה נמלים והביא\u0004 עוד \u0003אחד חי\u0004 (שלם) עד ש\u0003השלימן\u0004 כולן \u0003לכזית\u0004 ואכלם — \u0003לוקה שש\u0004 פעמים מלקות: \u0003חמש\u0004 — \u0003משום בריה\u0004 משום הנמלה החיה שאכל, שכאמור לעיל לוקה עליה משום חמישה לאוים, \u0003ואחד\u0004 לוקה — \u0003משום\u0004 שבסך הכל אכל \u0003כזית נבילה. רבא אמר\u0004 בשם \u0003ר' יוחנן: אפילו\u0004 אכל \u0003שנים\u0004 שתי נמלים מרוסקות, \u0003והוא\u0004 האחד החי, לוקה באופן זה. ו\u0003רב יוסף אמר: אפילו אחד והוא.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים],\u0006 אלא \u0003הא\u0004 \u0005[זה]\u0006 — \u0003ברברבי\u0004 \u0005[בגדולים]\u0006 אם הם משלימים לכזית כשהם גדולים, \u0003והא\u0004 \u0005[וזה]\u0006 — \u0003בזוטרי\u0004 \u0005[בקטנים],\u0006 ואין כאן הבדל בהלכה.","שנינו במשנה בכלל הלוקים \u0003\"אכל טבל ומעשר ראשון\". אמר רב: אכל טבל של מעשר עני\u0004 כלומר, אם אכל תבואה שעדיין לא הפרישו ממנה מעשר עני — \u0003לוקה\u0004 אף שהופרשו ממנה תרומה ומעשר ראשון.","ומסבירים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — \u0003כי האי\u0004 \u0005[כמו זה]\u0006 ה\u0003תנא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: יכול לא יהא חייב אלא על הטבל שלא הורם ממנו כל עיקר,\u0004 שלא הפרישו ממנו כל מתנה. אבל אם \u0003הורם ממנו תרומה גדולה ולא הורם ממנו מעשר ראשון,\u0004 או הורם \u0003מעשר ראשון ולא מעשר שני, ואפילו\u0004 לא הורם ממנו \u0003מעשר עני, מנין\u0004 שהוא טבל ושהוא חייב עליו —","\u0003תלמוד לומר \"לא תוכל לאכל בשעריך\u0004 מעשר דגנך ותירושך ויצהרך\" (דברים יב, יז), \u0003ולהלן\u0004 \u0005[הלאה]\u0006 \u0003הוא אומר\u0004 \"ונתת ללוי לגר ליתום ולאלמנה \u0003ואכלו בשעריך ושבעו\"\u0004 (דברים כו, יב), \u0003מה להלן\u0004 \u0005[הלאה]\u0006 \"ואכלו בשעריך\" הוא \u0003מעשר עני, אף כאן\u0004 מדובר כאשר מעורב בתבואה \u0003מעשר עני, ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"לא תוכל\u0004 לאכול\", שיש בזה איסור לאו.","\u0003אמר רב יוסף:\u0004 דבר זה שנוי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 ש\u0003ר' אליעזר אומר: אין צריך לקרות את השם על מעשר עני של דמאי\u0004 שאין צורך להפריש מעשר עני מן הדמאי (מתבואה שרק מחמת ספק אנו מפרישים עליה תרומות ומעשרות) כי מעשר עני הוא רק התחייבות כספית לעניים, ואינם יכולים לתובעו, מחמת הספק. ולדעת ר' אליעזר, אין התבואה נאסרת כשאין מפרישים ממנה מעשר זה. \u0003וחכמים אומרים:\u0004"],["\u0003קורא את השם\u0004 על חלק מסויים מן התבואה שהוא יהא מעשר עני, \u0003ו\u0004אולם \u0003אינו צריך להפריש\u0004 ולתת בפועל.","ומציעים: \u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא בזה הם חולקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 דבר שלא הופרש ממנו מעשר עני ב\u0003ודאי\u0004 — מעשר עני \u0003טובלו,\u0004 שהתבואה היא טבל, ולכן גם בספק צריך להפריש. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 אפילו \u0003ודאי\u0004 — \u0003אינו טובלו\u0004 מעשר עני, ולפיכך בספק אין הוא צריך אפילו לקרוא את השם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש את המחלוקת, \u0003אדמיפלגי\u0004 \u0005[עד ש\u0006הם \u0005חלוקים]\u0006 \u0003בספיקו\u0004 בדמאי, \u0003ליפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003בודאי,\u0004 האם הוא טבל כשוודאי לא הפריש מעשר עני!","\u0003אלא\u0004 צריך לחזור מפירוש ראשון, ולומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 לא הפריש מעשר עני \u0003ודאי\u0004 — \u0003טובלו.\u0004 \u0003והכא בהא קא מיפלגי\u0004 \u0005[וכאן ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003לא נחשדו עמי הארץ על מעשר עני של דמאי\u0004 כלומר, אין עמי הארץ חשודים שלא הפרישו מעשר עני. ומדוע, \u0003כיון דממונא\u0004 \u0005[שממון]\u0006 \u0003הוא,\u0004 ואין בו קדושה, לכן \u0003אפרושי מפריש\u0004 \u0005[מפריש],\u0006 אף כי בפועל אינו נותן אותו לעניים. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003כיון דטריחא ליה מילתא\u0004 \u0005[שטורח\u0006 הוא \u0005לו הדבר]\u0006 — \u0003לא מפריש\u0004 אף מעשר עני.","במשנה נחלקו: \u0003כמה יאכל מן הטבל\u0004 ויהא חייב, ר' שמעון אומר: כל שהוא, וחכמים אומרים: כזית. \u0003אמר רב ביבי אמר ר' שמעון בן לקיש: מחלוקת\u0004 זו היא \u0003בחטה,\u0004 אם אכל חטה אחת של טבל. \u0003אבל בקמח\u0004 — \u0003דברי הכל\u0004 איננו חייב אלא אם אכל \u0003כזית. ור' ירמיה אמר ר' שמעון בן לקיש: כמחלוקת בזו\u0004 בחיטה, \u0003כך מחלוקת בזו\u0004 בקמח.","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003אמר להם ר' שמעון: אי\u0004 (אין) \u0003אתם מודים לי באוכל נמלה כל שהוא שהוא חייב? אמרו לו:\u0004 חייב עליה \u0003מפני שהיא כברייתה. אמר להן: אף חטה אחת כברייתה.\u0004 ונדקדק מדברי ר' שמעון: \u0003חטה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003קמח\u0004 — לא. שאף הוא אינו מחייב על אכילת קמח אלא באכילה חשובה שהיא כזית, כדברי רב ביבי בשם ר' שמעון בן לקיש!","ומשיבים: ר' שמעון \u0003לדבריהם\u0004 על פי שיטתם של חכמים \u0003קאמר להו\u0004 \u0005[אומר להם],\u0006 וכך צריך להבין: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003אפילו\u0004 אם אכל \u0003קמח\u0004 כל שהוא \u0003נמי\u0004 \u0005[גם כן]\u0006 חייב. \u0003אלא לדידכו אודו לי מיהת\u0004 \u0005[לשיטתכם הודו לי על כל פנים]\u0006 ש\u0003חטה אחת,\u0004 שהיא \u0003כברייתה\u0004 חייב עליה. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: \u0003בריית נשמה\u0004 (יצור חי) — \u0003חשובה\u0004 נחשבת לדבר לעצמו, \u0003חטה\u0004 אחת — \u0003לא חשובה.\u0004 ומעירים, \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' ירמיה\u0004 שאף לענין קמח חלק ר' שמעון, שכך שנינו, \u0003ר' שמעון אומר:\u0004 האוכל איסור \u0003כל שהוא\u0004 נדון \u0003למכות, לא אמרו\u0004 שיעור \u0003כזית אלא לענין קרבן\u0004 שאינו מתחייב קרבן על אכילת איסור בשגגה אלא אם כן אכל כזית.","כהן \u0003האוכל בכורים עד שלא\u0004 (לפני) ש\u0003קרא עליהם\u0004 המביאם את הדברים שצריך מביא הביכורים לומר בשעת הבאת בכורים (ראה דברים כו, ג— י), וכן האוכל \u0003קדשי קדשים חוץ לקלעים\u0004 (לקלעי החצר של המשכן), ובמקדש בירושלים — מחוץ לעזרה. וכן האוכל \u0003קדשים קלים\u0004 או \u0003מעשר שני חוץ לחומה\u0004 של ירושלים. וכן \u0003השובר את העצם ב\u0004קרבן \u0003פסח הטהור,\u0004 בכל אלה — \u0003הרי זה לוקה ארבעים\u0004 מלקות. \u0003אבל המותיר\u0004 עד בוקר יום חמישה עשר בניסן מן הבשר \u0003ב\u0004קרבן פסח ה\u0003טהור, ו\u0004כן \u0003השובר\u0004 עצם \u0003ב\u0004פסח ה\u0003טמא\u0004 — \u0003אינו לוקה ארבעים.\u0004","\u0003הנוטל\u0004 מן הקן \u0003אם על הבנים,\u0004 ועובר על דברי התורה שאסרה ליטול אותה יחד עימם, \u0003ר' יהודה אומר: לוקה\u0004 על מה שעשה, \u0003ואינו משלח,\u0004 אינו צריך עוד לשלח את האם לאחר שלקחה. \u0003וחכמים אומרים: משלח, ו\u0004אז \u0003אינו לוקה.\u0004 ו\u0003זה הכלל: כל מצות לא תעשה שיש בה\u0004 גם מצות \u0003קום עשה\u0004 — \u0003אין חייבין עליה\u0004 מלקות, אלא יקיים את העשה.","על האמור במשנה בענין כהן שאוכל ביכורים לפני שקרא עליהם מי שהביאם, שהוא לוקה, \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 משנתנו \u0003זו\u0004 היא \u0003דברי ר' עקיבא סתימתאה\u0004 שרגילים דבריו להיאמר במשנה בסתם, ללא ציון שמו. \u0003אבל חכמים אומרים: בכורים\u0004 ה\u0003הנחה\u0004 שלהם ליד המזבח — \u0003מעכבת בהן,\u0004 ובלי זה אסורים הם באכילה, אבל \u0003קריאה\u0004 — \u0003אין מעכבת בהן,\u0004 ואם הניח ולא קרא, אינו לוקה האוכלם.","ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 ר' יוחנן ש\u0003זו דברי ר' שמעון סתימתאה\u0004 שהרי מצאנו במפורש שזו שיטת ר' שמעון, ולמה ציין את שיטת ר' עקיבא שאינה מפורשת? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 ש\u0003ר' עקיבא כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 אף שלא נתפרש הדבר.","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 הם דברי \u0003ר' שמעון\u0004 אלה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין הדברים האסורים באכילה מחוץ לירושלים: נאמר \"לא תוכל לאכול בשעריך מעשר דגנך ותירושך ויצהרך ובכורות בקרך וצאנך וכל נדריך אשר תדור ונדבותיך ותרומת ידך\" (דברים יב, יז), \u0003ו\u0004דרשו: \u0003\"ותרומת ידך\"\u0004 — \u0003אלו בכורים.\u0004","\u0003אמר ר' שמעון: מה בא\u0004 כתוב \u0003זה ללמדנו? אם\u0004 לאסור \u0003לאוכלן חוץ לחומה,\u0004 שחייבים לאוכלם בירושלים בלבד — הרי דבר זה נלמד ב\u0003קל וחומר ממעשר\u0004 שני, \u0003הקל\u0004 יותר בדינו מן הביכורים, ובאופן זה: \u0003ומה מעשר הקל,\u0004 מי ש\u0003אוכלן חוץ לחומה לוקה\u0004 — \u0003בכורים לא כל שכן? הא\u0004 \u0005[הרי]\u0006 \u0003לא בא הכתוב אלא לאוכל מבכורים עד שלא קרא עליהם,\u0004 לומר \u0003שהוא לוקה.\u0004","וממשיכה הברייתא במדרש הפסוק: נאמר \u0003\"ונדבתיך\"\u0004 — \u0003זו תודה ושלמים,\u0004 שבאים מנדבת לבו של אדם. \u0003אמר ר' שמעון: מה בא\u0004 כתוב \u0003זה ללמדנו? אם לאוכל\u0004 קרבנות אלו \u0003חוץ לחומה\u0004 — דבר זה נלמד ב\u0003קל וחומר ממעשר\u0004 שני שאסור לאוכלו חוץ לחומה, למרות שאינו קרבן, ולוקים עליו. \u0003הא\u0004 \u0005[הרי]\u0006 איפוא \u0003לא בא הכתוב אלא\u0004 ללמד \u0003לאוכל בתודה ובשלמים לפני זריקה\u0004 של הדם על המזבח, קודם שהותרו באכילה, \u0003שהוא לוקה.\u0004","ועוד דרשו: \u0003\"ובכרת\"\u0004 — \u0003זה הבכור. אמר ר' שמעון: מה בא\u0004 כתוב \u0003זה ללמדנו? אם לאוכלן חוץ לחומה\u0004 — \u0003קל וחומר ממעשר\u0004 שני, \u0003אם\u0004 לאסור לאוכלם \u0003לפני זריקה\u0004 — \u0003קל וחומר מתודה ושלמים\u0004 שהם קלים יותר, שהם נאכלים לישראלים. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא בא הכתוב אלא ל\u0004זר, שאינו כהן, ה\u0003אוכל מן הבכור אפילו לאחר זריקה\u0004 — \u0003שהוא לוקה.\u0004","ועוד דרשו: \u0003\"בקרך וצאנך\" —\u0004 \u0003זו חטאת ואשם,\u0004 שהם קדשי קדשים, ונאכלים רק בעזרה. \u0003אמר ר' שמעון: מה בא זה ללמדנו?\u0004","\u0003אם לאוכלן חוץ לחומה\u0004 — \u0003קל וחומר ממעשר, אם\u0004 לאסור לאוכלם \u0003לפני זריקה\u0004 — \u0003קל וחומר מתודה ושלמים\u0004 שהם קדשים קלים, \u0003אם\u0004 לאסור לאוכלם \u0003לאחר זריקה\u0004 — \u0003קל וחומר מבכור,\u0004 שנאכל גם מחוץ לעזרה. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא בא הכתוב אלא\u0004 ללמד \u0003לאוכל מחטאת ואשם אפילו לאחר זריקה חוץ לקלעים\u0004 (מחוץ לעזרה) \u0003שהוא לוקה.\u0004","עוד נאמר בכתוב שם \u0003\"נדריך\"\u0004 — \u0003זו עולה,\u0004 שהיא קדשי קדשים ועולה כליל למזבח. שאדם מביאה כנדר, ואינה חובה על האדם. \u0003אמר ר' שמעון: מה בא זה ללמדנו?\u0004","\u0003אם לאוכלן חוץ לחומה\u0004 — \u0003קל וחומר ממעשר, אם\u0004 לאוכלם \u0003לפני זריקה\u0004 — \u0003קל וחומר מתודה ושלמים, אם\u0004 שיאכלם זר \u0003לאחר זריקה\u0004 — \u0003קל וחומר מבכור, אם\u0004 לאוכלם \u0003חוץ לקלעים\u0004 — \u0003קל וחומר מחטאת ואשם, הא\u0004 \u0005[הרי]\u0006 \u0003לא בא הכתוב ל\u0004"],["\u0003אלא לאוכל מן העולה לאחר זריקה, אפילו בפנים, שהוא לוקה.\u0004 עד כאן דברי ר' שמעון.","\u0003אמר רבא:\u0004 מי \u0003דילידא אימיה\u0004 \u0005[שיולדת\u0006 אותו \u0005אמו]\u0006 והרי הוא \u0003כר' שמעון\u0004 — \u0003תיליד\u0004 \u0005[תלד],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003מוטב ש\u0004\u0003לא תיליד\u0004 \u0005[תלד]\u0006 אותו כלל. שהתפעל מדברי ר' שמעון, ואמר בשבחו שכך צריך אדם להיות מופלג בחכמה. והוסיף רבא: \u0003ו\u0004אומר אני דבר זה \u0003אף על גב דאית להו פירכא\u0004 \u0005[אף על פי שיש להן\u0006 לכל מסקנותיו \u0005פירכה]\u0006 שיש מקום להקשות עליהן. כיצד?","\u0003מאי חומרא\u0004 \u0005[מה החומרה]\u0006 שיש ב\u0003בכורים ממעשר\u0004 שני — \u0003שכן\u0004 הביכורים \u0003אסורים לזרים\u0004 שאינם כהנים, מה שאין כן מעשר שני. ואולם אפשר לומר \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003מעשר חמור\u0004 מביכורים, \u0003שכן\u0004 הוא \u0003אסור\u0004 באכילה \u0003לאונן\u0004 (מי שמת לו מת באותו יום), מה שאין כן בביכורים.","\u0003ו\u0004כן \u0003מאי חומרא\u0004 \u0005[מה החומרה]\u0006 של \u0003תודה ושלמים ממעשר\u0004 שני — \u0003שכן\u0004 תודה ושלמים \u0003טעונין\u0004 (צריכים) \u0003מתן דמים ו\u0004הקרבת \u0003אימורין\u0004 (חלקים מן הקרבן) \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח.\u0004 אבל אפשר לומר \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003מעשר חמור\u0004 מתודה ושלמים, \u0003שכן\u0004 פירותיו \u0003טעונין\u0004 לפדייתם דווקא \u0003כסף צורה\u0004 כלומר, דווקא במטבע ולא בחתיכת כסף, ואף לא במטבע ללא הטבעה (אסימון), אבל תודה ושלמים, ושאר קדשים שנפסלו, נפדים בשוויים.","\u0003ו\u0004כן \u0003מאי חומרא\u0004 \u0005[מה החומרה]\u0006 של \u0003בכור מתודה ושלמים\u0004 — \u0003שכן קדושתו\u0004 של הבכור \u0003מרחם,\u0004 ושאר הקדשים מוקדשים על ידי האדם. ואולם \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 אפשר לומר: \u0003תודה ושלמים חמורים, שכן טעונים סמיכה\u0004 לפני הקרבתם, \u0003ו\u0004כן טעונים \u0003נסכים, ו\u0004כן טעונים \u0003תנופת\u0004 (הרמת) \u0003חזה ושוק,\u0004 מה שאין כן בבכור.","\u0003ו\u0004עוד יש להקשות: \u0003מאי חומרא\u0004 \u0005[מה החומרה]\u0006 של \u0003חטאת ואשם מבכור\u0004 — \u0003שכן\u0004 חטאת ואשם הם \u0003קדשי קדשים.\u0004 ואולם \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 אפשר לומר ש\u0003בכור חמור\u0004 מהם, \u0003שכן קדושתו מרחם,\u0004 שהרי בלידתו הוא קדוש ואין קדושתו באה על ידי הקדשה בפה.","\u0003ו\u0004כן \u0003מאי חומרא\u0004 \u0005[מה החומרה]\u0006 של \u0003עולה מחטאת ואשם\u0004 — \u0003שכן\u0004 היא עולה \u0003כליל\u0004 לה', ואין בה חלק לכהנים. ואולם אפשר לומר: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003חטאת ואשם חמירי\u0004 \u0005[חמורים]\u0006 יותר \u0003שכן מכפרי\u0004 \u0005[מכפרים],\u0006 ועולה מובאת כנדבה.","ועוד יש להקשות: \u0003וכולהו חמירי\u0004 \u0005[וכולם חמורים]\u0006 \u0003מעולה,\u0004 משום \u0003דאית בהו\u0004 \u0005[שיש בהם]\u0006 \u0003שתי אכילות,\u0004 שחלק מהם נאכל (נשרף) על המזבח, וחלקם לבני אדם, מה שאין כן בעולה שיש בה אכילת מזבח בלבד.","ושואלים: \u0003אלא\u0004 לאחר שפרך רבא את כל הראיות של ר' שמעון, \u0003מאי\u0004 \u0005[מה]\u0006 שיבח אותו כל כך עד שאמר \u0003דילידא אימיה\u0004 \u0005[שיולדת אמו]\u0006 שתלד \u0003כר' שמעון?\u0004 ומסבירים: \u0003דלמאי דסבירא ליה לדידיה\u0004 \u0005[שלפי מה שהוא,\u0006 ר' שמעון, \u0005סבור, לשיטתו]\u0006 הוא \u0003מסרס ליה לקרא ודריש ליה\u0004 \u0005[משנה אותו את\u0006 סדר \u0005המקרא ודורש אותו].\u0006 שהרי ר' שמעון אינו דורש את הפסוק לפי סדרו, אלא מתחיל מסופו, מביכורים. לפי שאם היה רוצה לדרוש כסדר הכתוב לא היה יכול להגיע לאותן מסקנות. ורבא התפעל מן האופן בו דרש ר' שמעון.","ושואלים לגופם של דברי ר' שמעון, שלמד בדרך קל וחומר איסורי לאו שלא נתפרשו בתורה: \u0003וכי מזהירין מן הדין?\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003עונשין מן הדין,\u0004 שאם כבר יש אזהרה מפורשת בדבר, למדים במדת קל וחומר מדין אחר על העונש, בכל אופן גם הוא סבור ש\u0003אין מזהירין מן הדין,\u0004 לבנות איסור חדש בדרך קל וחומר! ומשיבים: לא בא ר' שמעון לומר שיש כאן לאו ממש מן התורה שלוקים עליו, אלא \u0003איסורא בעלמא\u0004 \u0005[איסור בלבד]\u0006 שנלמד מדרשת הכתוב.","ומקשים: איך אפשר לפרש כך? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: זר שאכל מן העולה לפני זריקה חוץ לחומה, ל\u0004דעת \u0003ר' שמעון לוקה חמש:\u0004 משום זרות, ומשום אכילת עולה, ומשום אכילת קרבן לפני זריקה, ומשום אכילת קדשי קדשים מחוץ לעזרה, ומשום אכילת קדשים מחוץ לירושלים. משמע מדבריו שלדעת ר' שמעון יש בכל אלה לאו ממש מן התורה עד שלוקים עליו! ומשיבים: אין הכוונה שלוקה ממש, אלא לומר ש\u0003חמשה איסורין הוו\u0004 \u0005[הם]\u0006 בדבר, אבל אין לוקה מן התורה.","ועוד מקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 בענין זה: \u0003אלו הן הלוקין\u0004 מן התורה, ונמנה ביניהם האיסור לאכול ביכורים לפני קריאה, והסכמנו שמשנתנו היא לשיטת ר' שמעון!"],["\u0003אלא\u0004 כך יש לפרש: בעצם כל הפסוק הזה (\"לא תוכל לאכול בשעריך מעשר דגנך\" וכו'. דברים יב, יז) \u0003קרא יתירא\u0004 \u0005[מקרא מיותר]\u0006 \u0003הוא, מכדי כתיב\u0004 \u0005[הלא נאמר]\u0006 כבר \u0003\"והבאת שם ואכלת לפני ה' אלהיך במקום\" וגו'\u0004 (\"והבאתם שמה עולותיכם וזבחיכם ואת מעשרותיכם ואת תרומת ידכם ונדריכם ונדבותיכם ובכורות בקרכם וצאנכם ואכלתם שם לפני ה' אלהיכם\". שם ו— ז) הרי שכבר נתפרטו באותה פרשה כל הדברים שצריך לאכול בירושלים דוקא, אם כן \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא תוכל לאוכלם\"\u0004 באופן כללי, וממילא היה בזה איסור לאו שמחייב מלקות על כל אחד ואחד מן הפרטים המפורשים כבר, \u0003מיהדר מפרש בהו רחמנא\u0004 \u0005[לחזור ולפרט\u0006 כל אחד \u0005בהם בתורה]\u0006 \u0003למה לי?\u0004","\u0003אלא\u0004 באה חזרה זו \u0003ליחודי להו לאוי\u0004 \u0005[ליחד להם לאוים]\u0006 \u0003לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 שיש איסור מיוחד נוסף בכל אחד מן הפרטים שנמנו בפסוק השני. ואנו למדים איפוא לא מקל וחומר, שהרי אין מזהירים מן הדין, אלא מיתור המקראות. ולא בא ר' שמעון אלא ללמד בדרך הקל וחומר מהו האיסור המיוחד שנוסף בכל אחד מן הפרטים.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שאמרנו, \u0003אמר רבא: זר שאכל מן העולה לפני זריקה חוץ לחומה, לר' שמעון לוקה חמש.\u0004 ושואלים: \u0003ולילקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 \u0003משום\u0004 איסור נוסף \u0003\"וזר לא יאכל כי קדש הם\"\u0004 (שמות כט, לג)! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 איסור זה שזר לא יאכל קדש, הוא רק \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לכהנים\u0004 הדבר \u0003חזי\u0004 \u0005[ראוי]\u0006 לאכילה, \u0003הכא דלכהנים נמי לא חזי\u0004 \u0005[כאן שלכהנים גם כן אינו ראוי],\u0006 שהרי אסור לכל אדם לאכול מן העולה — אין בו איסור מיוחד לזר.","ושואלים: \u0003ולילקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 \u0003משום\u0004 האיסור של \u0003\"ובשר בשדה טרפה לא תאכלו\"\u0004 (שמות כב, ל), שמן המלה \"בשדה\" למדנו הלכה כללית: \u0003כיון שיצא בשר חוץ למחיצתו\u0004 (\"בשדה\"), כגון בשר קדשים שיצא מחוץ לקלעים, שהיא המחיצה הראויה לו לפי עניינו — הרי הוא \u0003נאסר\u0004 באכילה, ויש עליו מצות לא תעשה! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003היכא דבפנים חזי\u0004 \u0005[היכן שבפנים\u0006 הוא \u0005ראוי]\u0006 לאכילה, ואז יש איסור על אכילתו מחוץ למחיצתו. \u0003הכא\u0004 \u0005[כאן\u0006 בקרבן עולה\u0005],\u0006 ש\u0003בפנים\u0004 הוא \u0003נמי לא חזי\u0004 \u0005[גם כן לא ראוי]\u0006 לאכילה, שהרי אין העולה ראויה לאכילת אדם — אין בו איסור אכילה לזר.","ושואלים: \u0003ולילקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 כפי הדברים שאמר \u0003ר' אליעזר,\u0004 ש\u0003אמר ר' אליעזר:\u0004 נאמר על הנותר מבשר ומלחם המילואים \u0003\"לא יאכל כי קדש הוא\"\u0004 (שמות כט, לד), ל"],["\u0003כל שבקדש פסול\u0004 כל קדשים שנפסלו מכל טעם שהוא — \u0003בא הכתוב ליתן\u0004 מצות \u0003לא תעשה על אכילתו!\u0004 ומשיבים: כאן אין הדבר שייך, שכן \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום]\u0006 ש\u0003קודם פסולו\u0004 היה \u0003חזי\u0004 \u0005[ראוי],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 ש\u0003קודם פסולו נמי לא חזי\u0004 \u0005[גם כן אין ראוי]\u0006 לא שייך בו איסור זה.","ושואלים: \u0003ולילקי נמי כאידך\u0004 \u0005[ושילקה גם כן כ\u0006אימרה \u0005אחרת]\u0006 של \u0003ר' אליעזר, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל שהוא ב\"כליל תהיה\"\u0004 שיש מצוה לשרוף אותו כולו, בא הכתוב \u0003ליתן לא תעשה על אכילתו,\u0004 כאמור \"כליל תהיה לא תאכל\" (ויקרא ו, טז)! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן],\u0006 \u0003ורבא\u0004 שאמר כי לדעת ר' שמעון לוקה חמש — דווקא \u0003מהאי קרא קאמר\u0004 \u0005[מאותו פסוק\u0006 שדרש ר' שמעון לעיל \u0005אמר],\u0006 אף שיש גם איסור נוסף ב\"כליל תהיה\".","\u0003אמר רב גידל אמר רב: כהן שאכל מחטאת ואשם לפני זריקה\u0004 של דם קרבנות אלה על המזבח — \u0003לוקה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין קרבנות המילואים, שהותרו באכילה רק לכהנים, כחטאת ואשם: \u0003\"ואכלו אתם אשר כפר בהם\"\u0004 (שמות כט, לג), לדייק: דווקא \u0003לאחר כפרה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 יאכלו אותם, ואולם \u0003לפני כפרה\u0004 — לא. ולשיטתו, \u0003לאו הבא מכלל עשה\u0004 כלומר, איסור הנובע מתוך מצות עשה — \u0003לאו הוא\u0004 כשאר הלאוים, ולוקים עליו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבא:\u0004 הלא נאמר \u0003\"וכל בהמה מפרסת פרסה ושסעת שסע שתי פרסות מעלת גרה בבהמה אתה תאכלו\"\u0004 (דברים יד, ו), ומכאן אפשר לדייק: \u0003\"אתה תאכלו\"\u0004 — \u0003ואין בהמה אחרת תאכלו,\u0004 שבא הכתוב לשלול, ולאסור אכילתה של בהמה אחרת שאין בה סימני טהרה. \u0003ואי כדקאמרת\u0004 \u0005[ו\u0006אולם \u0005אם כמו שאתה אומר]\u0006 שמצות העשה יוצרת ממילא מצות לא תעשה, מה שנאמר הלאה \u0003\"את זה לא תאכלו\"\u0004 (דברים יד, ז) \u0003למה לי?\u0004 והרי הדבר נלמד כבר ממצות העשה! אלא ודאי לאו הבא מכלל עשה — עשה הוא, ואין לוקים עליו!","\u0003אלא,\u0004 יש לדחות את מה שאמרנו ולתקן: \u0003אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר]\u0006 \u0003אמר רב גידל אמר רב: זר\u0004 (מי שאינו כהן) \u0003שאכל מחטאת ואשם, לפני זריקה\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואכלו אתם אשר כפר בהם...\u0004 וזר לא יאכל כי קדש הם\", ואנו למדים: \u0003כל היכא דקרינן ביה\u0004 \u0005[בכל מקום שאנו קוראים בו]\u0006 \u0003\"ואכלו אתם אשר כפר בהם\"\u0004 — באותו דבר \u0003קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 גם כן \u0003\"וזר לא יאכל קדש\", וכל היכא דלא קרינן ביה\u0004 \u0005[וכל מקום שאין אנו קוראים בו]\u0006 \u0003\"ואכלו אתם אשר כפר בהם\"\u0004 כגון כאן, קודם זריקת הדם על המזבח, שגם לכהנים אסורים קרבנות אלה — \u0003לא קרינן ביה\u0004 \u0005[אין אנו קוראים בו]\u0006 \u0003\"וזר לא יאכל\".\u0004","ושבים לדון בדין קריאה של הביכורים שהוזכר במשנה. \u0003אמר ר' אלעזר אמר ר' הושעיה: בכורים, הנחה\u0004 ליד המזבח — \u0003מעכבת בהן,\u0004 שאם לא עשו זאת, אינם מותרים לכהנים. \u0003קרייה\u0004 (קריאה) של פרשת הביכורים \u0003אין מעכבת בהן.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אלעזר הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר אמר ר' הושעיא: הפריש בכורים קודם לחג\u0004 הסוכות, \u0003ועבר עליהן החג\u0004 — \u0003ירקבו,\u0004 ואין להם תקנה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 סיבת הדבר היא \u0003משום דלא מצי למיקרי\u0004 \u0005[שאינו יכול\u0006 עוד \u0005לקרוא]\u0006 \u0003עליהן\u0004 את הקריאה, לפי שזמן הקריאה הוא רק עד החג? \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003קרייה אין מעכבת בהם, אמאי\u0004 \u0005[מדוע]\u0006 \u0003ירקבו?\u0004","ומשיבים: ר' אלעזר סבור \u0003כ\u0004שיטת \u0003ר' זירא.\u0004 ש\u0003אמר ר' זירא\u0004 בהלכות מנחות, ומכאן כלל גדול לדברים אחרים: \u0003כל הראוי לבילה\u0004 (לבלילה) כל מנחה שראויה מצד גודלה לבלול אותה בשמן, כדין התורה — \u0003אין בילה מעכבת בו,\u0004 וגם אם לא נבללה בפועל — אין הדבר פוסל את המנחה. \u0003וכל שאינו ראוי לבילה,\u0004 שאי אפשר כלל לבלול אותו — \u0003בילה\u0004 שציותה התורה \u0003מעכבת בו.\u0004 וגם כאן, אף שהקריאה כשלעצמה איננה מעכבת, מכל מקום הביכורים צריכים להיות ראויים לקריאה. ואילו ביכורים אלו שעבר עליהם חג הסוכות — שוב אינם ראויים לקריאה, ולכן יירקבו.","\u0003ר' אחא בר יעקב מתני לה\u0004 \u0005[היה שונה אותה,\u0006 את ההלכה הזו\u0005]\u0006 שיוחסה למעלה בשם ר' אלעזר, \u0003כ\u0004דברי \u0003ר' אסי אמר ר' יוחנן, וקשיא ליה\u0004 \u0005[והיה קשה לו]\u0006 מתוך כך מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן.\u0004 וכך שאל: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן בכורים הנחה מעכבת בהן, קרייה אין מעכבת בהן? והא בעא מיניה\u0004 \u0005[והרי שאל אותו]\u0006 \u0003ר' אסי מר' יוחנן: בכורים מאימתי מותרין לכהנים? ואמר ליה\u0004 \u0005[לו]:\u0006 אותם ביכורים \u0003הראוין לקרייה\u0004 — מותרים \u0003משקרא עליהן, ושאין ראוין לקרייה\u0004 — \u0003משראו פני הבית.\u0004 הרי שלדעתו, ביכורים שאינם ראוים לקריאה — אינם פסולים. ומצד שני, כיון שלא הזכיר הנחה כלל, משמע שהנחה אינה מעכבת בהם.","ואם כן הרי זו סתירה כפולה: \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003קרייה\u0004 על דין \u0003קרייה, קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003הנחה\u0004 על דין \u0003הנחה!\u0004","ומתרצים: מדין \u0003קרייה\u0004 על דין \u0003קרייה לא קשיא\u0004 \u0005[קשה],\u0006 שיש לומר: \u0003הא\u0004 \u0005[זו]\u0006 שקריאה מעכבת \u0005—\u0006 אמר כדעת \u0003ר' שמעון\u0004 האמורה במשנתנו, \u0003והא\u0004 \u0005[וזו]\u0006 שאין קריאה מעכבת — כדעת \u0003רבנן\u0004 \u0005[חכמים].\u0006 מדין \u0003הנחה\u0004 על דין \u0003הנחה נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 — כשיטת \u0003ר' יהודה,\u0004 שסבור שאין הנחה מעכבת, \u0003והא\u0004 \u0005[וזו]\u0006 — \u0003כשיטת\u0004 \u0003רבנן\u0004 \u0005[חכמים],\u0006 והם סבורים שהנחה מעכבת.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 שיטת \u0003ר' יהודה\u0004 שאנו רומזים לה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 נאמר בביכורים \u0003\"והנחתו\u0004 לפני ה' אלהיך\" (דברים כו, י) — אין זו הנחה אלא \u0003זו תנופה\u0004 (הנפה). \u0003אתה אומר זו תנופה, או אינו אלא הנחה ממש? כשהוא אומר\u0004 קודם לכן \"ולקח הכהן הטנא מידך \u0003והניחו\u0004 לפני מזבח ה' אלהיך\" (דברים כו, ד) — \u0003הרי הנחה\u0004 ליד המזבח \u0003אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"והנחתו\"\u0004 — יש לפרש ש\u0003זו תנופה.\u0004","ומסבירים: \u0003ומאן\u0004 \u0005[ומיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[החולק עליו]\u0006 על \u0003ר' יהודה —\u0004 שיטת \u0003ר' אליעזר בן יעקב היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"ולקח הכהן הטנא מידך\u0004 והניחו לפני מזבח ה' אלהיך\" (דברים כו, ד) — \u0003לימד על הבכורים שטעונין תנופה, דברי ר' אליעזר בן יעקב.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר בן יעקב?\u0004","\u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"יד\" \"יד\" משלמים,\u0004 כיצד? \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בביכורים \u0003\"ולקח הכהן הטנא מידך\"\u0004 (דברים כו,ד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בקרבן שלמים \"המקריב את זבח שלמיו לה'... \u0003ידיו תביאינה את אשי ה'...\u0004 להניף אותו תנופה לפני ה' \" (ויקרא ז, כט— ל), ויש ללמוד משני דינים אלה זה על זה: \u0003מה כאן\u0004 בביכורים \u0003כהן\u0004 עושה זאת — \u0003אף להלן\u0004 בשלמים צריך שיהיה זה \u0003כהן,\u0004 ומן הצד האחר: \u0003מה להלן\u0004 בשלמים \u0003בעלים,\u0004 שהרי נאמר \"המקריב... ידיו תביאנה\" — \u0003אף כאן\u0004 בביכורים \u0003בעלים. הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אפשר שתיעשה התנופה גם על ידי הכהן וגם על ידי הבעלים? \u0003מניח כהן ידיו תחת ידי בעלים ומניף\u0004 יחד אתו.","\u0003אמר רבא בר אדא אמר ר' יצחק: בכורים\u0004"],["\u0003מאימתי מחייבין עליהם\u0004 מיתה את הזר שאכלם — \u0003משיראו פני הבית\u0004 (בית המקדש), כלומר משיכנסו לתחום המקדש. ומעירים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר הלכה זו — \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: בכורים\u0004 שהיו \u0003מקצתן בחוץ\u0004 לבית המקדש \u0003ומקצתן בפנים,\u0004 אותם \u0003שבחוץ\u0004 — \u0003הרי הן\u0004 נחשבים \u0003כחולין לכל דבריהם\u0004 (דיניהם), \u0003שבפנים\u0004 — \u0003הרי הן כהקדש לכל דבריהם.\u0004","\u0003אמר רב ששת: בכורים, הנחה\u0004 ליד המזבח — \u0003מעכבת בהן, קרייה\u0004 (קריאה) — \u0003אין מעכבת בהן.\u0004","ומעירים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יוסי אומר שלשה דברים משום\u0004 (בשם) \u0003שלשה זקנים,\u0004 וזה אחד מהם, \u0003ר' ישמעאל אומר: יכול יעלה אדם מעשר שני בזמן הזה\u0004 (לאחר חורבן הבית) \u0003בירושלים, ויאכלנו? ו\u0004לכאורה \u0003דין\u0004 (סברה) \u0003הוא,\u0004 שיש מקום ללמוד שאסור הדבר מסברה, שכן קרבן \u0003בכור טעון הבאת מקום\u0004 שצריך להביאו למקדש לזובחו שם, \u0003ומעשר שני טעון הבאת מקום\u0004 לירושלים, \u0003מה בכור אינו\u0004 נאכל \u0003אלא בפני הבית\u0004 — \u0003אף מעשר אינו\u0004 נאכל \u0003אלא בפני הבית.\u0004","ויש לדחות: \u0003מה לבכור שכן טעון\u0004 (חייב) \u0003מתן דמים ו\u0004הקרבת \u0003אימורין\u0004 (חלקים פנימיים של הקרבן) \u0003לגבי מזבח,\u0004 ולכן כשאין המקדש בנוי אין מביאים אותו. מה שאין כן במעשר שני, שצריך רק לאוכלו בירושלים! ומשיבים: \u0003בכורים יוכיחו,\u0004 שהם אינם טעונים מתן דמים, ובכל זאת הם מובאים ונאכלים רק בפני הבית. ויש לדחות ראיה זאת: \u0003מה לבכורים\u0004 — \u0003שכן טעונים הנחה\u0004 לפני המזבח, אבל מעשר שני שאינו טעון מזבח — שמא צריך להביא אותו גם בזמן הזה לירושלים ולאוכלו שם,","\u0003תלמוד לומר: \"ואכלת לפני ה' אלהיך...\u0004 מעשר דגנך... ובכורות בקרך וצאנך\" (דברים יד, כג), \u0003מקיש\u0004 (משווה) הכתוב \u0003מעשר לבכור, מה בכור אינו\u0004 נאכל \u0003אלא לפני הבית\u0004 — \u0003אף מעשר אינו\u0004 נאכל \u0003אלא לפני הבית.\u0004 ומכאן מוכיח רב ששת את דבריו: \u0003ואם איתא\u0004 \u0005[יש]\u0006 שקריאה מעכבת ביכורים, מדוע נאמר רק \"מה לביכורים שכן טעונים הנחה\"? \u0003ליפרוך\u0004 \u0005[שיקשה\u0006 אחרת\u0005]:\u0006 \u0003מה לבכורים\u0004 — \u0003שכן טעונין קרייה ו\u0004גם \u0003הנחה!\u0004","\u0003אמר רב אשי:\u0004 מה שלא נזכרה קריאה — אין זו הוכחה, שהרי \u0003נהי דעיכובא ליכא\u0004 \u0005[גם אם אמנם שעיכוב אין]\u0006 בקריאה, ואולם \u0003מצוה מי ליכא\u0004 \u0005[האם אין]\u0006 בכך? ולכל הדעות מצוה היא לקרוא, \u0003ו\u0004מכל מקום \u0003לימא\u0004 \u0005[שיאמר]\u0006 שיש \u0003מצוה\u0004 בקריאה \u0003וליפרוך\u0004 \u0005[ויפרוך]\u0006 גם בכך את הראיה מביכורים, שבביכורים יש מצות קריאה לכתחילה, מה שאין כן במעשר! \u0003אלא אמר רב אשי,\u0004 טעם אחר יש שלא הוזכרה כאן קריאה: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003בכורי הגר, דבעי למימר\u0004 \u0005[ש\u0006הוא \u0005צריך לומר]\u0006 \"באתי אל הארץ \u0003אשר נשבע [ה'] לאבתינו\"\u0004 (דברים כו, ג) \u0003ולא מצי אמר\u0004 \u0005[ואינו יכול לומר]\u0006 זאת, שהרי לאבותיו של הגר לא נשבע ה', ולכן הוא מביא ביכורים ואינו קורא, משום כך \u0003לא פסיקא ליה\u0004 \u0005[אין\u0006 זה \u0005חתוך,\u0006 מוחלט, \u0005לו],\u0006 כדי שיוכל להקשות ממנו.","ושואלים: מדוע צריך התנא ללמוד שאין מביאים מעשר שני לירושלים בזמן הזה מההיקש בכתוב? \u0003וליהדר דינא\u0004 \u0005[ושיחזור\u0006 יהפוך, את \u0005הדין]\u0006 \u0003ותיתי\u0004 \u0005[ותבוא]\u0006 לו ההוכחה \u0003ב\u0004דרך הלימוד של \u0003\"מה הצד\",\u0004 שישווה מצד אחד לביכורים ומצד שני לבכור, וילמד מן הצד השווה לשניהם — שטעונים הבאת מקום — שגם מעשר שטעון הבאת מקום, איננו טעון הבאה שלא בפני הבית! ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]\u0006 השוואה זו, ולומר: \u0003מה להצד השוה שבהן\u0004 — \u0003ש\u0004על כל פנים \u0003כן יש בהן צד מזבח,\u0004 מה שאין כן במעשר.","ושואלים: \u0003ומאי קסבר\u0004 \u0005[ומה סבור]\u0006 ר' ישמעאל כשהניח מתחילה שבכור טעון הבאה רק בפני הבית? \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 בכלל ש\u0003קדושה ראשונה\u0004 של המקדש \u0003קדשה לשעתה וקדשה לעתיד לבא,\u0004 והמקום נשאר מקודש גם כשאין בית המקדש בנוי, אם כן \u0003אפילו בכור נמי\u0004 \u0005[גם כן]\u0006 יביא אותו למקום המקדש, ויקריב אותו במזבח כלשהו וייאכל, \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 ש\u0003קדושה ראשונה קדשה לשעתה ולא קדשה לעתיד לבא\u0004 — \u0003אפילו בכור נמי תבעי\u0004 \u0005[גם כן תישאל]\u0006 השאלה במקרה דומה (כמבואר להלן), האם הוא נאכל בירושלים!","\u0003אמר רבינא: לעולם\u0004 יש לומר כי \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003קדשה לשעתה ולא קדשה לעתיד לבא, ו\u0004מדוע פשוט לנו שאינו נאכל? \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003בבכור שנזרק דמו קודם חורבן הבית, וחרב הבית, ועדיין בשרו קיים.\u0004 וטעם הדבר הוא משום ש\u0003מקשינן\u0004 \u0005[מקישים,\u0006 משווים \u0005אנו]\u0006 \u0003בשרו לדמו, מה דמו\u0004 צריך להיות נזרק \u0003במזבח\u0004 — \u0003אף בשרו\u0004 אינו נאכל אלא \u0003ב\u0004זמן \u0003מזבח. ו\u0004בעקבות כך \u0003מקיש\u0004 (ומשווה) גם דין \u0003מעשר ל\u0004דין \u0003בכור,\u0004 לומר שאף אכילת מעשר תלויה בקיום הבית.","ושואלים: \u0003וכי דבר הלמד בהקש חוזר ומלמד\u0004 לדין אחר \u0003בהקש?\u0004 והרי אנו יודעים שבכל דיני קדשים אין למדים למד מלמד (דבר שנלמד באחת המידות שהתורה נדרשת בהם) אלא במקרים יוצאים מן הכלל, וכל ענין צריך מקור לעצמו! ומשיבים: \u0003מעשר דגן חולין הוא,\u0004 ולכן לא חלה לגביו הגבלה זו שיש בדיני קדשים, שלענין חולין למדים גם למד מלמד."],["ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003למד אזלינן\u0004 \u0005[אנו הולכים],\u0006 שאם הדבר שנלמד בהיקש הוא חולין — אפשר ללמוד מדבר שהוא קדשים, למרות שהוא עצמו נלמד בהיקש. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003מלמד אזלינן\u0004 \u0005[אנו הולכים],\u0006 ואם המלמד הוא דבר שבקדשים אין למדים ממנו, מאחר שהוא עצמו נלמד בהיקש, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 והרי כאן המלמד הוא קדשים, ובקדשים אין למדים למד מלמד!","ומשיבים: לשיטה זו אין כאן כלל \"למד מלמד\", שכן \u0003דם ובשר חדא מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 ואין כלל היקש מדם לבשר. וכיון שדם ובשר נחשבים כדבר אחד, הרי יש פה רק היקש אחד — שלמדים מדמו ובשרו של בכור לדין מעשר.","שנינו במשנה שהאוכל \u0003קדשי קדשים\u0004 וכו' ומעשר שני חוץ לחומה — לוקה. ומקשים: הלא כבר \u0003תנינא חדא זימנא\u0004 \u0005[שנינו\u0006 זאת \u0005פעם אחת]\u0006 במשנה הראשונה בפרק זה, בכלל הלוקים: האוכל \u0003מעשר שני והקדש שלא נפדו,\u0004 ומדוע חזר ושנה דין מעשר שני? \u0003אמר ר' יוסי בר חנינא:\u0004 יש הבדל במקרים בהם עוסקות שתי המשניות, שכן \u0003סיפא\u0004 \u0005[סופה]\u0006 של המשנה, המקרה שמדובר בו במשנה שלנו, עוסק \u0003במעשר שני טהור וגברא\u0004 \u0005[ואדם]\u0006 \u0003טהור, דקא אכיל\u0004 \u0005[שאוכל]\u0006 אותם \u0003חוץ לחומה\u0004 של ירושלים. \u0003רישא\u0004 \u0005[בתחילה]\u0006 במשנה הראשונה, מדובר \u0003במעשר שני טמא וגברא\u0004 \u0005[ואיש]\u0006 \u0003טמא, וקא אכיל ליה\u0004 \u0005[והוא אוכל אותו]\u0006 \u0003בירושלים.\u0004","ושואלים: \u0003ומנלן דמחייב עליה\u0004 \u0005[ומנין לנו שמתחייב עליו\u0006 מלקות\u0005]\u0006 \u0003משום טומאה?\u0004 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 נאמר בוידוי המעשר \u0003\"לא בערתי ממנו בטמא\"\u0004 (דברים כו, יד), והלשון הכללית הזו באה ללמד: \u0003בין שאני\u0004 (האדם) \u0003טמא והוא\u0004 (המעשר) \u0003טהור, בין שאני טהור והוא טמא.\u0004 ומוסיף התנא: \u0003והיכן מוזהר על אכילה איני יודע.\u0004 שאף שמן הכתוב ברור שאסור לאכול מעשר בטומאה, לא מצאנו מפורש היכן נאמר האיסור הזה.","ועוד לפני שמביא התנא ראיה לכך, תוהים: הלא לענין אכילת המעשר ב\u0003טומאת הגוף\u0004 (כשהאדם טמא) \u0003בהדיא כתיב\u0004 \u0005[במפורש נאמר]\u0006 \u0003\"נפש אשר תגע בו וטמאה עד הערב ולא יאכל מן הקדשים\"\u0004 (ויקרא כב, ו), וכפי שדייקו חכמים, מדובר שם גם על מעשר שני — ומכאן שהוא אסור באכילה לאדם טמא! \u0003אלא\u0004 כשאמר התנא \"היכן מוזהר על האכילה איני יודע\", שאלתו היתה: \u0003טומאת עצמו\u0004 כשהמעשר עצמו טמא \u0003מנין\u0004 לנו שאסור גם הטהור לאכול אותו?","והתשובה לכך היא: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לענין מעשר שני \u0003\"לא תוכל לאכל בשעריך\u0004 מעשר דגנך תירושך ויצהרך...\" (דברים יב, יז), \u0003ולהלן\u0004 בדין בכור שנפל בו מום \u0003הוא אומר \"בשעריך תאכלנו הטמא והטהור\"\u0004 (דברים טו, כב),","\u0003ותניא דבי\u0004 \u0005[ושנויה\u0006 ברייתא על כך \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אפילו טמא וטהור אוכלין\u0004 בו בבשרו של הבכור \u0003בקערה אחת ואין חוששין,\u0004 שאין איסור לא לאוכלו בטומאת הגוף ולא לאוכלו כשהוא טמא. \u0003וקאמר רחמנא\u0004 \u0005[ואמרה תורה]:\u0006 \u0003היאך\u0004 \u0005[אותו]\u0006 \u0003טמא דשרי\u0004 \u0005[שהותר]\u0006 \u0003לך\u0004 לאכול \u0003גבי\u0004 \u0005[יחד]\u0006 עם \u0003טהור התם\u0004 \u0005[שם]\u0006 \"בשעריך\", \u0003הכא לא תיכול\u0004 \u0005[כאן,\u0006 במעשר \u0005לא תאכל]\u0006 באותו אופן, שאינך רשאי לאכול מעשר בטומאה בירושלים, כמו שאתה אוכל בכור בעל מום בשעריך.","העמדנו את דין מעשר שני שלא נפדה, שהובא במשנה הראשונה בפרק זה, במעשר טמא, ומשמע מן הדברים שניתן לפדות אותו, ושואלים: \u0003ומנא לן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003בר\u0004 \u0005[בן]\u0006 \u0003פדייה הוא,\u0004 שאפשר לפדות את המעשר שנטמא?","ש\u0003אמר ר' אלעזר: מנין למעשר שני שנטמא שפודין אותו אפילו בירושלים? תלמוד לומר \"כי לא תוכל שאתו\u0004 כי ירחק ממך המקום... ונתתה בכסף...\" (דברים יד, כד— כה), \u0003ואין \"שאת\" אלא אכילה, שנאמר \"וישא משאת מאת פניו\"\u0004 (בראשית מג, לד) כלומר, מתנות של דברים הנאכלים. ולכן \"לא תוכל שאתו\" משמעו כמו \"לא תוכל לאכלו\", ומדוע — מפני שנטמא, ואמרה תורה שפודים אותו, גם אם המקום אינו רחוק אלא בירושלים.","ואגב זה מביאים דרשה אחרת ש\u0003אמר רב ביבי אמר רב אסי: מנין למעשר שני טהור שפודין אותו\u0004 \u0003אפילו בפסיעה אחת חוץ לחומה,\u0004 ולאו דוקא כשהיה זה במרחק גדול (\"כי ירחק ממך הדרך\")? \u0003שנאמר \"כי לא תוכל שאתו\",\u0004 שאם יש סיבה שאי אפשר לשאתו ולהכניסו — פודים אותו, בין שהיה במקום קרוב או רחוק. ומקשים: \u0003האי מבעי ליה\u0004 \u0005[\u0006הרי פסוק \u0005זה נצרך לו]\u0006 \u0003ל\u0004מה שלמד ממנו \u0003ר' אליעזר\u0004 (אלעזר) למעשר שני שנטמא, שפודים אותו בירושלים!","ומשיבים: \u0003אם כן,\u0004 שנאמר הדבר רק לשם הלימוד שלמד ר' אלעזר, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 במפורש \u0003\"לא תוכל לאוכלו\", מאי\u0004 \u0005[מה]\u0006 שינוי הלשון \u0003\"שאתו\"?\u0004 ושואלים: אם כן, \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכל מקרא זה \u0003כולו להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 לענין פדיונו אף במקום קרוב! ומשיבים: \u0003אם כן, לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"לא תוכל ליטלו\", מאי\u0004 \u0005[מה]\u0006 מלמדת לשון \u0003\"שאתו\"? שמע מינה תרתי\u0004 \u0005[למד ממנה שתים],\u0006 שתי הלכות אלה.","ובענין זה מסופר, \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב חנינא ורב הושעיא\u0004 איתו, \u0003וקא מבעיא להו\u0004 \u0005[ונשאלה להם\u0006 שאלה\u0005]:\u0006 \u0003אפיתחא\u0004 \u0005[על הפתח]\u0006 של \u0003ירושלים,\u0004 מה דינו? האם ניתן לפדות מעשר שני? ומסבירים את שאלתם: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 היה להם שאם \u0003הוא בחוץ ומשאו\u0004 (ובתוכו המעשר) \u0003בפנים\u0004 — \u0003קלטוהו מחיצות\u0004 את המעשר, ודינו כנכנס. ואולם השאלה היא אם היה \u0003הוא בפנים ומשאו בחוץ, מהו?\u0004 וצדדי השאלה: האם משום שהמעשר עצמו עדיין לא נכנס לירושלים יכול הוא לפדותו. או שמא אף כי המעשר עדיין מחוץ לירושלים, כיון שהאיש הנושאו כבר נכנס — נחשב כאילו גם המעשר נכנס?","\u0003תנא להו ההוא סבא\u0004 \u0005[שנה להם זקן אחד]\u0006 \u0003בדבי\u0004 \u0005[ב\u0006ברייתות של \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמעון בן יוחי\u0004 בתשובה לשאלתם: לשון הכתוב בענין זה \u0003\"כי ירחק ממך המקום\"\u0004 (דברים יד, כד), \"ממך\", כוונתה — \u0003ממילואך,\u0004 האדם וכל הצמוד והנקשר אליו, ובכלל זה משא שעליו. ולכן, אם חלק ממילואו — בין הוא ובין משאו נמצא בפנים, הרי זה נחשב כאילו היה כולו בפנים, ולכן לא ניתן לפדות את המעשר.","ועוד בענין דומה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003נקיט ליה בקניא\u0004 \u0005[מחזיק אותו\u0006 את המעשר \u0005בקנה]\u0006 והוא תלוי מאחריו, \u0003מאי\u0004 \u0005[מה]\u0006 דינו לענין זה? וצדדי השאלה: כיון שהקנה ארוך והמעשר אינו מונח ממש על גופו — אינו נחשב כמילואו, או מאחר שהוא בכל זאת נושאו הריהו כחלק מגופו? לשאלה זו לא נמצא פתרון, והשאירו אותה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר ר' אסי אמר ר' יוחנן: מעשר שני מאימתי חייבין עליו\u0004 אם אוכלים אותו מחוץ לחומה — \u0003משראה פני החומה\u0004 ונכנס כבר לירושלים. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין מעשר שני \u0003\"לפני ה' אלהיך תאכלנו\" (שנה בשנה)\u0004 (שם יב, יח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 קודם לכן \u0003(כי) \"לא תוכל לאכל בשעריך\"\u0004 (שם יז), ויש להבין כי \u0003כל היכא דקרינן ביה\u0004 \u0005[בכל מקום שאנו קוראים בו]\u0006 \u0003\"לפני ה' אלהיך תאכלנו\"\u0004 — \u0003קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 את האיסור \u0003\"לא תוכל לאכול בשעריך\",\u0004 שיש איסור לאו באכילתו בחוץ. \u0003וכל היכא דלא קרינן ביה\u0004 \u0005[וכל מקום שאין אנו קוראים בו]\u0006 \u0003\"לפני ה' אלהיך תאכלנו\"\u0004 שהוא עדיין בחוץ — \u0003לא קרינן ביה\u0004 \u0005[אין אנו קוראים בו]\u0006 \u0003\"לא תוכל לאכול בשעריך\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו, \u0003ר' יוסי אומר: כהן שעלתה בידו תאנה של טבל\u0004 שלא הופרשו ממנה תרומות ומעשרות, והוא רוצה להפריש ממנה תרומה ומעשר כדי שיוכל לאוכלה, \u0003אמר: תאנה זו, תרומתה\u0004 (התרומה שצריך להפריש ממנה) אני קובע אותה \u0003בעוקצה\u0004 (בחלק המחבר את התאנה לאילן), \u0003מעשר ראשון\u0004 יהא \u0003בצפונה, ומעשר שני לדרומה. ו\u0004מדובר כשאותה שנה \u0003היא שנת מעשר שני\u0004 שצריך להפריש בה מעשר שני (בשנה הראשונה, השניה, הרביעית או החמישית של מחזור שנות השמיטה), \u0003והוא בירושלים\u0004 כשאמר לשון זו. \u0003או\u0004 שהיתה זו שנת \u0003מעשר עני\u0004 (בשנה השלישית או השישית למחזור השמיטה), ואמר שמעשר עני לדרומה \u0003והוא בגבולין\u0004 (מחוץ לירושלים), אם \u0003אכלה —\u0004 ל"],["\u0003לוקה אחת,\u0004 משום שלא הפריש ממנה תרומת מעשר (מעשר מן המעשר הראשון), ולפני הפרשה זו התאנה היא עדיין טבל. אבל אם היה מפריש ממנה גם תרומת מעשר היה רשאי לאכול הכל, שהרי כהן הוא ורשאי לאכול תרומה ותרומת מעשר, ששתיהן ניתנות לכהנים.","\u0003וזר שאכלה\u0004 את התאנה הזו — \u0003לוקה שתים,\u0004 גם משום טבל, וגם משום חלק התרומה שיש בה, שהיא אסורה עליו. ומעירים, \u0003שאילו בתחלה אכלה\u0004 הזר, לפני שהפריש ממנה את התרומה והמעשרות — \u0003אינו לוקה אלא אחת,\u0004 משום טבל. ואילו עתה שיש בה גם חלק תרומה — הרי הוא לוקה גם משום התרומה. עד כאן לשון הברייתא.","וממה ששנינו בה \"והיא שנת מעשר שני והיא בירושלים\", יש לדייק: \u0003טעמא דאיתיה\u0004 \u0005[הטעם,\u0006 דווקא משום \u0005שהוא]\u0006 עכשיו \u0003בירושלים,\u0004 ושם הוא רשאי לאכול את המעשר השני, הדין כן, \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה תאנה זו \u0003בגבולין,\u0004 והפריש מעשר שני — \u0003לוקה שלש\u0004 על אכילת תאנה זו, גם על שאכל מעשר שני שלא במקומו, \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שהמעשר הזה בכלל מי \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003רואה\u0004 את \u0003פני\u0004 ה\u0003חומה\u0004 בירושלים והיה עדיין בגבולין. וקשה על דברי ר' יוחנן, שאמר שאינו לוקה עד שיראה פני חומה תחילה! ומתרצים: כאן מדובר \u0003דעיילי\u0004 \u0005[שהכניסו]\u0006 את התאנה הזו לתוך ירושלים, וחזרו \u0003ואפקי\u0004 \u0005[והוציאו\u0006 אותה\u0005],\u0006 ולכן היה לוקה שלוש.","ומקשים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך, מה\u0006 בא \u0005לומר]?\u0006 הרי אם נכנסה התאנה לתוך ירושלים — אין כל חידוש שלוקה משום מעשר שני שהוצא מחוץ לתחומו! ומשיבים: יש בדבר חידוש, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון דעיילינהו בטיבלייהו\u0004 \u0005[שהכניס אותן,\u0006 את התאנים, \u0005בעודן טבל]\u0006 לפני שהפריש מהן תרומות ומעשרות, \u0003וקסבר\u0004 \u0005[וסבור]\u0006 ר' יוסי כי \u0003מתנות שלא הורמו\u0004 עדיין — \u0003כמי שהורמו דמיין\u0004 \u0005[נחשבות].\u0006 והוא החידוש שבדבר, שאף שהמעשר השני לא היה מופרש בפועל, מכל מקום כיון שעתיד להפרישו, הרי חלים על אותו חלק שנועד למעשר כל דיני המעשר, ולכן אם הוציאו חוץ לירושלים ואכלו — לוקה.","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יוסי מתנות שלא הורמו כמי שהורמו דמי\u0004 \u0005[נחשבות]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' יוסי: לא נחלקו בית שמאי ובית הלל על פירות שלא נגמרה מלאכתן,\u0004 כלומר, שלא נגמרה מלאכת האיסוף שלהם, ועדיין לא חלה עליהם חובת הפרשת תרומות ומעשרות, \u0003ועברו\u0004 אז \u0003בירושלים\u0004 — \u0003שיפדה מעשר שני שלהן ויאכל בכל מקום,\u0004 משום שכל עוד לא הגיעו לגדר חיוב מעשר אין קדושת ירושלים חלה עליהם.","\u0003ועל מה נחלקו\u0004 — \u0003על פירות ש\u0004כבר \u0003נגמרה מלאכתן, ועברו בירושלים\u0004 קודם שיפרישו מהם תרומות ומעשרות, \u0003שבית שמאי אומרים:\u0004 כיון שנתחייבו בהפרשת מעשר שני, והיו בירושלים — \u0003יחזיר מעשר שני שלהם ויאכל בירושלים, ובית הלל אומרים: יפדה ויאכל בכל מקום. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003מתנות שלא הורמו כמי שהורמו דמיין\u0004 \u0005[נחשבות],\u0006 כיצד לשיטת בית הלל ניתן לפדות את המעשר השני? \u0003הא\u0004 \u0005[הרי]\u0006 משנכנסו הפירות לירושלים, כבר \u0003קלטוהו מחיצות\u0004 העיר את המעשר השני, גם אם לא הופרש בפועל, ואם כן שוב לא ניתן לפדותו! ומכאן שר' יוסי (שבוודאי הולך לשיטת בית הלל) סבור שמתנות שלא הורמו אינן נחשבות כאילו הורמו!","\u0003אמר רבה: מחיצה לאכול\u0004 ההלכה שאסור לאכול את המעשר השני מחוץ לירושלים היא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003מחיצה\u0004 לענין \u0003לקלוט\u0004 ההלכה שמעשר שני שנכנס לחומות ירושלים נקלט ואסור לפדותו ולהוציאו למקום אחר — היא \u0003דרבנן\u0004 \u0005[מדברי חכמים].\u0006 \u0003וכי גזור רבנן\u0004 \u0005[וכאשר גזרו חכמים]\u0006 שלא להוציא מעשר שנכנס לפנים מן המחיצות — הרי זה \u0003כי איתיה בעיניה\u0004 \u0005[כאשר\u0006 המעשר \u0005ישנו\u0006 כבר \u0005בעינו]\u0006 לאחר שהופרש, אבל \u0003בטבליה לא גזור רבנן\u0004 \u0005[ב\u0006עודו \u0005טבל לא גזרו חכמים].\u0006","\u0003רבינא אמר:\u0004 ר' יוסי עוסק במעשר שני שהופרש כבר ונכנס לירושלים, והחידוש בדבריו הוא שמדובר כאן בתאנה שלא נכנסה ממש לירושלים, אלא \u0003כגון דנקיט ליה בקניא\u0004 \u0005[שמחזיק אותה,\u0006 את התאנה הזו \u0005בקנה]\u0006 מבחוץ, אלא שהוא עצמו כבר בתוך ירושלים. \u0003ותפשוט בעיא\u0004 \u0005[ותפתור\u0006 על ידי כך את \u0005בעייתו]\u0006 של \u0003רב פפא,\u0004 שאם הוא בפנים ומחזיק מעשר בקנה מחוץ לעיר — נחשב כאילו נכנס.","\u0003הקורח קרחה בראשו, ו\u0004כן \u0003המקיף\u0004 (מגלח) \u0003פאת ראשו\u0004 (החלק הסמוך לאוזן), \u0003והמשחית פאת זקנו, והשורט שריטה אחת על המת\u0004 משום אבילות — הרי זה \u0003חייב\u0004 על כל אחד מהם מלקות. \u0003שרט שריטה אחת על חמשה מתים, או חמש שריטות על מת אחד\u0004 — \u0003חייב על כל אחת ואחת.\u0004","\u0003על\u0004 הקפת פאת \u0003הראש\u0004 חייב \u0003שתים, אחת מכאן\u0004 בשיער לצד אוזן אחת, \u0003ואחת מכאן\u0004 לצד האוזן השנית. \u0003על הזקן\u0004 יש \u0003שתים מכאן\u0004 שתי פאות מצד אחד של הפנים, \u0003ושתים מכאן\u0004 מצידו האחר, \u0003ו\u0004עוד \u0003אחת מלמטה\u0004 בסנטר. \u0003ר' אליעזר אומר: אם ניטלו\u0004 כל פאות הזקן \u0003כולן כאחת\u0004 — \u0003אינו חייב אלא אחת\u0004 על כולן.","ועוד הלכה בענין זה: \u0003ואינו חייב\u0004 על השחתת זקן \u0003עד שיטלנו בתער. ר' אליעזר אומר: אפילו לקטו במלקט\u0004 (כעין צבת קטנה, שתולש בה שערות) \u0003או ברהיטני\u0004 שחותך, כעין מקצוע — הרי זה \u0003חייב.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הפסוק האמור בכהנים \"לא יקרחו קרחה בראשם\" (ויקרא כא, ה): \u0003\"לא יקרחו\", יכול אפילו קרח ארבע וחמש קריחות\u0004 בבת אחת \u0003לא יהא חייב אלא אחת? תלמוד לומר\u0004 בלשון יחיד \u0003\"קרחה\"\u0004 — \u0003לחייב על כל קרחה וקרחה\u0004 בפני עצמה. ומה שנאמר \u0003\"בראשם\" מה תלמוד לומר,\u0004 מה אנו למדים ממנו? \u0003לפי שנאמר \"לא תתגדדו ולא תשימו קרחה בין עיניכם למת\"\u0004 (דברים יד, א), \u0003יכול לא יהא חייב אלא על בין העינים בלבד, מנין לרבות כל הראש\u0004 לאיסור קרחה? \u0003תלמוד לומר \"בראשם\"\u0004 (ויקרא שם) — \u0003לרבות כל הראש.\u0004","\u0003ואין לי\u0004 איסור זה \u0003אלא בכהנים שריבה בהן הכתוב מצות יתירות,\u0004 שהרי הכתוב בספר ויקרא מדבר בדיני כהנים, \u0003ישראל מנין?\u0004","\u0003נאמר כאן\u0004 (בספר דברים, לענין ישראל) \u0003\"קרחה\", ונאמר להלן\u0004 (בספר ויקרא, בכהנים) \u0003\"קרחה\", מה להלן,\u0004 בכהנים, \u0003חייב על כל קרחה וקרחה, וחייב על\u0004 קרחה שעושה ב\u0003ראש\u0004 כולו \u0003כבין העינים\u0004 — \u0003אף כאן,\u0004 בישראל, \u0003חייב על כל קרחה וקרחה, וחייב על הראש כבין העינים. ומה להלן,\u0004 במה שנאמר לכל ישראל, מפורש שהוא \u0003על מת\u0004 — \u0003אף כאן על מת.\u0004","לפרטי הענין שואלים: \u0003הני\u0004 \u0005[אותן]\u0006 \u0003ארבע וחמש קריחות\u0004 שעושה על מת אחד, שחייב על כל אחת ואחת, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שעושה אותן \u0003בזה אחר זה, ובחמש התראות,\u0004 שבכל פעם שהוא עושה מתרים בו שלא יעשה כן — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי הוא כעובר אותה עבירה פעמים אחדות, שנענש על כל עבירה שהתרו בו עליה!"],["\u0003אלא\u0004 תאמר שהיה זה \u0003בחדא התראה\u0004 \u0005[בהתראה אחת],\u0006 ואולם במקרה זה \u0003מי מחייב\u0004 \u0005[האם\u0006 הוא \u0005מתחייב]\u0006 על כך? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נזיר שהיה שותה יין כל היום\u0004 — \u0003אינו חייב אלא\u0004 עונש מלקות \u0003אחת.\u0004 ורק אם \u0003אמרו לו\u0004 כמה פעמים בהתראה: \u0003\"אל תשתה, אל תשתה\", והוא שותה\u0004 אחרי כל פעם ופעם — \u0003חייב\u0004 מלקות \u0003על כל אחת ואחת!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא למקרה שלאחר שהתרו בו פעם אחת \u0003סך חמש אצבעותיו נשא\u0004 (סם להשרת השיער) \u0003ואותבינהו\u0004 \u0005[והניח אותן]\u0006 \u0003בבת אחת\u0004 על שיער ראשו, ועשה על ידי כך חמש קרחות בבת אחת, \u0003דהויא ליה\u0004 \u0005[שהריהי\u0006 נחשבת \u0005לו]\u0006 אותה התראה שהתרו בו, כ\u0003התראה לכל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 מהקרחות. והוא החידוש בכתוב זה, שעשיית כל קרחה היא עבירה בפני עצמה.","בפרטי הדין שואלים: \u0003וכמה\u0004 הוא \u0003שיעור קרחה\u0004 להתחייב עליו? \u0003רב הונא אומר: כדי שיראה מראשו\u0004 מקום עור הראש בלא שיער. \u0003ר' יוחנן אומר משום\u0004 (בשם) \u0003ר' אלעזר בר' שמעון: כגריס.\u0004 ומעירים: מחלוקת זו היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 שכבר נחלקו באותו נושא, ששנינו: \u0003כמה שיעור קרחה\u0004 — \u0003כגריס, אחרים אומרים: כדי שיראה מראשו.\u0004","\u0003אמר רב יהודה בר חביבא: פליגי\u0004 \u0005[חלוקים]\u0006 \u0003בה\u0004 בבעיה זו \u0003תלתא תנאי\u0004 \u0005[שלושה תנאים],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אומר: כגריס, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אומר: כדי שיראה מראשו, וחד\u0004 \u0005[ואחד]\u0006 \u0003אומר: כשתי שערות. ואיכא דמפיק\u0004 \u0005[ויש שמוציא]\u0006 מהשיטות הללו את השיעור של \u0003שתי שערות, ומעייל\u0004 \u0005[ומכניס]\u0006 במקום זה שיעור \u0003בכעדשה. וסימנך,\u0004 כדי לזכור את חילוף הגרסה, המשנה בדיני צרעת: \u0003בהרת\u0004 המטמאה משום נגע — שיעורה \u0003כגריס, ומחיה\u0004 בשר חי הגדל בתוך הבהרת — שיעורו \u0003בכעדשה.\u0004","כיוצא בזה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הנוטל מלא פי הזוג\u0004 (המספריים) מן השיער \u0003בשבת\u0004 — \u0003חייב. וכמה\u0004 הוא \u0003\"מלא פי הזוג\"? אמר רב יהודה: שתים\u0004 (שתי שערות). ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לקרחה שתים,\u0004 משמע שלענין שבת יש שיעור אחר! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003וכן לקרחה שתים.\u0004 כלומר, לא בא התנא לחלק בין ההלכות, אלא לצרפן.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הנוטל מלא פי הזוג בשבת חייב, וכמה \"מלא פי הזוג\"\u0004 — \u0003שתים. ר'\u0004 \u0003אליעזר אומר: אחת. ומודים חכמים לר' אליעזר במלקט\u0004 שערות \u0003לבנות מתוך שחורות,\u0004 שהנוטל \u0003אפילו אחת\u0004 — \u0003שהוא חייב,\u0004 משום שעשה על ידי ליקוט זה מלאכה שלימה. כי אם הוא מקפיד ורוצה לעקור דווקא שערה זו, הרי עשה מעשה שלם בעקירה זו. ומעירים: \u0003ודבר זה אפילו בחול אסור\u0004 לאיש לעשותו, \u0003משום\u0004 מה \u0003שנאמר \"לא ילבש גבר שמלת אשה\"\u0004 (דברים כב, ה), וכל מעשה התייפות כזה הוא מנהג אשה, ואסור לגבר לעשותו.","שנינו במשנה: \u0003והמקיף פאת ראשו. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פאת ראשו\u0004 — זה \u0003סוף ראשו, ואיזהו סוף ראשו\u0004 — \u0003זה המשוה\u0004 (מיישר) \u0003צדעיו,\u0004 את גובה קו השיער של צידי הראש, \u0003ל\u0004שיער של \u0003אחורי אזנו ולפדחתו\u0004 (מצחו). שאם השיער גזור בשוה מסביב, שאין פאות הראש ניכרות — הרי זה עובר משום הקפת הראש.","\u0003תני\u0004 \u0005[שנה]\u0006 ה\u0003תנא\u0004 (חוזר המשניות). \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא: אחד המקיף ואחד הניקף\u0004 (זה שהקיפו שערו) — לוקה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא בתמיהה: \u0003מאן דאכיל תמרי בארבילא לקי\u0004 \u0005[מי שאוכל תמרים בכברה לוקה]?\u0006 כלומר, הרי הניקף לא עשה דבר, ומשום מה ילקה? והסביר רב חסדא לתנא: \u0003דאמר לך מני\u0004 \u0005[שאומר לך\u0006 אדם: ברייתא זו, כשיטת \u0005מי היא]?\u0006 אמור לו: כדעת \u0003ר' יהודה היא,\u0004 ש\u0003אומר: לאו שאין בו מעשה לוקין עליו,\u0004 ולכן גם הניקף לוקה, אף שלא עשה מעשה.","\u0003רבא אומר:\u0004 אפשר לפרש שמדובר כאן \u0003במקיף לעצמו\u0004 את פאת ראשו, ולכן הוא חייב גם משום מקיף וגם משום ניקף, \u0003ו\u0004ל\u0003דברי הכל,\u0004 שהרי הוא עושה מעשה. \u0003רב אשי אומר:\u0004 פה מדובר \u0003במסייע\u0004 הניקף למקיף. שהיה מסייע בתנועת ראשו לתספורת, ועושה בכך מעשה, \u0003ו\u0004לכן ל\u0003דברי הכל\u0004 חייב.","שנינו במשנה: \u0003והמשחית פאת זקנו. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פאת זקנו\u0004 — \u0003סוף זקנו, ואיזהו סוף זקנו\u0004 — \u0003שבולת זקנו,\u0004 כלומר כל אותן פאות שמנה במשנה, שיש בהן שיער הנמצא במקום אחד, כעין שבולת.","שנינו במשנה: \u0003והמשרט שריטה אחת\u0004 על המת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 מדרש הלכה זה: נאמר \"ושרט לנפש לא תתנו בבשרכם\" (ויקרא יט, כח). אילו היה כתוב רק \u0003\"ושרט\"\u0004 — \u0003יכול\u0004 היית לומר: על כל שריטה ששרט מתוך צערו, \u0003אפילו שרט על ביתו שנפל, ועל ספינתו שטבעה בים\u0004 — \u0003תלמוד לומר \"לנפש\"\u0004 (ויקרא יט, כח), לומר: \u0003אינו חייב אלא\u0004 כשמשרט \u0003על\u0004 נפש \u0003המת בלבד. ומנין למשרט חמש שריטות על מת אחד שהוא חייב על כל אחת ואחת\u0004 מהן? \u0003תלמוד לומר \"ושרט\"\u0004 — \u0003לחייב על כל שריטה ושריטה.\u0004","\u0003ר' יוסי אומר: מנין למשרט שריטה אחת על חמשה מתים, שהוא חייב על כל אחת ואחת\u0004 מן הנפשות ששרט עליהן? \u0003תלמוד לומר \"לנפש\",\u0004 לומר: \u0003לחייב על כל נפש ונפש.\u0004","ומקשים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאת אותו]\u0006 את הביטוי \"לנפש\", \u0003ל\u0004פטור את המשרט על \u0003ביתו שנפל ולספינתו שטבעה בים! ל\u0004"],["ומשיבים: דין זה למד ר' יוסי ממקום אחר, \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יוסי\u0004 ש\u0003שריטה\u0004 על מת \u0003וגדידה\u0004 על מת האמורה במקום אחר, \"לא תתגודדו\" (דברים יד, א), עבירה \u0003אחת היא, וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בגדידה \"לא תתגודדו ולא תשימו קרחה בין עיניכם \u0003למת\",\u0004 ומשמע — רק על המת, ולפיכך \"לנפש\" לא בא אלא לחייב על כל נפש ונפש.","ובענין זה מביאים עוד מה ש\u0003אמר שמואל: המשרט\u0004 בשרו על המת \u0003בכלי\u0004 — \u0003חייב. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: כל \u0003שריטה וגדידה אחת היא,\u0004 ששניהם נאמרו לשורט עצמו על מת, \u0003אלא ששריטה\u0004 היא \u0003ביד וגדידה\u0004 היא \u0003בכלי.\u0004 הרי שלא שייכת לשון \"משרט\" בכלי! ומשיבים: שמואל \u0003הוא\u0004 ש\u0003אמר כר' יוסי,\u0004 הסבור ששריטה וגדידה אחת היא לגמרי, ואין הבדל בין המונחים.","מסופר, \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו: השורט \u0003על מת, בין\u0004 ששרט \u0003ביד, בין בכלי\u0004 — \u0003חייב,\u0004 ואילו השורט \u0003על עבודה זרה, ביד\u0004 — \u0003חייב, בכלי\u0004 — \u0003פטור.\u0004 תהה על כך ר' יוחנן: \u0003והא איפכא כתיב\u0004 \u0005[והרי ההיפך\u0006 מזה \u0005נאמר]\u0006 בכהני הבעל \u0003\"ויתגדדו כמשפטם בחרבות וברמחים\"\u0004 (מלכים א יח, כח), הרי שכך הוא מנהגם (\"כמשפטם\") להתגודד בכלים! ולכן הורה לו ר' יוחנן לחוזר המשניות: \u0003אלא אימא\u0004 \u0005[אמור]\u0006 בברייתא זו להיפך: על עבודה זרה \u0003ביד\u0004 — \u0003פטור, בכלי\u0004 — \u0003חייב.\u0004","שנינו: \u0003וחייב על הראש\u0004 שתים, אחת מכאן ואחת מכאן. ומסופר, כי כאשר היה לומד משנה זו \u0003מחוי\u0004 \u0005[מראה\u0006 היה\u0005]\u0006 \u0003רב ששת בין פירקי רישא\u0004 \u0005[הראש],\u0006 במקום שמתחברים שני חלקי הראש, האחורי והקדמי, בצדעיים. וכן על מה ששנינו במשנה: \u0003ו\u0004חייב \u0003על הזקן, שתים מכאן ושתים מכאן ואחת מלמטה. מחוי\u0004 \u0005[מראה\u0006 היה\u0005]\u0006 \u0003רב ששת בין פירקי דיקנא\u0004 \u0005[הזקן]\u0006 בין חלקי הזקן.","ועוד שנינו במשנה כי \u0003ר' אליעזר אומר: אם נטלן\u0004 בבת אחת חייב אחת. ומסבירים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003חד לאו\u0004 \u0005[לאו אחד]\u0006 \u0003הוא\u0004 האיסור להשחית את פאת הזקן, ואינו חייב על כל פאה.","ועוד שנינו במשנה: \u0003ואינו חייב עד שיטלנו בתער.\u0004 ומביאים מדרש הלכה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"ופאת זקנם לא יגלחו\"\u0004 (ויקרא כא, ה), \u0003יכול\u0004 בכל אופן של גילוח הזקן, ו\u0003אפילו גלחו במספרים יהא חייב? תלמוד לומר \"לא תשחית\u0004 את פאת זקנך\" (ויקרא יט, כז), שאינו חייב על גילוח הזקן אלא באופן שמשחית אותו מעיקרו, ומספריים אינם משחיתים את השיער עד שורשו. וממשיכים: \u0003אי\u0004 \u0005[אם]\u0006 היה נאמר רק \u0003\"לא תשחית\"\u0004 בלבד, \u0003יכול אם לקטו במלקט ורהיטני\u0004 שהם משחיתים את השיער ועוקרים אותו, \u0003יהא\u0004 גם כן \u0003חייב? תלמוד לומר \"לא יגלחו\",\u0004 שהחיוב הוא רק כשעושה זאת דרך תגלחת, ואלו אינם דרך תגלחת.","\u0003הא כיצד\u0004 מצרפים את שני המקראות — שחייבים רק על \u0003גילוח שיש בו השחתה, הוי אומר זה תער.\u0004","ועוד שנינו במשנה: \u0003ר' אליעזר אומר: אפילו לקטו במלקט ורהיטני יהא חייב.\u0004 ושואלים: \u0003מה נפשך\u0004 \u0005[רצונך]\u0006 כלומר, בכל אופן שאתה רוצה לומר, תמוה הוא: \u0003אי גמיר\u0004 \u0005[אם למד\u0006 וקיבל מרבו\u0005]\u0006 \u0003גזירה שווה\u0004 זו, המשווה בין גילוח שנאמר בכהנים (ויקרא כא) ובין השחתה שנאמרה בישראל (ויקרא יט) — \u0003ליבעי\u0004 \u0005[שיצריך]\u0006 דווקא \u0003תער\u0004 כדי לחייבו, כמו חכמים. \u0003אי לא גמיר\u0004 \u0005[אם לא למד]\u0006 \u0003גזרה שוה\u0004 זו — \u0003מספרים נמי\u0004 \u0005[גם כן]\u0006 \u0003[לא]\u0004 יפטור, שהרי הוא בכלל גילוח!","ומשיבים: \u0003לעולם\u0004 יש לומר כי \u0003גמיר\u0004 \u0005[למד]\u0006 \u0003גזרה שוה\u0004 זו, \u0003ו\u0004אולם \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003הני נמי\u0004 \u0005[גם אלה]\u0006 מלקט ורהיטני, \u0003גילוח עבדי\u0004 \u0005[עושים].\u0006 שלא חלק על חכמים בעיקר הסברה, אלא בפרטי ההגדרה.","\u0003הכותב כתובת קעקע,\u0004 כתובת של צבע החרוטה בגוף, גם הוא בכלל הלוקים. אם \u0003כתב\u0004 בצבע \u0003ולא קעקע\u0004 (חקק) בבשרו, או \u0003קעקע ולא כתב\u0004 — \u0003אינו חייב, עד שיכתוב ויקעקע.\u0004 ובמה — \u0003בידו, ובכחול\u0004 (אותו שמים בעיניים) \u0003ובכל דבר\u0004 \u0003שהוא רושם\u0004 (עושה סימן). \u0003ר' שמעון בן יהודה משום\u0004 (בשם) \u0003ר' שמעון אומר: אינו חייב עד שיכתוב שם את השם, שנאמר \"וכתבת קעקע לא תתנו בכם אני ה' \"\u0004(ויקרא יט, כח).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 האם כוונת ר' שמעון היא שאינו חייב \u0003עד\u0004 ש\u0003יכתוב\u0004 בבשרו \u0003\"אני ה' \" ממש? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 לא זו הכוונה. אלא \u0003כדתני\u0004 \u0005[כמו ששנה]\u0006 \u0003בר קפרא: אינו חייב עד שיכתוב שם עבודה זרה, שנאמר \"וכתבת קעקע לא תתנו בכם אני ה' \",\u0004 לומר: אל תכתבו שם של עבודה זרה בבשרכם, שכן \u0003אני ה', ולא אחר.\u0004","\u0003אמר רב מלכיא אמר רב אדא בר אהבה: אסור לו לאדם שיתן אפר מקלה\u0004 (שריפה) \u0003על גבי מכתו\u0004 (פצעו) לשם רפואה, \u0003מפני שנראית ככתובת קעקע.\u0004 כיון שהיה רק מספר מצומצם של דברים שנאמרו בשמו של חכם זה, והיה עוד חכם בשם דומה, רב מלכיו, שאמר דברים בשם רב אדא בר אהבה, נותנים סימן להלכות אלה. \u0003אמר רב נחמן בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 ההלכות בענין \u0003שפוד, שפחות וגומות,\u0004 אותן אמר \u0003רב מלכיו,\u0004 ואילו ההלכות בענין \u0003בלורית,\u0004 בענין \u0003אפר מקלה, ו\u0004בענין \u0003גבינה,\u0004 אותן אמרן \u0003רב מלכיא.\u0004","\u0003רב פפא אמר:\u0004 לא כן, אלא \u0003מתניתין ומתניתא\u0004 \u0005[\u0006מה שנאמר לגבי \u0005המשנה והברייתא]\u0006 הוא מדברי \u0003רב מלכיא, שמעתתא\u0004 \u0005[השמועות]\u0006 שאינן קשורות למשניות, הן של \u0003רב מלכיו. וסימניך\u0004 שתזכור מי אמר כל דבר: \u0003מתניתא\u0004 — \u0003מלכתא\u0004 \u0005[המשנה\u0006 — \u0005מלכה\u0006 היא\u0005]\u0006 והוא לסימן, כי \"מלכיא\" דומה למלכה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין רב נחמן ורב פפא לענין זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 ביחס לדין \u0003שפחות\u0004 שנאמר במשנה, שלשיטת רב פפא — רב מלכיא הוא שאמר זאת, ולא רב מלכיו. ושבים לעיקר הדברים בענין הנחת אפר מקלה על גב פצע.","מסופר, \u0003רב ביבי בר אביי קפיד\u0004 \u0005[היה מקפיד]\u0006 שלא לשים אפר \u0003אפילו אריבדא דכוסילתא\u0004 \u0005[על פצע הקזה]\u0006 שאף זה נראה ככתובת קעקע, ואילו \u0003רב אשי אמר: כל מקום שיש שם מכה\u0004 (פצע) — \u0003מכתו מוכיח עליו\u0004 שלשם ריפוי הוא עושה, ואינו כתובת קעקע.","\u0003נזיר שהיה שותה יין כל היום\u0004 — \u0003אין חייב\u0004 מלקות אלא פעם \u0003אחת. אמרו לו\u0004 עדים בהתראה \u0003\"אל תשתה\", \"אל תשתה\", והוא שותה\u0004 — \u0003חייב על כל אחת ואחת\u0004 מן הפעמים שהתרו בו ושתה. וכן אם \u0003היה\u0004 הנזיר \u0003מטמא למתים כל היום\u0004 — \u0003אינו חייב אלא אחת, אמרו לו \"אל תטמא\", \"אל תטמא\", והוא מטמא\u0004 — \u0003חייב על כל אחת ואחת\u0004 מן הפעמים שהתרו בו ונטמא. וכן, אם \u0003היה מגלח\u0004 שערו \u0003כל היום\u0004 — \u0003אינו חייב אלא אחת, אמרו לו \"אל תגלח\", \"אל תגלח\", והוא מגלח\u0004 — \u0003חייב על כל אחת ואחת\u0004 שהתרו בו וחזר והתגלח.","וכן אדם ש\u0003היה לבוש בכלאים\u0004 (בגד שעטנז) \u0003כל היום\u0004 — \u0003אינו חייב אלא אחת, אמרו לו \"אל תלבש\", \"אל תלבש\", והוא פושט ולובש\u0004 — \u0003חייב על כל אחת ואחת\u0004 מן הפעמים. \u0003ל\u0004"],["כיון שהוזכר שאדם העושה מעשה אחד לוקה על כך כמה מלקות, מביאים דין שיש בו דמיון מסויים: \u0003יש חורש תלם אחד, וחייב עליו\u0004 על אותו מעשה, מלקות \u0003משום שמונה לאוין,\u0004 כיצד? היה \u0003החורש בשור וחמור\u0004 יחד, שעובר משום \"לא תחרוש בשור וחמור יחדיו\" (דברים כב, י), \u0003והן מוקדשין\u0004 והרי הוא עובר משום מועל בקדשים, \u0003ו\u0004היו אלה \u0003כלאים בכרם,\u0004 ובחרישה הוא מסייע לגידולם, כמבואר בגמרא. \u0003ו\u0004היתה זו שנת ה\u0003שביעית\u0004 (השמיטה), ועובר משום עושה מלאכת עבודת אדמה בשביעית, \u0003ו\u0004היה זה \u0003יום טוב,\u0004 שעובר משום עשיית מלאכה ביום טוב, \u0003ו\u0004הוא היה \u0003כהן ו\u0004גם \u0003נזיר,\u0004 ששניהם אסורים להיטמא למת, והיה אותו מקום שחרש \u0003בבית הטומאה\u0004 (במקום טמא בטומאת מת).","\u0003חנניא בן חכינאי אומר: אף\u0004 אם היה \u0003לובש כלאים\u0004 באותה שעה שחורש, לוקה גם משום כלאיים. ויש איפוא עוד איסור שעבר עליו. \u0003אמרו לו: אינו השם.\u0004 כלומר, אין זה מאותו טעם, כי אין זה שייך למעשה החרישה. \u0003אמר להם:\u0004 אם כן, לדבריכם \u0003אף הנזיר לא הוא השם,\u0004 שהרי הנזיר והכהן לא משום חרישה הוא חייב, אלא משום הכניסה למקום טמא.","\u0003אמר רב ביבי אמר ר' יוסי:\u0004 האם מה ששנינו במשנה \u0003\"פושט ולובש\"\u0004 לענין כלאיים, שחייב על כל פעם ופעם אם התרו בו, כוונתו פושט ו\u0003לובש ממש, או אפילו מכניס ומוציא\u0004 את ידו מ\u0003בית יד אונקלי\u0004 (שרוול הבגד) \u0003שלו,\u0004 ואף זה נקרא פשיטה ולבישה? ומספרים כי בענין זה \u0003מחוי\u0004 \u0005[מראה\u0006 היה\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: עיולי ואפוקי\u0004 \u0005[להכניס ולהוציא]\u0006 ממש. \u0003רב אשי אומר:\u0004 אין הכוונה לפושט ולובש ממש, אלא \u0003אפילו לא שהה אלא כדי לפשוט וללבוש,\u0004 והתרו בו — \u0003חייב\u0004 על כל התראה והתראה.","שנינו במשנה: \u0003יש חורש תלם\u0004 אחד וחייב עליו משום שמונה לאוין. ובענין זה \u0003אמר ר' ינאי: בחבורה\u0004 של החכמים \u0003נמנו\u0004 \u0003וגמרו\u0004 (הצביעו והחליטו): \u0003החופה\u0004 (המכסה בעפר) \u0003בכלאים\u0004 על מה שזרע — \u0003לוקה\u0004 משום האיסור לזרוע כלאיים. \u0003אמר להן\u0004 (לו) \u0003ר' יוחנן: לאו\u0004 \u0005[והאם לא]\u0006 \u0003משנתנו היא זו?\u0004 ששנינו בה: \u0003יש חורש תלם אחד וחייב עליו משום שמונה\u0004 \u0003לאוין: החורש בשור ובחמור והן מוקדשין, וכלאים בכרם;\u0004 ונברר: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003חורש, דמחייב\u0004 \u0005[שמתחייב]\u0006 בשעת חרישה \u0003משום כלאים היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 שהרי חרישה עצמה אינה שייכת לזריעת כלאיים. \u0003לאו דמיכסי בהדיה דאזיל\u0004 \u0005[האם לא\u0006 מדובר \u0005ש\u0006הוא \u0005מכסה\u0006 את הזרעים בעפר \u0005בתוך\u0006 כדי \u0005ש\u0006הוא \u0005הולך\u0006 וחורש\u0005]?\u0006 ומכאן משמע שהמחפה בכלאיים לוקה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: צודקים דבריך, אבל \u0003אי לאו דדלאי לך חספא, מי משכחת מרגניתא תותה\u0004 \u0005[אם לא שהרמתי לך\u0006 את \u0005החרס, האם היית מוצא\u0006 את \u0005המרגלית מתחתיו]?\u0006 כלומר, כיון שאמרתי לך את ההלכה, הצלחת למצוא לה מקור במשנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 לאחר זמן: \u0003אי לאו דקילסך גברא רבה\u0004 \u0005[אם לא ששיבח אותך אדם גדול,\u0006 ר' ינאי\u0005]\u0006 על מה שאמרת, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאין זו הוכחה, שהרי אפשר לומר כי \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 זו כדעת \u0005מי היא]\u0006 — דעת \u0003ר' עקיבא היא, דאמר\u0004 \u0005[שהוא אומר]:\u0006 \u0003המקיים כלאים,\u0004 כל שעושה מעשה שחיוני לקיומם — \u0003לוקה.\u0004 ולכן החורש ומחפה בכלאיים, כיון שהוא עוזר לקיומם — לוקה על כך. אבל לא משום שהוא נחשב זורע.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 דברי \u0003ר' עקיבא\u0004? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המנכש\u0004 (העוקר עשבים שוטים) \u0003והמחפה\u0004 בעפר את הזרעים \u0003בכלאים\u0004 — \u0003לוקה,\u0004 שעשה מעשה לגדל את הכלאיים, כזורע. \u0003ר' עקיבא אומר: אף המקיים\u0004 את הכלאיים.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"שדך לא תזרע כלאים\"\u0004 (ויקרא יט, יט) — \u0003אין לי אלא זורע, מקיים מנין? תלמוד לומר \"בהמתך לא תרביע כלאים שדך לא תזרע כלאים\"\u0004 (ויקרא יח— יט) שמצרפים וקוראים כאילו היה כתוב \"כלאים שדך לא\", שבכל מקרה לא יהיו כלאים בשדך.","ובקשר לרשימת הלוקים שבמשנתנו, שאמרנו שמדובר במי שחורש ומחפה את הזרעים, ויש בו משום זורע, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא לרב נחמן: ולילקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 \u0003משום זורע ביום טוב! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר,\u0004 והיה יכול לשנות גם לאו נוסף זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: ה\u0003תנא קתני\u0004 \u0005[שנה]\u0006 \u0003שמונה\u0004 ומנה אותם, \u0003ואת אמרת:\u0004 \u0005[ואתה אומר]:\u0006 \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר?!\u0004 אלא ודאי דייק במספר! \u0003אמר רבא:\u0004 כך צריך להסביר, \u0003יש חילוק מלאכות בשבת,\u0004 שאם עושה אדם מלאכות שונות בשבת בבת אחת — חייב על כל אחת ואחת, \u0003ואין חילוק מלאכות ביום טוב,\u0004 אלא כל איסור מלאכה ביום טוב לאו אחד הוא, ולוקה רק פעם אחת אפילו עושה כמה מלאכות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003עדא תהא\u0004 \u0005[זאת תהיה]\u0006 כלומר, כך הוא, זה הוא ההסבר הנכון.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי: ו\u0004כי \u0003אין חילוק מלאכות ביום טוב? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המבשל גיד בחלב ביום טוב, ואכלו\u0004 — \u0003לוקה חמש.\u0004 כיצד? \u0003לוקה משום אוכל גיד, ולוקה משום מבשל ביום טוב שלא לצורך, ולוקה משום מבשל גיד\u0004 (שהוא בשר) \u0003בחלב, ולוקה משום אוכל בשר בחלב, ולוקה ל\u0004"],["\u0003משום הבערה\u0004 ביום טוב. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדבריך, שאין חילוק מלאכות ביום טוב — \u0003משום הבערה לא מחייב\u0004 \u0005[מתחייב],\u0006 \u0003דהא איחייב ליה\u0004 \u0005[שהרי התחייב לו]\u0006 באיסור מלאכה אחר ביום טוב, \u0003משום בשולו!\u0004 ענה לו: \u0003אפיק\u0004 \u0005[הוצא]\u0006 ממנין חמשת חיובי המלקות איסור \u0003הבערה,\u0004 שבאמת אינו לוקה עליו, \u0003ועייל\u0004 \u0005[והכנס]\u0006 איסור אחר — \u0003גיד הנשה של נבילה,\u0004 שהיה זה גיד הנשה של נבילה, ועבר על איסור נוסף של אכילת נבילה.","ומקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 בברייתא, כסיכום לחמשת חיובי המלקות שבמשנה זו: \u0003לוקה שתים על אכילתו ושלש על בשולו, ואי איתא\u0004 \u0005[ואם יש]\u0006 מקום לדבריך אלו, שיש להוציא הבערה ולהכניס אכילת גיד הנשה של נבילה, אם כן \u0003שלש על אכילתו הוא חייב,\u0004 שהרי הוא חייב משום אכילת גיד, אכילת בשר בחלב, ואכילת נבילה! \u0003אלא\u0004 כך צריך לומר: \u0003אפיק\u0004 \u0005[הוצא]\u0006 מן המנין איסור \u0003הבערה, ועייל\u0004 \u0005[והכנס]\u0006 איסור אחר, והוא שעשה זאת ב\u0003עצי אשירה\u0004 (עץ שהוקדש לעבודה זרה), \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו,\u0006 מקור איסורו, \u0005מכאן]\u0006 מפסוק זה, שנאמר \u0003\"ולא ידבק בידך\u0004 מאומה מן החרם\" (דברים יג, יח), שאסור ליהנות מעבודה זרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 אם עצי אשירה הם, \u0003ולילקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 \u0003משום \"לא תביא תועבה אל ביתך\"\u0004 (דברים ז, כו), והיה צריך להוסיף לאו נוסף על החמישה! \u0003אלא\u0004 כך צריך לומר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שבישלו בעצי הקדש, ואזהרתיה מהכא\u0004 \u0005[ואזהרתו,\u0006 מקור איסורו \u0005מכאן]\u0006 שנאמר \u0003\"ואשריהם תשרפון באש... לא תעשון כן לה' אלהיכם\"\u0004 (דברים יב, ג—ד), שאסור להשמיד חפץ שבקדושה, והעושה כן עובר בלאו.","על מנין הלאווים שבמשנתנו, במי שחורש, הקשו חכמים, \u0003סימן\u0004 לשמות החכמים שהתקשו בדבר. \u0003שנבא\"י שנ\"ז\u0004 (הו \u0003ש\u0004עיא, ח \u0003נ\u0004 ניא, א \u0003ב\u0004הו, \u0003א\u0004 ב\u0003י\u0004 י, א \u0003ש\u0004י, רבי \u0003נ\u0004 א, \u0003ז\u0004 עירא).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הושעיא: וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 בתוך האיסורים איסור \u0003הזורע בנחל איתן,\u0004 שהיה חורש במקום שערפו בו את העגלה הערופה, \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו,\u0006 מקור איסורו \u0005מכאן]\u0006 שנאמר \"והורידו זקני העיר ההיא את העגלה אל נחל איתן \u0003אשר לא יעבד בו ולא יזרע\"\u0004 (דברים כא, ד), שמפרשים אותו כאיסור להבא, שמאז העריפה בנחל אסור עוד לעבוד בו!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חנניא: וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 איסור \u0003המוחק את השם בהליכתו\u0004 תוך כדי שהוא הולך וחורש, \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו מכאן]\u0006 \u0003\"ואבדתם את שמם וגו' (ו)לא תעשון כן לה' אלהיכם\"\u0004 (דברים יב, ג— ד)!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבהו: וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 שבתוך כדי כך היה \u0003קוצץ את בהרתו\u0004 (את נגע הצרעת שהיתה עליו), \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו מכאן]\u0006 \u0003\"השמר בנגע הצרעת\"\u0004 (דברים כד, ח), ו\"השמר\" הוא לשון לאו, שאסור להסיר את הנגע!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 שהיה באותו זמן \u0003מזיח החושן מעל האפוד, ו\u0004כן \u0003המסיר בדי ארון\u0004 העדות, \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו מכאן]\u0006 שנאמר \"בטבעות הארון יהיו הבדים \u0003(ו)לא יסרו\u0004 ממנו\" (שמות כה, טו), וכן לגבי החושן נאמר \u0003\"ולא יזח החשן\u0004 מעל האפוד\" (שמות כח, כח)!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 את \u0003החורש בעצי אשירה,\u0004 שהיתה המחרישה עצמה עשויה מעצים אלה, \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו מכאן]\u0006 \u0003\"ולא ידבק בידך מאומה\u0004 מן החרם\" (דברים יג, יח)!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 \u0003הקוצץ אילנות טובות,\u0004 שקוצצם עם חרישתו, \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו מכאן]\u0006 \u0003\"כי ממנו תאכל ואתו לא תכרת\"\u0004 (דברים כ, יט)!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זעירא לר' מני: וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 \u0003כגון דאמר\u0004 \u0005[שאומר]\u0006 \u0003\"שבועה שלא אחרוש ביום טוב\"\u0004 ועבר על השבועה! ענה לו ר' מני: \u0003התם\u0004 \u0005[שם]\u0006 \u0003לא חלה שבועה\u0004 זו עליו, כי \u0003מושבע ועומד מהר סיני הוא\u0004 שלא לחרוש, ואין שבועה חלה על שבועה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 בכל זאת אפשר שתחול שבועה זו, \u0003כגון דאמר\u0004 \u0005[שאומר]\u0006 \u0003\"שבועה שלא אחרוש בין בחול\u0004 \u0003בין ביום טוב\", דמגו\u0004 \u0005[שמתוך]\u0006 ש\u0003חלה עליה\u0004 \u0005[עליו]\u0006 \u0003שבועה בחול\u0004 — \u0003חלה עליה נמי\u0004 \u0005[עליו גם כן]\u0006 \u0003ביום טוב!\u0004 ענה לו ר' מני: \u0003מידי דאיתיה\u0004 \u0005[דבר שישנו]\u0006 \u0003בשאילה לא קתני\u0004 \u0005[שנה\u0006 במשנה\u0005],\u0006 שלא מנה איסורים שאפשר להתירם אם יישאל לחכם, וכיון שיכול להישאל לחכם על השבועה ויתיר לו, אין בזה לאו ודאי.","אמר לו ר' זעירא: \u0003ו\u0004כי \u0003לא\u0004 שנה שם דבר שאפשר להישאל עליו? \u0003והרי\u0004 נזכר במשנה \u0003הקדש,\u0004 שחרש בבהמות הקדש, ואדם יכול להישאל על נדר ההקדש ולבטלו! ענה לו: מדובר במשנה \u0003בבכור,\u0004 שקדושתו מרחם, ואי אפשר להישאל על איסורו. וחזר והקשה: \u0003והרי\u0004 הובא במשנה גם איסור טומאה של \u0003נזיר\u0004 שיכול להישאל על נדר נזירותו! השיב לו ר' מני: מדובר שם \u0003בנזיר שמשון\u0004 שאין התרה לנדרו.","ודחה ר' זעירא: וכי \u0003נזיר שמשון בר איטמויי\u0004 \u0005[בן טומאה]\u0006 \u0003למתים הוא?\u0004 והרי נזירות כנזירות שמשון אינה כוללת איסור טומאה למתים, כמו שמצאנו בשמשון עצמו שנטמא למתים! \u0003אלא\u0004 צריך לתרץ כי הסיבה שלא נאמר במשנה גם שאדם זה עבר על שבועתו, היא משום ש\u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003איסור כולל לית ליה\u0004 \u0005[אין לו],\u0006 שלדעתו אין איסור חל על איסור גם במקרה כזה. ולכן, הואיל וכבר נאסר מן התורה לחרוש ביום טוב, אינו מוסיף דבר במה שנשבע שלא לחרוש גם ביום חול.","אגב דברים אלה \u0003אמר ר' הושעיא: המרביע שור פסולי המוקדשים\u0004 (שור שהוקדש ונפל בו מום), הרי אף שיצא מקדושתו לכמה דברים — יש בו עדיין מקצת קדושה, כגון שאסור לעבוד בו, ואם הרביע עליו (כגון שהיה נקבה) — \u0003לוקה שנים,\u0004 אחת משום עבודה בפסולי המוקדשים, ואחת משום כלאיים. לפי שהכתוב עשה את פסולי המוקדשים כשתי בריות, בהמת הקדש ובהמת חולין, ואם מרביע עליו שור — הריהו כמרביע עליו בהמה ממין אחר, ועובר על איסור כלאיים. וכן \u0003אמר ר' יצחק: המנהיג\u0004 כגון שחורש \u0003בשור פסולי המוקדשים\u0004 — \u0003לוקה,\u0004 וטעמו \u0003שהרי גוף אחד הוא, ועשאו הכתוב כשני גופים,\u0004 והמנהיג שתי בהמות שונות יחד — לוקה.","\u0003כמה\u0004 מלקות \u0003מלקין אותו\u0004 את המחוייב מלקות — \u0003ארבעים חסר אחת, שנאמר\u0004 \"והכהו לפניו כדי רשעתו \u0003במספר, ארבעים\u0004 יכנו לא יוסיף...\" (דברים כה, ג— ד), ואנו דורשים את הכתובים, ומצרפים את סוף הפסוק הראשון לתחילת הפסוק השני, וקוראים כאילו היה כתוב יחד \"במספר ארבעים\", כלומר \u0003מנין שהוא סמוך לארבעים. ר' יהודה אומר: ארבעים שלימות הוא לוקה, והיכן הוא לוקה את\u0004 המכה \u0003היתירה\u0004 שאיננה בכפולות של שלוש (שהרי כמבואר להלן מחלקים את המלקות לשלוש) — \u0003בין כתפיו.\u0004","\u0003אין אומדין אותו,\u0004 כדי לפסוק כמה מכות הוא יכול לקבל, \u0003אלא במכות ראויות להשתלש\u0004 להתחלק לשלוש, כגון שאם יכול ללקות עשרים — יפסקו לו שמונה עשרה. ועוד הלכה בענין האומדן: \u0003אמדוהו\u0004 הרופאים שיכול \u0003לקבל ארבעים\u0004 מלקות, \u0003ולוקה\u0004 בפועל \u0003מקצת\u0004 מהן,"],["\u0003ואמדו\u0004 שנית \u0003שאין יכול לקבל ארבעים\u0004 מלקות — הרי הוא \u0003פטור\u0004 ממלקות נוספות. אם \u0003אמדוהו\u0004 מתחילה שיכול \u0003לקבל\u0004 רק \u0003שמונה עשרה\u0004 מלקות, \u0003ומשלקה\u0004 שמונה עשרה אלה \u0003אמדו שיכול הוא לקבל ארבעים\u0004 — \u0003פטור.\u0004","ותחילה דנים במספר המלקות. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמרו שיש להלקותו ארבעים חסר אחת? כי \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005נאמר]\u0006 \u0003\"ארבעים במספר\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהכוונה היא \u0003ארבעים במניינא\u0004 \u0005[במנין,\u0006 במספר מדויק\u0005],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"במספר ארבעים\",\u0004 כוונתו: \u0003מנין\u0004 (מספר) זה \u0003שהוא סוכם\u0004 (משלים) \u0003את הארבעים. אמר רבא\u0004 כהערה לכך: \u0003כמה טפשאי\u0004 \u0005[טפשים]\u0006 הם \u0003שאר אינשי\u0004 \u0005[האנשים],\u0006 \u0003דקיימי מקמי\u0004 \u0005[שעומדים מלפני]\u0006 \u0003ספר תורה\u0004 שעובר לפניהם, \u0003ולא קיימי מקמי גברא רבה\u0004 \u0005[ואינם עומדים מלפני אדם גדול],\u0006 תלמיד חכם שעובר לפניהם, ש\u0003אילו בספר תורה כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ארבעים\",\u0004 ופשוטו הוא ארבעים ממש, \u0003ואתו רבנן בצרו חדא\u0004 \u0005[ובאו חכמים והפחיתו\u0006 מכה \u0005אחת]\u0006 והעמידו את מספר המלקות על שלושים ותשע. הרי שגדול כוחם של חכמים יותר משל הכתוב בספר התורה.","שנינו במשנה, \u0003ר' יהודה אומר: ארבעים שלימות\u0004 הוא לוקה, והיכן הוא לוקה את היתירה — בין כתפיו. \u0003אמר ר' יצחק: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"מה המכות האלה בין ידיך ואמר אשר הכתי בית מאהבי\"\u0004 (זכריה יג, ו), שהוא מפרשו שפעמים יש לאדם סימני מכות בין כתפיו — מקום חיבור ידיו לגופו, מפני שהולקה בבית דין. משמע שמכים מכה אחת גם בין הכתפיים. ומצד אחר, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מפרשים הם כתוב זה? \u0003ההוא\u0004 \u0005[אותו]\u0006 פסוק \u0003בתינוקות של בית רבן הוא דכתיב\u0004 \u0005[שנאמר],\u0006 בילדים הלוקים על ידי רבם על שהתרשלו בלימודם, ואין אלה כמלקות בית דין.","שנינו במשנה ש\u0003אין אומדין אלא במכות הראויות\u0004 להשתלש. ועוד שנינו שאם אמדוהו לקבל ארבעים ולקה מקצת, ושוב אמדוהו ואמרו שאינו יכול לקבל ארבעים — פטור. וכיוצא בזה אם אמדוהו שיכול לקבל פחות ולקה, ושוב אמדוהו ויכול לקבל ארבעים — פטור. ומדייקים: אם \u0003לקה\u0004 בפועל — \u0003אין\u0004 \u0005[כן]\u0006 פטור, אם עדיין \u0003לא לקה\u0004 — \u0003לא\u0004 נפטר ממלקות ארבעים.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך, ממה ששנינו בברייתא: \u0003אמדוהו לקבל ארבעים, וחזרו ואמדו שאין יכול לקבל ארבעים\u0004 — \u0003פטור. אמדוהו לקבל שמונה עשרה, וחזרו ואמדוהו שיכול לקבל ארבעים\u0004 — \u0003פטור.\u0004 משמע שגם אם לא לקה ממש חלק מהמכות, אלא אפילו אמדו אותו למלקות — הרי זה כאילו לקה!","\u0003אמר רב ששת: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003אמדוהו\u0004 לקבל מלקות ב\u0003יומי\u0004 \u0005[\u0006באותו \u0005יום]\u0006 ולא השתנה בו דבר בינתיים, אלא הוכח שאומד ראשון לא היה נכון. ולכן דווקא אם לקה כבר — נפטר בכך, אבל אם לא לקה — הולכים רק אחר אומד שני. \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003אמדוהו למחר וליומא אוחרא\u0004 \u0005[וליום אחר],\u0006 שיכול להיות שהשתנה מצב בריאותו בינתיים, ובמקרה כזה, שנתברר שאינו יכול עכשיו לקבל — פטור.","\u0003עבר עבירה שיש בה שני לאוין,\u0004 אם \u0003אמדוהו אומד אחד\u0004 כמה מלקות הוא יכול לקבל בבת אחת על שניהם — \u0003לוקה\u0004 כמה שאמדוהו, \u0003ופטור\u0004 בכך משתי המלקויות, \u0003ואם לאו,\u0004 שאמדו אותו רק לדין מלקות אחד — \u0003לוקה ומתרפא, ו\u0004אחר כך \u0003חוזר ולוקה\u0004 משום הלאו השני.","במשנה נדון המקרה שאמדוהו לשתי מלקויות בבת אחת. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין אומדין אומד אחד לשני לאוין!\u0004","\u0003אמר רב ששת: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין אומדים אומד אחד לשני לאוים — מדובר ש\u0003אמדוהו\u0004 שיכול לקבל \u0003לארבעים וחדא\u0004 \u0005[ואחת]\u0006 מכות. שיש כאן שיעור מלקות שלם אחד, ועוד שתי מלקות נוספות, וכיון ששתי המלקות הנוספות אינן ראויות להתחלק לשלוש, הרי אינו לוקה אלא שלושים ותשע, כדברי המשנה לעיל (עמוד א). ונמצא שלא לקה אלא פעם אחת, ולכן יש להלקותו פעם אחת שלושים ותשעה. וממתינים עד שיתרפא, ויחזרו ויאמדו אותו כמה מלקות הוא יכול לקבל עבור הלאו השני. \u0003הא\u0004 \u0005[זה]\u0006 במשנה — מדובר ש\u0003אמדוהו לארבעים ותרתי\u0004 \u0005[ושתים]\u0006 מלקות. שאפשר לומר שלוקה שלושים ותשע משום לאו אחד, ועוד שלוש משום הלאו השני, והרי זה כשני אומדנים לחוד.","\u0003כיצד מלקין אותו\u0004 בפועל? \u0003כופה\u0004 (קושר) \u0003שתי ידיו על העמוד הילך והילך\u0004 (לכאן ולכאן), \u0003וחזן הכנסת\u0004 (שמש הקהל) \u0003אוחז בבגדיו\u0004 להסירם ממנו, \u0003אם נקרעו\u0004 בתוך כך — \u0003נקרעו, ואם נפרמו\u0004 — \u0003נפרמו, עד שהוא מגלה את לבו. והאבן\u0004 שהחזן עומד עליה \u0003נתונה מאחריו. חזן הכנסת עומד עליו ורצועה בידו,\u0004 והרצועה היא \u0003של\u0004 עור \u0003עגל,\u0004 והיא \u0003כפולה, אחד לשנים ושנים לארבעה, ושתי רצועות של חמור עולות ויורדות\u0004 כלומר, תלויות \u0003בה. ידה,\u0004 הידית שלה, שבה הוא מחזיק — אורכה \u0003טפח, ורחבה\u0004 של הרצועה \u0003טפח, ו\u0004צריך שיהא \u0003ראשה\u0004 של הרצועה ארוך כדי שתהיה \u0003מגעת על פי\u0004 (שפת) \u0003כריסו\u0004 כשהוא מכהו על גבו,","\u0003ומכה אותו שליש\u0004 מן המלקות \u0003מלפניו\u0004 על חזהו, \u0003ושתי ידות\u0004 שני שלישים \u0003מלאחריו\u0004 על גבו. \u0003ואינו מכה אותו\u0004 כשהמוכה \u0003לא עומד ולא יושב, אלא\u0004 כשהוא \u0003מוטה, שנאמר \"והפילו השפט\u0004 והכהו\" (דברים כה, ב) שיהא המוכה במצב שהוא כעין נפילה,","\u0003והמכה מכה בידו אחת בכל כחו, והקורא קורא\u0004 עליו את הפסוקים: \u0003\"אם לא תשמר לעשות וגו'\u0004 (דברים כח, נח) \u0003והפלא ה' את מכתך ואת מכות\u0004 זרעך מכות גדלות ונאמנות וחליים רעים ונאמנים\" (דברים, נט), \u0003וחוזר לתחלת המקרא: \"ושמרתם את דברי הברית הזאת...\"\u0004(דברים כט, ח), \u0003וחותם\u0004 בפסוק: \u0003\"והוא רחום יכפר עון\"\u0004 (תהלים עח, לח), \u0003וחוזר\u0004 שוב \u0003לתחלת המקרא\u0004 (\"אם לא תשמור\" וכו').","\u0003ואם מת תחת ידו\u0004 של המכה — \u0003פטור\u0004 המכה, משום שעשה לפי הוראת בית דין. \u0003הוסיף לו עוד\u0004 מכת \u0003רצועה אחת ומת\u0004 — \u0003הרי זה גולה על ידו,\u0004 שהוא כרוצח בשגגה. \u0003נתקלקל\u0004 כלומר, נפתחו נקביו של המוכה מחמת פחד או יסורים, \u0003בין בריעי\u0004 (בצואה) \u0003בין במים\u0004 (בשתן) — \u0003פטור\u0004 מן המלקות, \u0003ר' יהודה אומר:\u0004 אין בושתם של איש ואשה דומה, \u0003האיש\u0004 — עד שיתקלקל \u0003בריעי\u0004 דווקא, \u0003והאשה\u0004 — \u0003במים.\u0004"],["שנינו במשנה שקורעים את בגדיו של הלוקה בבית הדין. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003משום \"נקלה\",\u0004 שהרי נאמר על הלוקה \"ונקלה אחיך לעיניך\" (דברים כה, ג), ואף קריעת בגדיו היא מענין קלונו.","ועל מה ששנינו במשנה שמכים אותו ברצועה של עגל, מביאים מה ש\u0003אמר רב ששת משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה: מנין לרצועה\u0004 שמלקים בה את הלוקים בבית דין \u0003שהיא\u0004 מעור \u0003של עגל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ארבעים יכנו\"\u0004 (שם), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"לא תחסם שור בדישו\"\u0004 (דברים כה, ד), לרמז שמלקים אותו בדבר הנעשה מעור שור. כיון שהוזכרה דרשת סמוכים של ר' אלעזר בן עזריה שהביא רב ששת, מביאים דרשות דומות נוספות שאמרן רב ששת בשם ר' אלעזר בן עזריה.","\u0003ואמר רב ששת משום ר' אלעזר בן עזריה: מנין ליבמה שנפלה\u0004 לייבום \u0003לפני\u0004 יבם \u0003מוכה שחין, שאין חוסמין אותה\u0004 כלומר, אין מכריחים אותה להתייבם — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא תחסם שור בדישו\"\u0004 (דברים כה, ד), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"כי ישבו אחים יחדו\" וגו'\u0004 (דברים כה, ה) המדבר בדיני יבום.","\u0003ו\u0004עוד \u0003אמר רב ששת משום ר' אלעזר בן עזריה: כל המבזה את המועדים\u0004 הריהו \u0003כאילו עובד עבודה זרה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אלהי מסכה לא תעשה לך\"\u0004 (שמות לד, יז), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"את חג המצות תשמר\"\u0004 (שמות לד, יח).","\u0003ו\u0004עוד \u0003אמר רב ששת משום ר' אלעזר בן עזריה: כל המספר לשון הרע, וכל המקבל\u0004 (מאמין) ב\u0003לשון הרע, וכל המעיד עדות שקר\u0004 — \u0003ראוי להשליכו לכלבים, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לכלב תשלכון אתו\"\u0004 (שמות כב, ל), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 מיד \u0003\"לא תשא שמע שוא\u0004 אל תשת ידך עם רשע להיות עד חמס\" (שמות כג, א), ומסבירים שכתוב זה כולל בתוכו בנוסף לעדות שקר (\"עד חמס\"), ולמקבל לשון הרע (\"לא תשא\"), גם איסור סיפור לשון הרע, שכן \u0003קרי ביה נמי\u0004 \u0005[קרא בו גם כן]\u0006 \u0003\"לא תשיא\"\u0004 כלומר, לא תגרום לאחר להאמין בשמועת שוא.","שנינו במשנה: \u0003ושתי רצועות\u0004 עולות ויורדות בה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003ו\u0004רצועות \u0003של חמור\u0004 דוקא. \u0003כדדריש ההוא גלילאה עליה דרב חסדא\u0004 \u0005[כמו שדרש גלילי אחד לפני רב חסדא]:\u0006 נאמר \u0003\"ידע שור קנהו וחמור אבוס בעליו, ישראל לא ידע\u0004 עמי לא התבונן\" (ישעיה א, ג), \u0003אמר הקדוש ברוך הוא: יבא מי שמכיר אבוס בעליו,\u0004 שור וחמור, \u0003ויפרע\u0004 במלקות (ברצועה העשויה מעורו) \u0003ממי שאינו מכיר אבוס בעליו\u0004 וחוטא.","ועוד שנינו במשנה ש\u0003ידה\u0004 של רצועה \u0003טפח\u0004 ואורכה כדי שתגיע לפי (לקצה) כריסו. \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כל חד וחד לפום גביה עבדינן ליה\u0004 \u0005[אחד ואחד לפי גבו עושים לו]\u0006 רצועה, שהרי אין האנשים שווים, וצריכים שתהיה רצועה מתאימה לגודל הגב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אם כן נפיש להו\u0004 \u0005[ירבו להם]\u0006 \u0003רצועות טובא\u0004 \u0005[הרבה]\u0006 בבית דין! \u0003אלא אמר רבא: אבקתא אית ליה\u0004 \u0005[לולאות יש בו],\u0006 \u0003כי בעי מיקטר ביה\u0004 \u0005[כאשר צריך קושר בהן],\u0006 \u0003כי בעי מרפה בה\u0004 \u0005[כאשר צריך מרפה אותן],\u0006 כך שהרצועה יכולה להתארך ולהתקצר לפי גודלו של האיש הלוקה.","שנינו ש\u0003מלקין אותו\u0004 שליש מהמלקות מלפניו ושני שלישים מהמלקות מאחוריו. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב כהנא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והפילו השפט והכהו לפניו כדי רשעתו במספר\"\u0004 (דברים כה, ב) כלומר: מכה אותו כדי \u0003רשעה אחת מלפניו, שתי רשעיות מאחריו.\u0004","ועוד שנינו ש\u0003אין מלקין אותו\u0004 כשהוא יושב אלא כשהוא מוטה, שנאמר \"והפילו השופט\" (דברים כה, ב). ותחילה מביאים בענין זה מה ש\u0003אמר רב חסדא אמר ר' יוחנן: מנין לרצועה שהיא מוכפלת\u0004 — \u0003שנאמר \"והפילו\",\u0004 שאנו מפרשים כמו בארמית, משורש עיף=כפול. ושואלים: \u0003והא מיבעי ליה לגופיה\u0004 \u0005[והרי צריך אותה לגופו]\u0006 כמו שדרשנו במשנתנו, שיהיה מוטה! ומשיבים: \u0003אם כן לכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"יטיהו\", מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"הפילו\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שתים],\u0006 גם לענין המוכה שיהא מוטה, וגם רמז לרצועה.","שנינו במשנה ש\u0003המכה מכה בידו\u0004 אחת ובכל כוחו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מעמידין חזנין\u0004 (שמשים) למלקות \u0003אלא\u0004 מי שהם \u0003חסירי כח ויתירי מדע\u0004 מרובים בידיעה, בעלי תורה. \u0003ר' יהודה אומר: אפילו חסירי מדע ויתירי כח.\u0004","\u0003אמר רבא: כוותיה\u0004 \u0005[כשיטתו של]\u0006 \u0003ר' יהודה מסתברא\u0004 \u0005[מסתבר],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \"ארבעים יכנו \u0003לא יוסיף... פן יוסיף\u0004 להכותו\" (דברים כ״ה:ג׳, בד), \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמדובר פה גם באנשים שהם \u0003חסירי מדע —\u0004 \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003צריך לאזהורי\u0004 \u0005[להזהיר]\u0006 שלא יכה יותר, שהרי האיש אינו יודע כלל בהלכה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר דווקא ב\u0003יתירי מדע\u0004 — \u0003מי צריך לאזהורי\u0004 \u0005[האם צריך להזהיר]\u0006 אותם כל כך? ומכאן משמע שאפשר לקחת גם אדם שאיננו יודע. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: אין מכאן ראיה, שכן \u0003אין מזרזין אלא למזרז,\u0004 ולכן נאמרה אזהרה זו לאנשים הבקיאים ומדקדקים במצוות.","ובפרטי ענין זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשהוא\u0004 המלקה \u0003מגביה\u0004 את הרצועה על מנת להלקות — \u0003מגביה\u0004 אותה \u0003בשתי ידיו, וכשהוא מכה\u0004 — \u0003מכה בידו אחת\u0004 בלבד, \u0003כי היכי דליתא מדידיה\u0004 \u0005[כדי שתגיע\u0006 המכה \u0005משלו,\u0006 ממנו, במכה מכוונת\u0005].\u0006","שנינו במשנה \u0003והקורא קורא\u0004 \"אם לא תשמור\" וכו' ועוד פסוקים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הגדול שבדיינין קורא\u0004 את הפסוקים הללו, \u0003השני מונה\u0004 את מספר המלקות, \u0003והשלישי אומר\u0004 לחזן: \u0003\"הכהו\"! בזמן שמכה מרובה\u0004 — \u0003מאריך\u0004 הקורא בקריאה, \u0003בזמן שמכה מועטת\u0004 — \u0003מקצר,\u0004 גומר אותה מהר יותר, כדי שתיגמר הקריאה יחד עם גמר המלקות. ושואלים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 ש\u0003חוזר לתחלת המקרא,\u0004 משמע שאפשר לקרוא כמה פעמים! ומשיבים: \u0003מצוה לצמצם\u0004 (לדייק) שיהיו המלקות נגמרות יחד עם הקריאה, \u0003ו\u0004רק \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא צמצם\u0004 וקרא מהר יותר — \u0003חוזר לתחלת המקרא.\u0004 ומביאים עוד דבר שדרשו חכמים במנין המלקות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"פן יוסיף להכותו על אלה \u0003מכה רבה\"\u0004 (דברים כה, ג), \u0003אין לי\u0004 שאסור להוסיף \u0003אלא מכה רבה, מכה מועטת מנין? תלמוד לומר \"לא יוסיף\"\u0004 כלל. ושואלים: \u0003אם כן, מה תלמוד לומר \"מכה רבה\"\u0004 — כוונתו: \u0003לימד על הראשונות שהן מכה רבה,\u0004 ואותן ראוי להכותו בכל כוחו.","שנינו במשנה: \u0003נתקלקל\u0004 בין בריעי בין במים — פטור, ר' יהודה אומר: האיש בריעי והאשה במים. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אחד האיש ואחד האשה,\u0004 אם נתקלקלו — \u0003בריעי\u0004 דווקא הם נפטרים \u0003ולא במים, דברי ר' מאיר. ר' יהודה אומר: האיש בריעי, והאשה\u0004 אפילו \u0003במים. וחכמים אומרים: אחד האיש ואחד האשה\u0004 — \u0003בין בריעי בין במים.\u0004","ומתקשים במה שהובא בשם ר' יהודה: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא אחרת\u0005],\u0006 \u0003ר' יהודה אומר: אחד האיש ואחד האשה\u0004 — \u0003בריעי,\u0004 ומשמע שגם אשה ברעי דווקא ולא במים! \u0003אמר רב נחמן בר יצחק:\u0004 אין זו סתירה, אלא כוונת ברייתא זו היא שלשיטת ר' יהודה \u0003שניהם שוין בריעי\u0004 שבזה הם נפטרים, אבל יתירה אשה שנפטרת גם במים.","ובענין זה מביאים מה ש\u0003אמר שמואל: כפתוהו\u0004 להכותו, \u0003ורץ\u0004 (ברח) \u0003מבית דין\u0004 — \u0003פטור. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003קלה\u0004 כלומר, אם נקלה, נתקלקל ברעי, \u0003בין ב\u0004מכה ה\u0003ראשונה בין בשניה\u0004 — \u0003פוטרין אותו.\u0004 אבל אם \u0003נפסקה רצועה\u0004 תוך כדי ההכאה \u0003ב\u0004מכה ה\u0003שניה\u0004 — \u0003פוטרין אותו,\u0004 אבל \u0003בראשונה\u0004 — \u0003אין פוטרין אותו.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אין פוטרים אותו בראשונה? \u0003להוי\u0004 \u0005[שיהיה\u0006 זה\u0005]\u0006 \u0003כרץ\u0004 וברח מבית דין, וייפטר! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003רץ\u0004 וברח מבית הדין, ולכן אין מחזירים אותו עוד, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא רץ,\u0004 ולכן אינו נפטר בלי מלקות כלל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אמדוהו לכשילקה קלה,\u0004 שאם ילקוהו יהיה לו הקלון של ריעי — \u0003פוטרין אותו,\u0004 שאין פוסקים לו לכתחילה דבר שיהיה לו בו קלון יתר. אם אמדוהו ש\u0003לכשיצא מבית דין\u0004 לאחר שילקה \u0003קלה\u0004 — \u0003מלקין אותו. ולא עוד אלא, אפילו קלה בתחלה\u0004 לפני שהתחילו להכותו — \u0003מלקין אותו\u0004 שנאמר \u0003\"והכהו... ונקלה\",\u0004 שבתוך כדי מלקות נקלה, \u0003ולא שלקה כבר בבית דין.\u0004","\u0003כל חייבי כריתות שלקו\u0004 — \u0003נפטרו ידי כריתתם, שנאמר \"ונקלה אחיך לעיניך\"\u0004 (דברים כה, ג) כוונתו: \u0003כשלקה הרי הוא כאחיך,\u0004 שנמחל עוונו, והריהו כאחיך — אדם כשר כמותך. אלו \u0003דברי ר' חנניה בן גמליאל.\u0004","\u0003ואמר ר' חנניה בן גמליאל: מה אם העובר עבירה אחת נוטל נפשו עליה,\u0004 שהרי בעבירה אחת יכול שתיעקר נפשו מן העולם, \u0003העושה מצוה אחת\u0004 — \u0003על אחת כמה וכמה שתנתן לו נפשו,\u0004 שגדול שכר המצוות יותר מעונש העבירות. \u0003ר' שמעון אומר: ממקומו הוא למד\u0004 כלומר, מאותו כתוב עצמו למדים דברים אלה, \u0003שנאמר\u0004 בסוף דיני עריות שיש בהן כרת \u0003\"ונכרתו הנפשות העשת\"\u0004 (ויקרא יח, כט), ואומר"],["בתחילת פרשה זו \u0003\"אשר יעשה אתם האדם וחי בהם\"\u0004 (ויקרא יח, ה). \u0003הא\u0004 \u0005[הרי]\u0006 מכאן משמע שעושה המצוות זוכה לחיים. והרי נמנו לאחר מכן רק מצוות לא תעשה, ומכאן למדנו שכל \u0003היושב ולא עבר עבירה\u0004 — \u0003נותנין לו שכר כעושה מצוה.\u0004","\u0003ר' שמעון בר רבי אומר: הרי הוא אומר \"רק חזק לבלתי אכל (את) הדם כי הדם הוא הנפש\"\u0004 (דברים יב, כג), ויש ללמוד קל וחומר לעבירות אחרות: \u0003ומה אם הדם, שנפשו של אדם\u0004 בכלל \u0003קצה\u0004 (מואסת, נגעלת) \u0003ממנו\u0004 — \u0003הפורש ממנו\u0004 מלאוכלו \u0003מקבל\u0004 על כך \u0003שכר,\u0004 כאמור לאחר מכן \"לא תאכלנו למען ייטב לך ולבניך אחריך\" (דברים יב, כה), \u0003גזל ועריות, ש\u0004בדרך הטבע \u0003נפשו של אדם מתאוה להן ומחמדתן\u0004 — \u0003הפורש מהן\u0004 ושובר את יצרו \u0003על אחת כמה וכמה שיזכה\u0004 על כך שכר \u0003לו ולדורותיו ולדורות דורותיו עד סוף כל הדורות.\u0004","\u0003ר' חנניא בן עקשיא אומר: רצה הקדוש ברוך הוא לזכות את ישראל, לפיכך הרבה להם תורה ומצות\u0004 שבכל מצוה יש להם זכות נוספת, \u0003שנאמר \"ה' חפץ למען צדקו יגדיל תורה ויאדיר\"\u0004 (ישעיה מב, כא). שמפני צדקתו של ה' רצה לזכות את ישראל, ולכן יגדיל תורה — בתוספת מצוות.","\u0003אמר ר' יוחנן: חלוקין עליו חבריו על ר' חנניה בן גמליאל,\u0004 ואינם סבורים שהלוקה נפטר מן הכרת. ומנין שכן הוא? \u0003אמר רב אדא בר אהבה: אמרי בי\u0004 \u0005[אמרו\u0006 חכמים \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב, תנינן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 במסכת מגילה: \u0003אין בין שבת ליום הכפורים אלא שזה\u0004 (שבת) \u0003זדונו בידי אדם\u0004 שאם עבר במזיד וחילל שבת — נדון למיתה בבית דין, \u0003וזה\u0004 (יום הכיפורים) \u0003זדונו בהכרת\u0004 בידי שמים. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי ר' חנניא בן גמליאל, שאדם שלקה נפטר מן הכרת — \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 גם שבת וגם יום הכיפורים, \u0003בידי אדם הוא,\u0004 שהרי גם ביום הכיפורים, כיון שיש בו עונש כרת — לוקה בידי אדם. משמע ממשנה זו איפוא שחולקים חכמים על ר' חנניה בן גמליאל.","\u0003רב נחמן בר יצחק אומר:\u0004 אין זו הוכחה, שכן אפשר לומר, \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 ששנינו כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' יצחק היא,\u0004 ש\u0003אומר: מלקות בחייבי כריתות ליכא\u0004 \u0005[אין],\u0006 ולכן אין זדונו של יום הכיפורים בידי אדם, אלא רק בידי שמים, בכרת. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יצחק אומר:\u0004 כל \u0003חייבי כריתות בכלל\u0004 אחד \u0003היו,\u0004 שנאמר בסיום פרשת העריות שיש בכולן עונש כרת (ויקרא יח, כט), \u0003ו\u0004אם כן \u0003למה יצאת כרת באחותו\u0004 שחוזר הכתוב ומפרש שיש בכך עונש כרת (ויקראד כ, יז) — כדי ללמד: \u0003לדונו בכרת\u0004 דווקא \u0003ולא במלקות,\u0004 ומכאן למד לכל חייבי הכרת שאינם לוקים. אבל חכמים אחרים אינם מסכימים לכך (ראה לעיל מכות יג,ב).","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנה זו במסכת מגילה היא כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שיש מלקות בחייבי כריתות — גם אז אין זו הוכחה שחולקים על ר' חנניה בן גמליאל, כי יש לפרש משנה זו כך: \u0003זה\u0004 בחילול שבת — \u0003עיקר\u0004 העונש על \u0003זדונו בידי אדם, וזה\u0004 ביום הכיפורים \u0003עיקר זדונו בידי שמים,\u0004 שהרי עיקר העונש וחומרתו היא דווקא בכרת, למרות שהוא יכול ללקות ולהיפטר על ידי כך מעונש הכרת.","\u0003אמר רב אדא בר אהבה אמר רב: הלכה כר' חנניא בן גמליאל\u0004 שכיון שלקה אינו נענש עוד בדיני שמים. \u0003אמר רב יוסף\u0004 בתמיהה: \u0003מאן סליק לעילא ואתא\u0004 \u0005[מי עלה למעלה ובא]\u0006 \u0003ואמר\u0004 שמשמים פוטרים אותו מן הכרת?! הרי דבר זה אינו תלוי בהכרעת בני אדם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא,\u0004 לטעמך, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' יהושע בן לוי: שלשה דברים עשו בית דין של מטה והסכימו בית דין של מעלה על ידם,\u0004 גם כן אפשר לשאול: \u0003מאן סליק לעילא ואתא\u0004 \u0005[מי עלה למעלה ובא]\u0006 \u0003ואמר\u0004 שכך הוא? \u0003אלא\u0004 צריך אתה לומר שלדברי ר' יהושע בן לוי \u0003קראי קא דרשינן\u0004 \u0005[מקראות אנו דורשים]\u0006 ומשם אנו למדים, \u0003הכא נמי קראי קא דרשינן\u0004 \u0005[כאן גם כן מקראות אנו דורשים].\u0006","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהזכרנו. \u0003אמר ר' יהושע בן לוי: שלשה דברים עשו בית דין של מטה והסכימו בית דין של מעלה על ידם, [אלו הן]: מקרא מגילה\u0004 בפורים, \u0003ושאילת שלום [בשם],\u0004 שהשואל בשלום חבירו מזכיר שם שמים בנוסח הברכה, \u0003והבאת מעשר\u0004 לבית האוצר שבירושלים. ומנין שהסכימו על ידם משמים?","\u0003מקרא מגילה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"קימו וקבלו היהודים\"\u0004 (אסתר ט, כז), ודי היה לומר \"קבלו\", אלא יש להבינו כך: \u0003קיימו\u0004 (הסכימו) \u0003למעלה\u0004 בשמים \u0003מה שקבלו\u0004 עליהם ישראל \u0003למטה.\u0004","\u0003ושאילת שלום\u0004 בשם — כמו ששנינו במשנה במסכת ברכות, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והנה בעז בא מבית לחם ויאמר לקוצרים ה' עמכם\"\u0004 (רות ב, ד), הרי שברכם בשם ה', \u0003ואומר\u0004 בפסוק אחר, בדברי המלאך לגדעון \u0003\"ה' עמך גבור החיל\"\u0004 (שופטים ו, יב). ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 הצורך ב\u0003\"ואומר\",\u0004 ומדוע אין להוכיח מדברי בועז בלבד? והסבירו שיש בראיה השניה תשובה לשאלה על הראיה הראשונה: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003בועז הוא דעביד מדעתיה\u0004 \u0005[שעשה מדעתו]\u0006 שבירך בשם, \u0003ומשמיא\u0004 \u0005[ומשמים]\u0006 \u0003לא אסכימו\u0004 \u0005[הסכימו]\u0006 \u0003על ידו\u0004 — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003ואומר \"ה' עמך גבור החיל\"\u0004 שאמר כך גם המלאך לגדעון, משמע שגם משמים הסכימו שכך יש לומר בברכה שמברכים זה את זה.","\u0003הבאת מעשר,\u0004 מנין שהסכימו משמים לכך — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי הנביא \u0003\"הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת אמר ה' צבאות אם לא אפתח לכם את ארבות השמים והריקתי לכם ברכה עד בלי די\"\u0004 (מלאכי ג, י). הרי שמשמים הסכימו על הבאת המעשרות אל בית האוצר. אגב כך שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד בלי די\"\u0004 האמור שם? \u0003אמר רמי בר רב: עד שיבלו\u0004 (\"בלי\") \u0003שפתותיכם מלומר \"די\",\u0004 שיהא מרובה שפע הברכה עד כדי כך.","מאמר דומה \u0003אמר ר' אלעזר: בשלשה מקומות הופיע\u0004 (התגלתה לכל) \u0003רוח הקודש\u0004 להודיע שמה שנעשה היה נכון ואמיתי. \u0003בבית דינו של שם, ובבית דינו של שמואל הרמתי, ובבית דינו של שלמה.\u0004 ופרטי הדברים: \u0003בבית דינו של שם\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במעשה יהודה ותמר \u0003\"ויכר יהודה ויאמר צדקה ממני\"\u0004 (בראשית לח, כו), ויש לשאול: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003ידע\u0004 שבאמת תמר צודקת והיא הרתה לו? \u0003דלמא כי היכי דאזל איהו לגבה אזל נמי אינש אחרינא [לגבה]\u0004 \u0005[שמא כמו שהלך הוא אצלה הלך גם איש אחר אצלה],\u0006 ושמא ההריון איננו ממנו, וזונה היא! אלא \u0003יצאת בת קול ואמרה: ממני יצאו כבושים\u0004 (סודות). כלומר, ה' מעיד שכך היה הדבר וממנו יצא הדבר, שיזכו לזרע.","\u0003בבית דינו של שמואל\u0004 היתה התגלות — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"הנני ענו בי נגד ה' ונגד משיחו את שור מי לקחתי... ויאמרו לא עשקתנו ולא רצותנו... ויאמר עד ה' ועד משיחו כי לא מצאתם בידי מאומה ויאמר עד\"\u0004 (שמואל א יב, ג— ה). ולכאורה מדוע נאמר \u0003\"ויאמר\u0004 עד\"? \u0003\"ויאמרו\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי כפשוטו היתה זו תשובת כל ישראל, שאומרים הם: עדים אנחנו בדבר זה! אלא הכוונה היא: \u0003יצאת בת קול ואמרה\u0004 בשם ה': \u0003אני עד בדבר זה.\u0004","\u0003בבית דינו של שלמה\u0004 הופיעה רוח הקודש, במשפט שתי הנשים הזונות אודות הבן החי — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויען המלך ויאמר תנו לה את הילד החי והמת לא תמיתהו (כי) היא אמו\"\u0004 (מלכים א ג, כז), ויש לשאול: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003ידע? דלמא איערומא מיערמא\u0004 \u0005[שמא\u0006 היא \u0005הערימה]\u0006 בכך, ואין היא באמת אמו של הילד החי? אלא \u0003יצאת בת קול ואמרה: היא אמו.\u0004","\u0003אמר רבא: ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח? בכל אלה אין ראיה גמורה. \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003יהודה, כיון דחשיב ירחי ויומי\u0004 \u0005[\u0006כיון \u0005שחישב את החדשים והימים]\u0006 מאז שבא אל תמר, \u0003ואיתרמי\u0004 \u0005[והזדמן]\u0006 שהיה משך הריונה תואם לזמן שבא אליה, הבין שהיא צודקת. ולא היה מקום לחשוד באחר, \u0003דחזינן\u0004 — \u0003מחזקינן, דלא חזינן\u0004 — \u0003לא מחזקינן\u0004 \u0005[\u0006כי \u0005מה שראינו\u0006 ואנו יודעים — \u0005אנו מחזיקים, מה שלא ראינו\u0006 — \u0005אין אנו מחזיקים].\u0006","ולענין \u0003שמואל נמי\u0004 \u0005[גם כן],\u0006 אפשר לומר כי \u0003כולהו\u0004 \u0005[כל]\u0006 \u0003ישראל קרי להו\u0004 \u0005[קורא להם]\u0006 \u0003בלשון יחידי, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ישראל נושע בה'\"\u0004 (ישעיה ה, יז), הרי שעל עם ישראל מדבר בלשון יחיד.","ולענין \u0003שלמה נמי\u0004 \u0005[גם כן]\u0006 אפשר לומר שסברה היא: \u0003מדהא קא מרחמתא והא לא קא מרחמתא\u0004 \u0005[מפני שזו מרחמת וזו אינה מרחמת]\u0006 ניכר שזו אמו וזו אינה אמו! \u0003אלא\u0004 יש לומר כי לא מן הכתובים אנו למדים שיצאה באותם מקומות בת קול, \u0003אלא גמרא\u0004 \u0005[מסורת]\u0006 היא בידינו, שכך היה הדבר.","\u0003דרש ר' שמלאי: שש מאות ושלש עשרה מצות נאמרו לו למשה\u0004 בתורה, והן כוללות \u0003שלש מאות וששים וחמש לאוין\u0004 (מצוות לא תעשה) \u0003כמנין ימות החמה, ומאתים וארבעים ושמונה\u0004 מצוות \u0003עשה, כנגד איבריו של אדם\u0004 שהם כמספר זה. \u0003אמר רב המנונא: מאי קרא\u0004 \u0005[מה המקרא]\u0006 המרמז על כך — שנאמר \u0003\"תורה צוה לנו משה מורשה\u0004 קהלת יעקב\" (דברים לג, ד). \u0003\"תורה\" בגימטריא\u0004 (בחשבון האותיות) ל"],["\u0003שית מאה וחד סרי הוי\u0004 \u0005[שש מאות ואחת עשרה הן],\u0006 שאותן קיבלנו מפי משה רבינו, ועוד: \u0003\"אנכי\u0004 ה' אלקיך\" ו\u0003\"לא יהיה לך\"\u0004 (שמות כ, ב— ג) שהן שתי הדברות הראשונות — \u0003מפי הגבורה\u0004 (מפי ה' עצמו) \u0003שמענום,\u0004 הרי מנין שש מאות ושלש עשרה.","\u0003(סימן דמשמ\"ק ס\"ק).\u0004","ודרש ר' שמלאי עוד ש\u0003בא דוד\u0004 המלך \u0003והעמידן\u0004 את תרי\"ג המצוות \u0003על אחת עשרה\u0004 מצוות, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"מזמור לדוד [ה'] מי יגור באהלך מי ישכן בהר קדשך. הולך תמים ופועל צדק ודבר אמת בלבבו. לא רגל על לשנו לא עשה לרעהו רעה וחרפה לא נשא על קרבו. נבזה בעיניו נמאס ואת יראי ה' יכבד נשבע להרע ולא ימר. כספו לא נתן בנשך ושחד על נקי לא לקח עשה אלה לא ימוט לעולם\"\u0004 (תהלים פרק טו), ומנויות פה אחת עשרה מידות שבזכותן זוכה אדם לחיי העולם.","ומפרטים: \u0003\"הולך תמים\"\u0004 — \u0003זה\u0004 הנוהג כ\u0003אברהם,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו באברהם \u0003\"התהלך לפני והיה תמים\"\u0004 (בראשית יז, א).","\u0003\"פועל צדק\"\u0004 — \u0003כגון אבא חלקיהו,\u0004 שעבד כפועל ולא ביטל ממלאכתו אפילו כדי לומר \"שלום\", שהוא פועל צדק.","\u0003\"ודובר אמת בלבבו\"\u0004 — \u0003כגון רב ספרא,\u0004 שבא אליו אדם לקנות דבר בשעה שהיה קורא קריאת שמע, והוא הסכים להצעה בלבו אלא שלא יכול היה לדבר בשפתיו. ואותו אדם חשב שרב ספרא אינו מרוצה במחיר והוסיף עליו, אבל רב ספרא מכר לו כפי שקיבל עליו מתחילה בלבו.","\u0003\"לא רגל על לשנו\"\u0004 — \u0003זה יעקב אבינו,\u0004 שלא רצה להטעות את אביו, כדי לקבל את הברכות, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אולי ימשני אבי והייתי בעיניו כמתעתע\"\u0004 (בראשית כז, יב).","\u0003\"לא עשה לרעהו רעה\"\u0004 — הכוונה היא לאדם \u0003שלא ירד לאומנות חבירו\u0004 להתחרות בו שלא כדין.","\u0003\"וחרפה לא נשא על קרבו\"\u0004 — \u0003זה המקרב את קרוביו,\u0004 ואינו מרחקם מפני שמתבייש בהם.","\u0003\"נבזה בעיניו נמאס\"\u0004 — \u0003זה חזקיהו המלך שגירר עצמות אביו\u0004 הרשע, אחז, \u0003במטה של חבלים\u0004 כשהביאו לקבורה, שנבזה בעיניו היה מי שנמאס לה'.","\u0003\"ואת יראי ה' יכבד\"\u0004 — \u0003זה יהושפט מלך יהודה, שבשעה שהיה רואה תלמיד חכם היה עומד מכסאו ומחבקו ומנשקו, וקורא לו \"אבי אבי, רבי רבי, מרי\u0004 (אדוני) \u0003מרי\".\u0004","\u0003\"נשבע להרע ולא ימר\"\u0004 — \u0003כ\u0004דברי \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן\u0004 בלשון נדר, כשהיה רוצה להימנע מלאכול אצל מישהו: \u0003אהא בתענית עד שאבא לביתי\u0004 וכך היה מקיים, אף שמתחילה לא אמר אלא כדי שלא לאכול שם.","\u0003\"כספו לא נתן בנשך\"\u0004 — כוונתו \u0003אפילו ברבית\u0004 ל\u0003גוי,\u0004 שהיא מותרת מן הדין, והוא מחמיר על עצמו לא לקחת כלל.","\u0003\"ושחד על נקי לא לקח\"\u0004 — \u0003כגון ר' ישמעאל בר' יוסי\u0004 שאריסו הביא לו סלסלת פירות, כדרכו, וסירב לדונו, שמא יטה לבו לזכותו.","ובסוף כל זה \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"עשה אלה לא ימוט לעולם\"\u0004 (תהילים טו, ה). מספרים, \u0003כשהיה רבן גמליאל מגיע למקרא הזה היה בוכה, אמר: מאן דעביד להו לכולהו\u0004 \u0005[מי שעושה את\u0006 כל אלה \u0005כולם]\u0006 \u0003הוא\u0004 ש\u0003לא ימוט, הא\u0004 \u0005[אבל]\u0006 אם עושה רק \u0003חדא מינייהו\u0004 \u0005[אחת מהן] —\u0006 \u0003ימוט.\u0004","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"עשה כל אלה\"? \"עשה אלה\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003אפילו בחדא מינייהו\u0004 \u0005[באחת מהן]\u0006 גם כן זוכה. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר\u0006 ותפרש \u0005כך],\u0006 הרי \u0003כתיב קרא אחרינא\u0004 \u0005[נאמר כתוב אחר]\u0006 לגבי העבירות החמורות שעונשן כרת \u0003\"אל תטמאו בכל אלה\"\u0004 (ויקרא יח, כד), האם \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 תאמר שהכוונה היא \u0003הנוגע\u0004 (הנטמא) \u0003בכל אלה הוא\u0004 ש\u0003מטמא, בחדא מינייהו\u0004 \u0005[באחת מהן]\u0006 \u0003לא? אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה, כשהוא אומר \"בכל אלה\" — \u0003באחת מכל אלה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ב\u0004עושה \u0003אחת מכל אלו,\u0004 שלא ימוט לעולם.","ובהמשך דרשת ר' שמלאי נאמר: \u0003בא ישעיהו והעמידן על שש, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"הלך צדקות ודבר מישרים מאס בבצע מעשקות נער כפיו מתמך בשחד אטם אזנו משמע דמים ועצם עיניו מראות ברע\"\u0004 (ישעיה לג, טו).","ומפרטים: \u0003\"הלך צדקות\"\u0004 — \u0003זה\u0004 הנוהג כ\u0003אברהם אבינו, דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"כי ידעתיו למען אשר יצוה\u0004 את בניו... לעשות צדקה ומשפט\" (בראשית יח, יט).","\u0003\"ודבר מישרים\"\u0004 — \u0003זה שאינו מקניט\u0004 (מעליב) \u0003פני חבירו ברבים.\u0004","\u0003\"מאס בבצע מעשקות\"\u0004 — \u0003כגון ר' ישמעאל בן אלישע,\u0004 שאחר שקיבל מתנות כהונה מאדם — סירב לדונו, מחשש שוחד.","\u0003\"נער כפיו מתמך בשחד\" —\u0004 \u0003כגון ר' ישמעאל בר' יוסי,\u0004 כמסופר לעיל.","\u0003\"אטם אזנו משמע דמים\"\u0004 כוונתו: זה \u0003דלא שמע בזילותא דצורבא מרבנן ושתיק\u0004 \u0005[שאינו שומע בזלזולו של תלמיד חכם, ושותק],\u0006 \u0003כגון ר' אלעזר בר' שמעון\u0004 שהיה מקפיד בדבר זה.","\u0003\"ועצם עיניו מראות ברע\"\u0004 — \u0003כ\u0004דברי \u0003ר' חייא בר אבא\u0004 על פסוק זה. ש\u0003אמר ר' חייא בר אבא:\u0004 \"עוצם עיניו מראות ברע\" — \u0003זה שאינו מסתכל בנשים בשעה שעומדות על הכביסה\u0004 בנהר ומרימות את בגדיהן, כדי שלא להירטב, ומתוך כך נחשף חלק מגופן.","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באדם כזה המקיים את האמור לעיל: \u0003\"הוא מרומים ישכון\u0004 מצדות סלעים משגבו לחמו ניתן מימיו נאמנים\" (ישעיה לג, טז).","\u0003בא מיכה והעמידן\u0004 את המצוות \u0003על שלש, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"הגיד לך אדם מה טוב ומה ה' דורש ממך כי אם עשות משפט ואהבת חסד והצנע לכת עם (ה') אלהיך\"\u0004 (מיכה ו, ח).","ומסבירים: \u0003\"עשות משפט\"\u0004 — \u0003זה הדין,\u0004 כלומר שצריך לנהוג על פי מידת הדין, \u0003\"אהבת חסד\"\u0004 — \u0003זה גמילות חסדים, \"הצנע לכת\"\u0004 — \u0003זה\u0004 רמז למצוות שנעשות בכעין תהלוכה, כגון \u0003הוצאת המת והכנסת כלה.\u0004 ומעירים: \u0003והלא דברים קל וחומר, ומה דברים\u0004 כהוצאת המת או הכנסת כלה \u0003שאין דרכן לעשותן בצנעא,\u0004 שהרי הם דברים פומביים — \u0003אמרה תורה \"והצנע לכת\",\u0004 שמי שמתעסק בזה צריך לעשות בצניעות, \u0003דברים שדרכם לעשותם בצנעא\u0004 כגון מתן צדקה לנזקקים — \u0003על אחת כמה וכמה!\u0004","\u0003חזר ישעיהו והעמידן\u0004 את המצוות \u0003על שתים, שנאמר \"כה אמר ה' שמרו משפט ועשו צדקה\"\u0004 (ישעיה נו, א). \u0003בא עמוס והעמידן על אחת, שנאמר\u0004 \"כי \u0003כה אמר ה' לבית ישראל דרשוני וחיו\"\u0004 (עמוס ה, ד). \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן בר יצחק:\u0004 אין זה מעמיד את כל המצוות על אחת, כי \u0003אימא\u0004 \u0005[אמור,\u0006 פרש\u0005]:\u0006 \u0003דרשוני בכל התורה\u0004 שהרי אין מפורש במה לדרוש! \u0003אלא\u0004 כך יש לומר: \u0003בא חבקוק והעמידן על אחת, שנאמר \"וצדיק באמונתו יחיה\"\u0004 (חבקוק ב, ד).","\u0003אמר ר' יוסי בר חנינא: ארבע גזירות גזר משה רבינו על ישראל, באו ארבעה נביאים וביטלום. משה אמר \"וישכן ישראל בטח בדד עין יעקב\"\u0004 (דברים לג, כח), ומובן הדברים שישכון עם ישראל לבטח, רק כאשר יהיה במדרגה מעין יעקב אבינו — \u0003בא עמוס וביטלה, [שנאמר] \"חדל נא מי יקום יעקב\u0004 כי קטון הוא\" (עמוס ז, ה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך \u0003\"נחם ה' על זאת\u0004 גם היא לא תהיה אמר ה' \" (עמוס ז, ו).","\u0003משה אמר \"ובגוים ההם לא תרגיע\"\u0004 (דברים כח, סה) — \u0003בא ירמיה ואמר \"הלוך להרגיעו ישראל\"\u0004 (ירמיה לא, א) גם בהיותם בגלות.","\u0003משה אמר \"פקד עון אבות על בנים\"\u0004 (שמות לד, ז) — \u0003בא יחזקאל וביטלה,\u0004 שאמר \u0003\"הנפש החטאת היא תמות\"\u0004 (יחזקאל יח, ד) ולא ישאו בנים בעוון אבותיהם.","\u0003משה אמר \"ואבדתם בגוים\"\u0004 (ויקרא כו, לח) — \u0003בא ישעיהו ואמר \"והיה ביום ההוא יתקע בשופר גדול\u0004 ובאו האובדים מארץ אשור...\" (ישעיה כז, יג).","\u0003אמר רב: מסתפינא מהאי קרא\u0004 \u0005[מפחד אני מפסוק זה]\u0006 שנאמר \u0003\"ואבדתם בגוים\". מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא \u0003כאבידה המתבקשת,\u0004 שבעליה מחפש אותה, וכך ה' ישיב אבידה זו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"תעיתי כשה אבד בקש עבדך\"\u0004 (תהלים קיט, קעו)! \u0003אלא מסיפא [דקרא]\u0004 \u0005[מסופו של\u0006 אותו \u0005הפסוק]\u0006 חשש רב, ממה שנאמר \u0003\"ואכלה אתכם ארץ איביכם\". מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא:\u0004 גם שם אפשר לומר \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003כאכילת קישואין ודילועין,\u0004 שאין אוכלים אותם בשלמות ומשאירים מהם מקצת, וזרעיהם צומחים.","באותם עניינים של יסורי הגלות ותקוות הגאולה מספרים, \u0003וכבר היה רבן גמליאל ור' אלעזר בן עזריה ור' יהושע ור' עקיבא מהלכין בדרך\u0004 במלכות רומי, \u0003ושמעו קול המונה של רומי מפלטה [ברחוק] מאה ועשרים מיל,\u0004 שהעיר היתה גדולה כל כך עד ששמעו את רעשי העיר ממרחק עצום, \u0003והתחילו\u0004 חכמים אלה \u0003בוכין, ו\u0004אילו \u0003ר' עקיבא\u0004 היה \u0003משחק\u0004 (צוחק). \u0003אמרו לו: מפני מה אתה משחק? אמר להם: ואתם מפני מה אתם בוכים? אמרו לו: הללו גוים שמשתחוים לעצבים\u0004 (לאלילים) \u0003ומקטרים לעבודה זרה יושבין בטח והשקט\u0004 בעיר עצומה זו, \u0003ואנו, בית הדום רגלי אלהינו\u0004 (בית המקדש) \u0003שרוף\u0004"],["\u0003באש, ולא נבכה?! אמר להן: לכך\u0004 (משום כך) \u0003אני מצחק, ומה לעוברי רצונו\u0004 (רשעים), עושה ה' \u0003כך,\u0004 ומשלם להם מקצת טובות שעשו — \u0003לעושי רצונו על אחת כמה וכמה\u0004 שישלם.","ועוד מסופר, \u0003שוב פעם אחת היו\u0004 אותם חכמים \u0003עולין לירושלים\u0004 לאחר חורבן הבית, \u0003כיון שהגיעו להר הצופים\u0004 וראו משם את מקום המקדש \u0003קרעו בגדיהם\u0004 כדין, \u0003כיון שהגיעו להר הבית ראו שועל שיצא מ\u0004מקום \u0003בית קדשי הקדשים, התחילו הן בוכין ור' עקיבא מצחק. אמרו לו: מפני מה אתה מצחק? אמר להם: מפני מה אתם בוכים? אמרו לו: מקום\u0004 זה \u0003שכתוב בו \"והזר הקרב יומת\"\u0004 (במדבר א, נא), \u0003ועכשיו שועלים הלכו בו, ולא נבכה?!\u0004","\u0003אמר להן: לכך\u0004 (משום כך) \u0003אני מצחק, דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי ה' לישעיהו, כאשר גילה לו על העתיד: \u0003\"ואעידה לי עדים נאמנים את אוריה הכהן ואת זכריה בן יברכיהו\"\u0004 (ישעיה ח, ב), \u0003וכי מה ענין אוריה אצל זכריה?\u0004 והלא \u0003אוריה\u0004 היה נביא \u0003ב\u0004זמן בית \u0003מקדש ראשון, וזכריה במקדש שני,\u0004 שהיה בין עולי בבל! \u0003אלא\u0004 הכוונה היא: \u0003תלה הכתוב נבואתו של זכריה בנבואתו של אוריה,\u0004","\u0003באוריה כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"לכן בגללכם ציון שדה תחרש\u0004 וירושלים עיין תהיה והר הבית לבמות יער\" (מיכה ג, יב) ובאלה מצויים שועלים, שמסורת היתה בידם שכך ניבא אוריה, \u0003בזכריה כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"עוד ישבו זקנים וזקנות ברחבות ירושלם\"\u0004 (זכריה ח, ד). \u0003עד שלא נתקיימה נבואתו של אוריה\u0004 על חורבן העיר \u0003הייתי מתיירא שלא תתקיים\u0004 גם \u0003נבואתו של זכריה,\u0004 שהרי הן תלויות, כאמור, זו בזו. \u0003עכשיו שנתקיימה נבואתו של אוריה\u0004 — \u0003בידוע שנבואתו של זכריה מתקיימת.\u0004 ומספרים: \u0003בלשון הזה אמרו לו: עקיבא ניחמתנו, עקיבא ניחמתנו.\u0004",""]]};
